KB.add({"board":"05","title":"书画、戏曲与音乐","note":"交大考过：楷书四大家（2024名解）、《清明上河图》《步辇图》（2025名解，同组）、四大名旦（2023名解）、篆隶行楷排序（2020选择）、《黄河大合唱》（2026选择，见板块08）。书画题的核心是“作者—作品—朝代”三项对应。","clusters":[{"cid":"05a","name":"汉字书体演变与文房","line":"按时间排：商甲骨文、商周金文、大篆（含石鼓文）、秦小篆（李斯统一文字）、隶书（隶变是古今文字分界）、汉末出现楷书，草书、行书与楷书交错发展；书写工具是笔墨纸砚文房四宝，篆刻是书法的旁支。"},{"cid":"05b","name":"书法名家：从钟王到楷书四大家与宋四家","line":"魏钟繇为楷书鼻祖，东晋王羲之“书圣”与王献之合称“二王”；唐代初唐四家、颜筋柳骨，张旭怀素“颠张醉素”写狂草；宋代尚意，苏黄米蔡为宋四家，宋徽宗创瘦金体；元赵孟頫与欧颜柳并称楷书四大家；三大行书串起王、颜、苏三人。"},{"cid":"05c","name":"魏晋至五代绘画：人物画为主","line":"东晋顾恺之“以形写神”，《洛神赋图》《女史箴图》；南齐谢赫提出“六法”；唐代阎立本《步辇图》、吴道子“画圣”、韩滉《五牛图》、张萱周昉仕女画；五代顾闳中《韩熙载夜宴图》，荆关董巨奠定山水画南北两派。"},{"cid":"05d","name":"宋元明清绘画：山水、文人画与流派","line":"北宋山水三大家与张择端《清明上河图》、王希孟《千里江山图》，宋徽宗画院；南宋四家“马一角夏半边”；元四家以黄公望《富春山居图》为代表，文人画成熟；明代吴门四家与徐渭大写意，董其昌提出南北宗论；清代四王摹古、四僧创新，扬州八怪写意花鸟，郎世宁中西合璧。"},{"cid":"05e","name":"近现代美术","line":"清末民初上海形成海派（吴昌硕、任伯年），广东出岭南画派；20世纪齐白石、张大千“南张北齐”，徐悲鸿以西法改良中国画；新中国有《江山如此多娇》《开国大典》等主题美术。"},{"cid":"05f","name":"中国音乐：律吕、乐器、古曲与近现代作品","line":"古代以五音、八音、十二律为理论基础，曾侯乙编钟是实物证据；古琴与十大古曲承载文人传统（《高山流水》《广陵散》）；近现代有学堂乐歌、阿炳《二泉映月》、聂耳与冼星海、《梁祝》，民歌与少数民族音乐多项列入人类非遗。"},{"cid":"05g","name":"乐舞：从周代六舞到敦煌飞天","line":"周代“六代乐舞”是礼乐制度的一部分；汉代百戏；唐代乐舞最盛，唐玄宗设梨园，《霓裳羽衣舞》《秦王破阵乐》、胡旋舞、剑器舞；敦煌壁画飞天启发了现代舞剧《丝路花雨》；当代有《东方红》与民族民间舞。"},{"cid":"05h","name":"戏曲：从四大声腔、昆曲到京剧与地方戏","line":"明代南戏四大声腔中昆山腔经魏良辅改为“水磨调”，昆曲称“百戏之祖”；清乾隆年间花雅之争，1790年四大徽班进京，融合汉调形成皮黄腔京剧；京剧有生旦净丑行当、四功五法，名角有四大名旦、四大须生，梅兰芳体系与斯坦尼、布莱希特并称；另有越剧、黄梅戏、评剧、豫剧等地方戏与曲艺、皮影。"},{"cid":"05i","name":"古代建筑与园林","line":"木构建筑以斗拱榫卯为核心，屋顶有严格等级（重檐庑殿最高，如太和殿）；北宋李诫《营造法式》是官方规范，梁思成林徽因用现代方法研究古建；现存实例有唐代南禅寺、佛光寺，辽代应县木塔，隋代赵州桥等四大古桥；园林以苏州古典园林为代表，明末计成《园冶》“虽由人作，宛自天开”；民居各具地域特色。"}],"entries":[{"id":"b05-005","t":"汉字书体演变","cid":"05a","p":1,"kind":"概念","exam":["2020选择"],"alias":["书体演变","汉字字体演变"],"one":"甲骨文、金文、大篆、小篆、隶书、楷书，草书与行书穿插其间。","ans":"汉字书体演变指**汉字从甲骨文发展到楷书、行书的字形变化过程**。主线按时间排：**商代甲骨文，商周金文，大篆，秦代小篆，隶书，汉末出现的楷书**，魏晋以后楷书成熟。草书起于汉代，行书兴起于汉末，二者与隶书、楷书交错发展。秦统一后以**小篆**为标准字体，**隶书**经“隶变”使汉字由古文字转入今文字，成为字形演变的转折点。**楷书**笔画规整，沿用至今，是现代汉字的直接来源。","pts":["甲骨文、金文、大篆、小篆、隶书、楷书","隶变是古今文字分界","草书汉代、行书汉末，与楷书交错发展"],"mem":"按字形变化记：篆是圆转的线条，隶把圆线拆成方折的笔画，楷把笔画写端正，行是楷书写快了的样子。口诀“篆隶楷行”，前面再加“甲金”两个起点：甲金篆隶楷行。2020 届排序题的陷阱在“楷”与“行”：行书是楷书的快写，所以排在楷后。","mix":"草书出现得比楷书早（汉代），但通行排序题按“篆隶楷行”，不要因为草书早就把行、草提前；大篆和小篆也不能颠倒，小篆是秦统一文字后的规范字体。","mcq":[{"q":"下列书体按产生先后排列，正确的是","o":["篆书、隶书、行书、楷书","隶书、篆书、楷书、行书","行书、楷书、篆书、隶书","篆书、隶书、楷书、行书"],"a":3,"w":"通行排序为篆、隶、楷、行，2020 届考过。"},{"q":"秦统一六国后作为标准文字推行的书体是","o":["小篆","楷书","隶书","大篆"],"a":0,"w":"李斯等整理小篆，作为全国统一字体。"}],"rel":[{"t":"隶书与“隶变”","n":"古今文字分界"},{"t":"甲骨文","n":"最早成体系文字"},{"t":"大篆、小篆与石鼓文","n":"篆书两阶段"},{"t":"楷书四大家","n":"楷书最高成就"},{"t":"草书：章草、今草、狂草","n":"草书的三种形态"}],"more":"书体顺序：甲骨文（商）→金文（商周）→大篆→小篆（秦）→隶书（秦汉）→楷书（汉末至魏晋）。\n草书（汉）、行书（汉末）与楷书前后发展。"},{"id":"b05-027","t":"文房四宝","cid":"05a","p":2,"kind":"合称","alias":["文房四宝","笔墨纸砚"],"one":"笔、墨、纸、砚，名品为湖笔、徽墨、宣纸、端砚。","ans":"文房四宝指中国传统书写绘画所用的**笔、墨、纸、砚**四种工具，是文人书斋的基本用具。四者各有名品：**湖笔**产于浙江湖州，**徽墨**产于安徽徽州，**宣纸**产于安徽泾县，**端砚**产于广东肇庆（古称端州）。端砚与歙砚、洮砚、澄泥砚合称四大名砚，“中国宣纸传统制作技艺”于2009年列入联合国教科文组织人类非遗名录。","pts":["笔墨纸砚四种书画工具","湖笔、徽墨、宣纸、端砚","宣纸技艺2009年入人类非遗"],"members":[["笔","湖笔，浙江湖州善琏"],["墨","徽墨，安徽徽州（歙县、休宁）"],["纸","宣纸，安徽泾县"],["砚","端砚，广东肇庆；另有歙砚、洮砚、澄泥砚"]],"mem":"产地口诀：**湖徽宣端**，与“笔墨纸砚”一一对应。再记省份：浙、皖、皖、粤，两样出在安徽，唯一的广东是砚台。","mix":"四大名砚是端、歙、洮、澄泥，与“文房四宝”里的端砚不是一组概念；宣纸因泾县历属宣州府得名，墨和纸同在安徽，常被混淆产地。","mcq":[{"q":"“文房四宝”中，名品“宣纸”的产地是","o":["浙江湖州","广东肇庆","安徽泾县","甘肃临洮"],"a":2,"w":"宣纸产于安徽泾县；湖州出湖笔，肇庆出端砚，临洮出洮砚。"}],"rel":[{"t":"四大名砚","n":"砚中四种名品"},{"t":"宣纸","n":"四宝中的纸"},{"t":"造纸术","n":"四大发明之一"},{"t":"文人四艺（琴棋书画）","n":"文人书斋并提"}],"more":"2009年：中国宣纸传统制作技艺列入人类非遗代表作名录。","exam":[]},{"id":"b05-028","t":"“飞白书”","cid":"05a","p":2,"kind":"概念","alias":["飞白书","飞白"],"one":"东汉蔡邕所创，笔画中丝丝露白的书体。","ans":"飞白书是**东汉蔡邕所创**的一种特殊书法技法，书写时笔画中留有丝丝露白，似用枯笔扫出，故名“飞白”。相传蔡邕在鸿都门见工匠用扫帚蘸白粉刷墙，受到启发而创此体。它属于**装饰性的书写风格**，多用于题写宫殿匾额，后世王羲之、唐太宗等人皆善飞白。飞白体现了汉字书法对**用笔虚实、墨色枯润**的追求，丰富了书法的表现手法。","pts":["东汉蔡邕所创","笔画中丝丝露白","多用于题署匾额"],"mem":"画面记忆：工匠拿**扫帚刷墙**，白粉刷出一道道缝隙，蔡邕看了顿悟，把这种“飞”起来的“白”写进字里。名字本身就是释义：飞，是笔势飞动；白，是纸色露出。","mix":"飞白是笔法，不是独立书体，不要与篆、隶、楷、行、草五体并列；创始人是蔡邕，不是王羲之。","mcq":[{"q":"相传创造“飞白书”的书法家是","o":["蔡邕","张芝","钟繇","王羲之"],"a":0,"w":"飞白书为东汉蔡邕所创；张芝以草书著称，钟繇为楷书鼻祖。"}],"rel":[{"t":"蔡邕","n":"飞白书的创始人"},{"t":"王羲之","n":"后世善飞白"},{"t":"汉字书体演变","n":"书体总线索"}],"more":"蔡邕（133–192），东汉文学家、书法家，主持刻写《熹平石经》；其女蔡文姬。","exam":[]},{"id":"b05-001","t":"楷书四大家","cid":"05b","p":1,"kind":"合称","exam":["2024名解"],"alias":["欧颜柳赵","欧体颜体柳体赵体"],"one":"唐代欧阳询、颜真卿、柳公权与元代赵孟頫，三唐一元。","ans":"楷书四大家是**中国书法史上四位楷书代表人物的合称**，指**唐代欧阳询、颜真卿、柳公权和元代赵孟頫**，其书体分别称**欧体、颜体、柳体、赵体**。**欧体险劲严整，代表作《九成宫醴泉铭》；颜体雄浑饱满，代表作《多宝塔碑》；柳体骨力挺拔，代表作《玄秘塔碑》；赵体圆润秀丽，代表作《胆巴碑》**。“颜筋柳骨”概括颜、柳的风格。四家书体成为后世学习楷书的主要范本。","pts":["欧、颜、柳、赵，三唐一元","四体代表碑帖：九成宫、多宝塔、玄秘塔、胆巴碑","后世楷书范本，颜筋柳骨"],"members":[["欧阳询","唐初，欧体，《九成宫醴泉铭》"],["颜真卿","唐，颜体，《多宝塔碑》"],["柳公权","唐，柳体，《玄秘塔碑》"],["赵孟頫","元，赵体，《胆巴碑》"]],"mem":"口诀“欧颜柳赵”，也可记成“三唐一元”。碑名配字：欧阳询的《九成宫》像一座险峻的宫殿，颜真卿的《多宝塔》敦厚如塔，柳公权的《玄秘塔》清瘦如骨，赵孟頫的《胆巴碑》圆润。2024 届名解考的就是这一组。","mix":"王羲之是“书圣”，以行书著称，不在四大家内；欧阳询与虞世南、褚遂良、薛稷合称“初唐四家”，范围不同；颜真卿的行书《祭侄文稿》不是他楷书的代表作。另有说法以褚遂良、虞世南论楷书，但通行的楷书四大家为欧颜柳赵。","mcq":[{"q":"下列书法家中，不属于“楷书四大家”的是","o":["王羲之","欧阳询","柳公权","赵孟頫"],"a":0,"w":"四大家为欧阳询、颜真卿、柳公权、赵孟頫。"},{"q":"《玄秘塔碑》的书写者是","o":["柳公权","欧阳询","颜真卿","赵孟頫"],"a":0,"w":"柳体代表作，骨力挺拔。"}],"rel":[{"t":"颜真卿","n":"四大家之一"},{"t":"柳公权","n":"四大家之一，颜筋柳骨"},{"t":"欧阳询","n":"四大家之一"},{"t":"赵孟頫","n":"唯一的元代成员"},{"t":"初唐四家（书法）","n":"常混的另一组四家"}],"more":"颜筋柳骨：颜真卿丰腴有筋力，柳公权瘦劲见骨力。\n欧阳询《九成宫醴泉铭》作于唐贞观年间，被誉为“楷书极则”。"},{"id":"b05-006","t":"王羲之","cid":"05b","p":1,"kind":"人物","alias":["书圣","王右军","逸少"],"one":"东晋书法家，“书圣”，《兰亭集序》作者。","ans":"王羲之（303–361），字逸少，**东晋书法家**，官至右军将军，世称**王右军**，被尊为**“书圣”**。他兼擅各体，**变汉魏质朴书风为妍美流便的新体**，对行书和草书的成熟贡献最大。代表作**《兰亭集序》**作于永和九年（353 年），被称**“天下第一行书”**，另有《快雪时晴帖》《丧乱帖》《十七帖》。其子**王献之**与他并称**“二王”**。王羲之的书风影响此后一千多年的书法发展，是书法史上的标杆人物。","pts":["东晋书圣，官至右军将军","《兰亭集序》天下第一行书","与王献之并称二王"],"mem":"一句话链条：王羲之，住东晋，号书圣，官右军，写《兰亭》。画面记“东床快婿”：郗家选婿，唯有王羲之坦腹东床，所以又称“东床”。“二王”记成父子：父羲之、子献之，“小圣”献之排后。","mix":"生卒年另有 321–379 说，两说并存，通行用 303–361。书圣是王羲之，草圣是张旭；《兰亭集序》是行书，不是楷书；“天下第二行书”是颜真卿《祭侄文稿》。","mcq":[{"q":"被后世尊为“书圣”的书法家是","o":["王羲之","颜真卿","张旭","钟繇"],"a":0,"w":"王羲之为书圣；张旭为草圣；钟繇为楷书鼻祖。"},{"q":"下列关于王羲之的说法，正确的是","o":["是西晋书法家","与其子并称“二王”","作品《九成宫醴泉铭》","以楷书《多宝塔碑》闻名"],"a":1,"w":"与王献之并称二王；他是东晋人，代表作是《兰亭集序》。"}],"rel":[{"t":"《兰亭集序》","n":"代表作"},{"t":"王献之与“二王”","n":"其子，并称二王"},{"t":"天下三大行书","n":"位居第一"},{"t":"钟繇","n":"早于他的楷书鼻祖"},{"t":"书画称号：书圣、草圣、画圣","n":"书圣之称"}],"more":"作品：《兰亭集序》《快雪时晴帖》《丧乱帖》《十七帖》《黄庭经》（传）。\n名句：后之视今，亦犹今之视昔。｜《兰亭集序》\n死生亦大矣，岂不痛哉！｜《兰亭集序》\n《晋书》评其书：飘若游云，矫若惊龙。","exam":[]},{"id":"b05-010","t":"颜真卿","cid":"05b","p":1,"kind":"人物","alias":["颜鲁公","颜体","颜筋"],"one":"唐代书法家，颜体创立者，行书《祭侄文稿》天下第二行书。","ans":"颜真卿（709–784），字清臣，**唐代书法家**，官至太子太师，封鲁郡公，世称**颜鲁公**。安史之乱时他任平原太守起兵抗敌，忠烈之名与书名并传。楷书**创立颜体**，雄浑饱满，端庄大气，代表作**《多宝塔碑》《颜勤礼碑》**，与柳公权并称**“颜筋柳骨”**。行书**《祭侄文稿》**为悼念侄子颜季明所作，被称**“天下第二行书”**。他是**楷书四大家**之一，改变了初唐楷书的清瘦风格。","pts":["唐代书法家，颜体，雄浑饱满","《多宝塔碑》楷书，《祭侄文稿》行书","颜筋柳骨，天下第二行书"],"mem":"楷与行分开记：颜真卿“楷看《多宝塔》，行看《祭侄》”。颜体字肉多、横细竖粗，像一位体格魁梧的将军，所以说“颜筋”；柳体瘦硬见棱，说“柳骨”。《祭侄文稿》写于悲愤之中，涂改处很多，是情感先于技法的名作。","mix":"“天下第二行书”的《祭侄文稿》是行书，不是颜体楷书；“颜筋柳骨”里颜是筋、柳是骨，不要对调；天下第一行书是王羲之《兰亭集序》，第三是苏轼《黄州寒食诗帖》。","mcq":[{"q":"被称为“天下第二行书”的作品是","o":["《祭侄文稿》","《自叙帖》","《黄州寒食诗帖》","《兰亭集序》"],"a":0,"w":"颜真卿悼侄之作，位列三大行书第二。"},{"q":"“颜筋柳骨”中的“颜”指","o":["颜真卿","颜之推","颜延之","颜回"],"a":0,"w":"指唐代书法家颜真卿，与柳公权对举。"}],"rel":[{"t":"天下三大行书","n":"《祭侄文稿》居第二"},{"t":"柳公权","n":"颜筋柳骨"},{"t":"楷书四大家","n":"四大家之一"},{"t":"王羲之","n":"行书首位，常对比"}],"more":"作品：楷书《多宝塔碑》《颜勤礼碑》《麻姑仙坛记》；行书《祭侄文稿》《争座位帖》。\n《祭侄文稿》作于乾元元年（758 年）。","exam":[]},{"id":"b05-011","t":"天下三大行书","cid":"05b","p":1,"kind":"合称","alias":["三大行书","天下第一行书","天下第二行书","天下第三行书"],"one":"王羲之《兰亭集序》、颜真卿《祭侄文稿》、苏轼《黄州寒食诗帖》。","ans":"天下三大行书是**对三件行书名作的合称**，按通行排序为：**东晋王羲之《兰亭集序》为天下第一行书，唐代颜真卿《祭侄文稿》为天下第二行书，北宋苏轼《黄州寒食诗帖》为天下第三行书**。《兰亭集序》作于**永和九年（353 年）三月三日**，写会稽山阴兰亭修禊雅集，真迹已佚，今传摹本；《祭侄文稿》是悼念侄子颜季明的草稿；《黄州寒食诗帖》写于苏轼贬居黄州时。三帖分别代表晋、唐、宋三代书风，体现“晋尚韵、唐尚法、宋尚意”。","pts":["兰亭集序第一，祭侄文稿第二，寒食诗帖第三","作者：王羲之、颜真卿、苏轼","晋、唐、宋三代书风代表"],"members":[["《兰亭集序》","王羲之，东晋，天下第一行书"],["《祭侄文稿》","颜真卿，唐，天下第二行书"],["《黄州寒食诗帖》","苏轼，北宋，天下第三行书"]],"mem":"按朝代一路排下来：晋、唐、宋，对应一、二、三。人名记“王、颜、苏”，帖名记“兰、祭、寒”：兰亭、祭侄、寒食。情感线索：兰亭是雅集的从容，祭侄是丧侄的悲愤，寒食是贬谪的苦闷，三帖都是“有感而发、一气呵成”。","mix":"三帖都是行书，颜真卿的楷书代表作是《多宝塔碑》；《寒食帖》的作者是苏轼不是黄庭坚，黄庭坚只是为它写了跋；“三希堂三希”（《快雪时晴帖》等）是另一组，不要混。","mcq":[{"q":"“天下第三行书”指的是","o":["《祭侄文稿》","《黄州寒食诗帖》","《蜀素帖》","《兰亭集序》"],"a":1,"w":"苏轼《黄州寒食诗帖》，排在兰亭、祭侄之后。"},{"q":"下列作者与作品对应，正确的是","o":["苏轼《祭侄文稿》","颜真卿《祭侄文稿》","王羲之《祭侄文稿》","颜真卿《兰亭集序》"],"a":1,"w":"《祭侄文稿》是颜真卿所作。"}],"rel":[{"t":"《兰亭集序》","n":"第一行书"},{"t":"颜真卿","n":"第二行书作者"},{"t":"《黄州寒食诗帖》","n":"第三行书"},{"t":"苏轼","n":"第三行书作者"},{"t":"三希堂“三希”","n":"另一组名帖，常混"}],"more":"苏轼《黄州寒食诗帖》写于元丰五年（1082 年），帖中有“自我来黄州，已过三寒食”。\n黄庭坚跋语称其“试使东坡复为之，未必及此”。","exam":[]},{"id":"b05-012","t":"宋四家","cid":"05b","p":1,"kind":"合称","alias":["苏黄米蔡","宋代四大书法家"],"one":"北宋书法四家：苏轼、黄庭坚、米芾、蔡襄，书风尚意。","ans":"宋四家指**北宋四位书法家苏轼、黄庭坚、米芾、蔡襄**，通行简称“苏黄米蔡”。宋代书法重表达个人意趣，史称**“宋人尚意”**，与晋尚韵、唐尚法相对。**苏轼**行书《黄州寒食诗帖》为天下第三行书；**黄庭坚**长于行草，有《松风阁诗帖》；**米芾**号“米颠”，有《蜀素帖》《苕溪诗帖》；**蔡襄**楷书端庄，有《万安桥记》《茶录》。四家把书法从重法度推向重个性，开创了宋代书风。","pts":["苏轼、黄庭坚、米芾、蔡襄","宋人尚意，重个人意趣","苏轼《黄州寒食诗帖》，米芾《蜀素帖》"],"members":[["苏轼","《黄州寒食诗帖》，天下第三行书"],["黄庭坚","《松风阁诗帖》，行草"],["米芾","《蜀素帖》《苕溪诗帖》，号米颠"],["蔡襄","《万安桥记》《茶录》，楷书端庄"]],"mem":"口诀“苏黄米蔡”。书风口诀（清代梁巘提出）：晋尚韵，唐尚法，宋尚意，元明尚态。其中“宋”字对应“意”，四家都是“用字写心意”的人。另一个顺口的记法：苏轼最有名排头，米芾爱石称“米颠”。","mix":"另有说法以蔡京代蔡襄（因蔡京人品遭贬，改称蔡襄），通行为蔡襄；“苏黄米蔡”与“苏黄”（诗，苏轼黄庭坚）、“苏辛”（词）是不同的并称；宋徽宗创瘦金体，不在四家之列。","mcq":[{"q":"下列书法家中，属于“宋四家”的是","o":["米芾","柳公权","颜真卿","赵孟頫"],"a":0,"w":"宋四家为苏轼、黄庭坚、米芾、蔡襄。"},{"q":"“晋尚韵，唐尚法，宋尚意”中，“宋尚意”概括的是","o":["宋四家的书风","颜真卿等人的书风","瘦金体的书风","赵孟頫的书风"],"a":0,"w":"宋代书法重个人意趣，代表即苏黄米蔡。"}],"rel":[{"t":"苏轼","n":"宋四家之首"},{"t":"黄庭坚","n":"宋四家之一"},{"t":"米芾","n":"宋四家之一"},{"t":"瘦金体","n":"宋代另一书体，宋徽宗创"},{"t":"苏黄","n":"同名并称在诗，易混"}],"more":"苏轼自称“我书意造本无法”。\n米芾《蜀素帖》写于北宋元祐三年（1088 年）。","exam":[]},{"id":"b05-025","t":"张旭、怀素","cid":"05b","p":1,"kind":"人物","alias":["颠张醉素","张旭","怀素","草圣张旭","狂草"],"one":"唐代狂草大家，“颠张醉素”，张旭为草圣，怀素有《自叙帖》。","ans":"张旭与怀素是**唐代两位狂草大家**，并称**“颠张醉素”**。**张旭**，吴县（今苏州）人，嗜酒，常醉后挥毫，有时以头发蘸墨书写，被称为**“草圣”**，传世有《古诗四帖》（传）。**怀素**是长沙僧人，以**《自叙帖》**著称，笔势连绵，传说他种芭蕉取叶练字。两人把草书推向**狂草**的高峰，后世以“以狂继颠”相称。杜甫《饮中八仙歌》写“张旭三杯草圣传”，唐文宗曾以张旭草书与李白诗、裴旻剑舞并称“三绝”。","pts":["唐代狂草，颠张醉素","张旭草圣，怀素《自叙帖》","唐文宗三绝：李白诗、裴旻剑、张旭草书"],"members":[["张旭","草圣，嗜酒，“颠”，《古诗四帖》（传）"],["怀素","僧人，“醉”，《自叙帖》"]],"mem":"“颠张醉素”四个字一一对应：颠对张旭，醉对怀素。画面记：张旭喝醉了用头发蘸墨写字（所以“颠”），怀素和尚种了满园芭蕉当纸（所以“素”与芭蕉绑定）。《自叙帖》里的“自”字，对应“自叙”二字，提醒是怀素自己写自己的事。","mix":"东汉张芝也被称“草圣”，唐代的草圣指张旭；《自叙帖》是怀素的，不是张旭的；张旭与怀素是草书，颜真卿曾向张旭请教笔法（传说）。","mcq":[{"q":"唐代草书家中，被称为“草圣”的是","o":["张旭","怀素","颜真卿","柳公权"],"a":0,"w":"张旭，号“草圣”，怀素与之并称颠张醉素。"},{"q":"怀素的代表作是","o":["《玄秘塔碑》","《自叙帖》","《古诗四帖》","《祭侄文稿》"],"a":1,"w":"《自叙帖》为怀素狂草代表作；《古诗四帖》传为张旭作。"}],"rel":[{"t":"书画称号：书圣、草圣、画圣","n":"草圣之称"},{"t":"草书：章草、今草、狂草","n":"狂草的两位大家"},{"t":"颜真卿","n":"相传向张旭学笔法"},{"t":"李白","n":"唐文宗并称“三绝”"}],"more":"杜甫《饮中八仙歌》：张旭三杯草圣传，脱帽露顶王公前，挥毫落纸如云烟。\n作品：张旭《古诗四帖》（传）《肚痛帖》；怀素《自叙帖》《苦笋帖》。","exam":[]},{"id":"b05-026","t":"瘦金体","cid":"05b","p":2,"kind":"概念","alias":["瘦金书","瘦金体"],"one":"宋徽宗赵佶独创的书体，瘦劲锋利。","ans":"瘦金体是**北宋徽宗赵佶**独创的书体，又称“瘦金书”，属楷书一路。其特点是**笔画瘦硬挺拔，转折处带钩，横画收笔有顿点，竖画末端出钩**，如屈铁断金，锋芒毕露。代表作有**《秾芳诗帖》**和《千字文》。瘦金体与宋徽宗的画院、画作共同体现了北宋宫廷书画的高度，是帝王书法中罕见的自成一家者。","pts":["宋徽宗赵佶独创","瘦硬挺拔，转折带钩","《秾芳诗帖》"],"mem":"名字即特征：“瘦”（笔画细劲）加“金”（如金属般锋利）。画面：宋徽宗用瘦长的金属笔写字，笔锋像刀。配套记忆：徽宗**一人三绝**，瘦金体、花鸟画、画院。","mix":"瘦金体是赵佶独创，不是“宋四家”（苏黄米蔡）的书体；宋四家擅行书，瘦金体属楷书。","mcq":[{"q":"“瘦金体”的创始人是","o":["蔡襄","米芾","宋徽宗赵佶","黄庭坚"],"a":2,"w":"瘦金体为宋徽宗赵佶独创，代表作《秾芳诗帖》；蔡襄、米芾、黄庭坚属宋四家。"}],"rel":[{"t":"宋徽宗赵佶","n":"创始人"},{"t":"宋四家","n":"同时代书法家，常被混淆"},{"t":"靖康之变","n":"徽宗被俘的转折"},{"t":"宋代画院与院体画","n":"徽宗同期艺术事业"}],"more":"代表作：《秾芳诗帖》《千字文》（瘦金体）。","exam":[]},{"id":"b05-003","t":"《步辇图》","cid":"05c","p":1,"kind":"作品","exam":["2025名解"],"alias":["步辇图","唐太宗步辇图"],"one":"阎立本绘唐太宗接见吐蕃使者禄东赞，唐蕃和亲的见证。","ans":"《步辇图》是**唐代画家阎立本创作的人物画**，绢本设色，现藏北京故宫博物院（一般认为是宋代摹本）。画面描绘**贞观十五年（641 年）唐太宗坐在步辇上接见吐蕃使者禄东赞**的情景，禄东赞此行是为**吐蕃赞普松赞干布迎娶文成公主**。画家以人物大小、神态的对比突出唐太宗的威仪。作品既是唐代人物画代表作，也是**唐蕃友好往来的历史见证**。","pts":["唐代阎立本人物画","唐太宗接见吐蕃使者禄东赞","文成公主入藏，唐蕃友好见证"],"mem":"一幅画一句话：“太宗坐辇见禄东赞”。人物对应：画中坐辇的是唐太宗，被宫女抬着；站在对面的是禄东赞，要为松赞干布求婚。数字记 641：贞观十五年。阎立本另一代表作《历代帝王图》，画十三位帝王，两幅合起来记“阎立本画帝王”。","mix":"画中使者是禄东赞，不是松赞干布本人；《步辇图》画的是接见使者，不是文成公主出嫁；阎立本的另一名作是《历代帝王图》；现存本被认为是宋摹本。","mcq":[{"q":"《步辇图》描绘的历史事件是","o":["唐太宗接见吐蕃使者禄东赞","文成公主入藏途中","唐高宗册封渤海王","唐玄宗接见日本使者"],"a":0,"w":"贞观十五年，禄东赞来长安为松赞干布求婚。"},{"q":"《步辇图》的作者是","o":["阎立本","吴道子","张萱","顾闳中"],"a":0,"w":"阎立本，唐代人物画家，另有《历代帝王图》。"}],"rel":[{"t":"阎立本与《历代帝王图》","n":"同一作者"},{"t":"唐太宗“天可汗”","n":"画中主角的威望"},{"t":"《清明上河图》","n":"2025 同组名解"},{"t":"《洛神赋图》","n":"同为早期人物画"}],"more":"2025 届名解同组：《清明上河图》。\n《步辇图》现藏北京故宫博物院。"},{"id":"b05-017","t":"吴道子","cid":"05c","p":1,"kind":"人物","alias":["吴道玄","画圣"],"one":"唐代画家，“画圣”，人物衣纹“吴带当风”。","ans":"吴道子，本名道玄，**唐代画家**，阳翟（今河南禹州）人，唐玄宗时曾任宫廷画家，被尊为**“画圣”**。他擅画佛道人物和山水，在长安、洛阳寺观绘有大量壁画。画风**线条流畅有力，人物衣袖飘举**，有**“吴带当风”**之誉，与北齐曹仲达的**“曹衣出水”**相对。传世《送子天王图》相传为其作品（多认为是摹本）。他与顾恺之、陆探微、张僧繇并称**“顾陆张吴”**，开创了中国人物画新风格，被民间画工奉为祖师。","pts":["唐代画圣，擅佛道人物","吴带当风，对曹衣出水","顾陆张吴，《送子天王图》（传）"],"mem":"一句话记画风：“吴带当风”，衣带像被风吹起来；对照“曹衣出水”，衣服像刚出水贴在身上。顺序：先曹后吴，北齐曹、唐代吴。“顾陆张吴”是四个人名首字，顾恺之、陆探微、张僧繇、吴道子，前三位是魏晋南北朝，吴排最后。","mix":"画圣是吴道子，不是顾恺之，也不是阎立本；曹仲达是“曹衣出水”，吴道子是“吴带当风”，两者常被做成对举题；《送子天王图》只是传为吴道子所作。","mcq":[{"q":"“吴带当风”形容的画家是","o":["吴道子","顾恺之","曹仲达","阎立本"],"a":0,"w":"吴道子人物衣带飘举，与曹衣出水相对。"},{"q":"下列画家中，不属于“顾陆张吴”的是","o":["吴道子","顾恺之","陆探微","张萱"],"a":3,"w":"顾陆张吴为顾恺之、陆探微、张僧繇、吴道子。"}],"rel":[{"t":"吴带当风与曹衣出水","n":"风格对举"},{"t":"顾陆张吴","n":"画史四大家"},{"t":"书画称号：书圣、草圣、画圣","n":"画圣之称"},{"t":"唐代仕女画：张萱与周昉","n":"同属唐代人物画"}],"more":"作品：《送子天王图》（传）。\n传说玄宗命其画嘉陵江山水，一日而毕。","exam":[]},{"id":"b05-018","t":"顾恺之","cid":"05c","p":1,"kind":"人物","alias":["顾长康","虎头","顾虎头"],"one":"东晋画家，主张“以形写神”，《洛神赋图》《女史箴图》。","ans":"顾恺之，字长康，小字虎头，晋陵无锡人，**东晋画家**，被誉为**“才绝、画绝、痴绝”**。他的绘画理论主张**“以形写神”**，强调“传神写照，正在阿堵之中”，即人物画要抓住眼睛，另有“迁想妙得”之说。代表作有**《洛神赋图》《女史箴图》**，今存均为摹本。著有《论画》《魏晋胜流画赞》等画论。他与陆探微、张僧繇、吴道子合称**“顾陆张吴”**，把人物画从描摹外形提升到传达精神，是中国人物画的奠基者之一。","pts":["东晋画家，才绝画绝痴绝","以形写神，传神写照在阿堵","《洛神赋图》《女史箴图》（摹本）"],"mem":"三绝顺口：“才、画、痴”。画论四个字：以形写神。画面记：他给人画像，几年不点眼睛，说“传神全在眼睛里”（“阿堵”即“这个”，指眼睛）。两幅图名各取一字：洛神的“洛”，女史的“史”，简称“洛史”。","mix":"顾恺之不是“画圣”（吴道子才是）；谢赫“六法”的“气韵生动”与顾恺之“传神”相通，但六法的提出者是南齐谢赫；两部作品今存均为摹本，原作不存。","mcq":[{"q":"提出“传神写照”“以形写神”的画家是","o":["谢赫","吴道子","顾恺之","张择端"],"a":2,"w":"顾恺之，东晋人物画家。"},{"q":"下列作品中，属于顾恺之的是","o":["《清明上河图》","《五牛图》","《步辇图》","《女史箴图》"],"a":3,"w":"《女史箴图》《洛神赋图》为顾恺之作品（摹本）。"}],"rel":[{"t":"《洛神赋图》","n":"代表作"},{"t":"谢赫“六法”","n":"南齐画论，常对举"},{"t":"顾陆张吴","n":"画史四大家"},{"t":"书画称号：书圣、草圣、画圣","n":"三绝称号"}],"more":"作品：《洛神赋图》《女史箴图》《列女仁智图》（摹本）。\n名句：传神写照，正在阿堵之中。","exam":[]},{"id":"b05-002","t":"《清明上河图》","cid":"05d","p":1,"kind":"作品","exam":["2025名解"],"alias":["清明上河图"],"one":"北宋张择端风俗画长卷，描绘汴京清明时节汴河两岸风貌。","ans":"《清明上河图》是**北宋画家张择端创作的风俗画长卷**，绢本设色，现藏**北京故宫博物院**。画卷以长卷形式，**描绘北宋都城东京（汴京，今河南开封）汴河两岸清明时节的城乡风貌**，从郊野、虹桥到城门街市，绘有数百人物和大量车船、店铺。作品**写实精细，构图疏密有致**，被誉为“中华第一神品”。它是研究北宋城市经济、交通和社会生活的重要图像史料，后世多有仿本。","pts":["北宋张择端，风俗画长卷","汴京汴河两岸清明景象，虹桥","写实精细，北宋社会史料，故宫藏"],"mem":"画面分三段：郊外春色，汴河虹桥，城内街市，像镜头从乡下推进到闹市。数字记：一人（张择端）、一河（汴河）、一桥（虹桥）、一城（汴京）。2025 届与《步辇图》同组，两幅一“朝廷”一“市井”，一唐一宋，对比着记。","mix":"明代仇英等也有同名仿本，别当作原作；“清明”指清明时节，不是清明节习俗专题；现存原本在北京故宫博物院，不是台北故宫。","mcq":[{"q":"《清明上河图》的作者是","o":["张择端","王希孟","黄公望","顾闳中"],"a":0,"w":"北宋张择端。"},{"q":"《清明上河图》描绘的城市是","o":["长安","汴京","临安","洛阳"],"a":1,"w":"北宋都城东京汴京，今开封；临安是南宋都城。"}],"rel":[{"t":"《步辇图》","n":"2025 同组名解"},{"t":"《千里江山图》","n":"同为北宋名画"},{"t":"中国十大传世名画","n":"名作合集"},{"t":"宋代画院与院体画","n":"北宋画院背景"}],"more":"2025 届名解同组：《步辇图》。"},{"id":"b05-013","t":"元四家","cid":"05d","p":1,"kind":"合称","alias":["元代四大家","黄吴倪王"],"one":"元代山水画四家：黄公望、吴镇、倪瓒、王蒙。","ans":"元四家指**元代四位山水画家黄公望、吴镇、倪瓒、王蒙**，他们**以文人画为主流，重笔墨意趣，注重诗书画印结合**，把文人画推向高峰。**黄公望**代表作《富春山居图》；**吴镇**号梅花道人，画《渔父图》；**倪瓒**号云林，画风简淡萧疏，有《六君子图》；**王蒙**画风繁密，有《青卞隐居图》。四家多为隐逸文人，对明清山水画影响深远，被视为**元代文人画的最高成就**。","pts":["黄公望、吴镇、倪瓒、王蒙","元代文人画山水，重笔墨意趣","黄公望《富春山居图》"],"members":[["黄公望","《富春山居图》，居四家之首"],["吴镇","号梅花道人，《渔父图》"],["倪瓒","号云林，简淡，《六君子图》"],["王蒙","画风繁密，《青卞隐居图》"]],"mem":"口诀“黄吴倪王”，谐音可连成“黄吴泥旺”。风格线：黄公望疏朗，吴镇苍劲，倪瓒简淡，王蒙繁密，就像一个从“疏”到“密”的光谱。黄公望的《富春山居图》是必须单独记牢的一幅。","mix":"亦有以赵孟頫代倪瓒的旧说，通行为黄吴倪王；元四家与明四家（沈周、文徵明、唐寅、仇英）、清初四王同为四家并称，注意朝代：元四家画山水，明四家在苏州，清初四王摹古。","mcq":[{"q":"下列画家中，属于“元四家”的是","o":["八大山人","王翚","倪瓒","沈周"],"a":2,"w":"元四家：黄公望、吴镇、倪瓒、王蒙。"},{"q":"《富春山居图》的作者属于","o":["明四家","扬州八怪","元四家","清初四王"],"a":2,"w":"黄公望，元四家之首。"}],"rel":[{"t":"《富春山居图》","n":"黄公望代表作"},{"t":"文人画","n":"元四家为高峰"},{"t":"明四家（吴门四家）","n":"后继的四家"},{"t":"清初四王","n":"摹元四家的一派"}],"more":"黄公望号大痴道人，晚年居富春江畔。","exam":[]},{"id":"b05-014","t":"明四家（吴门四家）","cid":"05d","p":1,"kind":"合称","alias":["明四家","吴门四家","吴门画派","沈文唐仇"],"one":"明代苏州画家沈周、文徵明、唐寅、仇英。","ans":"明四家又称吴门四家，指**明代中期苏州（吴门）地区四位画家沈周、文徵明、唐寅、仇英**。**沈周**是吴门画派的开创者，擅山水花鸟；**文徵明**继承沈周，是吴门画派的领袖；**唐寅**字伯虎，号六如居士，人称“江南第一才子”，擅山水人物；**仇英**出身工匠，擅**工笔重彩人物**，有《汉宫春晓图》。四家继承宋元传统，其中沈、文偏文人画，仇英偏院体，共同使**苏州成为明代绘画重镇**。","pts":["沈周、文徵明、唐寅、仇英","明中期苏州，吴门画派","沈文偏文人画，仇英工笔"],"members":[["沈周","吴门画派开创者"],["文徵明","吴门画派领袖，诗书画兼擅"],["唐寅","字伯虎，江南第一才子"],["仇英","工笔重彩，《汉宫春晓图》"]],"mem":"口诀“沈文唐仇”，谐音“沈文堂仇”。排序有规律：按年龄和师承先后，沈周最长，文徵明是沈周的学生，唐寅与文徵明同龄，仇英最晚。“吴门”是苏州，所以“吴门四家”和“明四家”是同一组。","mix":"唐寅与祝允明、文徵明、徐祯卿合称“吴中四才子”，那是文学并称，不是画家并称；仇英擅长工笔人物，另三家偏文人画；“元四家”“清初四王”是别的朝代。","mcq":[{"q":"下列画家中，不属于“明四家”的是","o":["沈周","黄公望","文徵明","仇英"],"a":1,"w":"黄公望属于元四家。"},{"q":"“吴门四家”中以工笔重彩人物著称的是","o":["文徵明","唐寅","沈周","仇英"],"a":3,"w":"仇英出身工匠，擅工笔，作《汉宫春晓图》。"}],"rel":[{"t":"元四家","n":"前一代四家"},{"t":"吴中四才子","n":"含唐寅文徵明，易混"},{"t":"文人画","n":"沈周文徵明的画风"},{"t":"清初四王","n":"后一代四家"}],"more":"唐寅号六如居士，代表作《秋风纨扇图》。","exam":[]},{"id":"b05-015","t":"扬州八怪","cid":"05d","p":1,"kind":"合称","alias":["扬州画派","扬州八家"],"one":"清代乾隆年间扬州卖画的画家群，郑板桥、金农等，个性鲜明。","ans":"扬州八怪是**清代康乾时期活跃在扬州的一批画家的合称**，因画风不拘成法、个性强烈而得名。通行说法有**郑燮（板桥）、金农、黄慎、李鱓、李方膺、汪士慎、高翔、罗聘**八人，另有多种名单。他们多以**卖画为生**，擅长**写意花鸟**，主张抒发个性，突破“四王”的摹古风气。**郑燮**画竹，有“难得糊涂”之语；**金农**创“漆书”；罗聘有《鬼趣图》。扬州八怪促进了**文人画的创新**和书画商品化的发展。","pts":["清代乾隆前后，扬州卖画画家群","郑板桥、金农、黄慎、李鱓等","写意花鸟，个性强烈，突破摹古"],"members":[["郑燮","号板桥，画竹，“难得糊涂”"],["金农","创“漆书”，号冬心"],["黄慎","人物画，泼墨"],["李鱓","写意花卉"],["李方膺","梅竹"],["汪士慎","画梅"],["高翔","山水"],["罗聘","《鬼趣图》"]],"mem":"记一个核心人物：郑板桥（郑燮）。他“难得糊涂”、画竹、写“咬定青山不放松”（《竹石》）。“八怪”记成“怪”的原因：作风怪，画风怪。通行名单八人：郑金黄李（鱓）李（方膺）汪高罗，顺口念“郑金黄两李，汪高罗”。","mix":"八怪成员有多种说法（有版本含边寿民、闵贞、华喦、杨法等），通行八人如上，题目常只考郑板桥、金农、黄慎、李鱓；“清初四王”主张摹古，“扬州八怪”主张个性，是一对反差。","mcq":[{"q":"“难得糊涂”的题写者、扬州八怪代表人物是","o":["黄慎","郑燮","罗聘","金农"],"a":1,"w":"郑燮，号板桥，人称郑板桥。"},{"q":"扬州八怪活跃的时代是","o":["元代","清代","宋代","明代"],"a":1,"w":"清代康乾时期，卖画于扬州。"}],"rel":[{"t":"郑燮","n":"八怪代表"},{"t":"清初四王","n":"摹古对立面"},{"t":"清初四僧","n":"同代创新画派"},{"t":"文人画","n":"传统的继承与革新"}],"more":"郑燮名句：咬定青山不放松，立根原在破岩中。｜《竹石》","exam":[]},{"id":"b05-016","t":"岁寒三友、四君子","cid":"05d","p":2,"kind":"合称","alias":["岁寒三友","四君子","松竹梅","梅兰竹菊"],"one":"岁寒三友松竹梅，四君子梅兰竹菊，文人画常见题材。","ans":"岁寒三友与四君子都是**文人画常见题材**，用植物比喻高洁品格。**岁寒三友**指**松、竹、梅**，因耐寒而傲霜雪，象征坚贞，语意出自《论语》“岁寒，然后知松柏之后凋也”。**四君子**指**梅、兰、竹、菊**，分别象征傲、幽、坚、淡。二者共用梅、竹两种，是文人以物比德、寄托志趣的体现。","pts":["岁寒三友：松竹梅","四君子：梅兰竹菊","文人画题材，比喻高洁品格"],"members":[["岁寒三友","松、竹、梅"],["四君子","梅、兰、竹、菊"]],"mem":"数字对应：**三友松竹梅，四君子加兰菊、减松**（四君子里没有松）。梅、竹是两组共有。性格记忆：梅傲雪、兰幽香、竹有节、菊耐霜。","mix":"松只在三友里，兰、菊只在四君子里；梅、竹两个组合都有，最易出干扰项。","mcq":[{"q":"下列植物组合中，属于“四君子”的是","o":["松、竹、梅","梅、兰、竹、菊","松、梅、兰、竹","兰、菊、竹、松"],"a":1,"w":"四君子是梅兰竹菊；松竹梅是岁寒三友。"}],"rel":[{"t":"文人画","n":"常见题材"},{"t":"中国画技法与分科：工笔、写意、白描、没骨","n":"花鸟科题材"},{"t":"元四家","n":"文人画成熟期"},{"t":"文人四艺（琴棋书画）","n":"文人雅事"}],"more":"《论语·子罕》：岁寒，然后知松柏之后凋也。","exam":[]},{"id":"b05-019","t":"齐白石","cid":"05e","p":2,"kind":"人物","alias":["白石老人","白石山翁"],"one":"近现代画家，画虾闻名，提出“似与不似之间”。","ans":"齐白石（1864–1957）是**近现代著名画家**，**湖南湘潭人**，早年为木匠，后以画名世。他擅画**虾、蛙、花鸟**，笔墨简练，“衰年变法”后画风独创，提出作画“**妙在似与不似之间**”。他与**张大千**并称“**南张北齐**”，被授予“**人民艺术家**”称号，1956年获**世界和平理事会1955年度国际和平奖**。《蛙声十里出山泉》是其名作。","pts":["湘潭木匠出身，画虾闻名","似与不似之间","与张大千并称南张北齐"],"mem":"画面：**一只虾**，透明有节，是齐白石的“商标”。理论一句话：**妙在似与不似之间**，太似为媚俗，不似为欺世。地理锚点：湖南湘潭，对比“南张北齐”的“北”（定居北京）。","mix":"齐白石擅花鸟虫鱼，徐悲鸿擅画马，张大千擅山水，不要混淆；“南张北齐”里齐属“北”，张属“南”。","mcq":[{"q":"以画虾闻名，并提出“妙在似与不似之间”的画家是","o":["徐悲鸿","张大千","吴昌硕","齐白石"],"a":3,"w":"齐白石善画虾，艺术主张是“妙在似与不似之间”。"}],"rel":[{"t":"南张北齐","n":"与张大千并称"},{"t":"吴昌硕","n":"受其影响"},{"t":"徐渭","n":"推崇的前辈"},{"t":"徐悲鸿","n":"同时代画家，画马"}],"more":"名句：作画妙在似与不似之间，太似为媚俗，不似为欺世。｜齐白石\n名作：《墨虾》《蛙声十里出山泉》。","exam":[]},{"id":"b05-020","t":"《二泉映月》","cid":"05f","p":2,"kind":"作品","alias":["二泉映月","阿炳","华彦钧"],"one":"民间艺人华彦钧（阿炳）创作的二胡独奏曲，二胡艺术经典。","ans":"《二泉映月》是**民间音乐家华彦钧（阿炳）创作的二胡独奏曲**，原无曲名，1950年经杨荫浏等人录音整理后，因曲意与无锡惠山二泉相关而定名。阿炳是无锡的盲人艺人，另有《听松》《寒春风曲》等曲传世。全曲以深沉苍凉的旋律抒发**底层生活的辛酸与不屈**，被视为**二胡艺术的经典**，1978年指挥家小泽征尔听后称这样的音乐应当跪着听。","pts":["华彦钧（阿炳）所作二胡曲","1950年录音整理，因无锡惠山二泉定名","二胡经典，小泽征尔“跪着听”"],"mem":"画面：无锡街头，盲艺人阿炳拉二胡，月光映在惠山泉面上，曲调凄凉。与《梁祝》对记：《二泉映月》写苦（民间艺人，二胡），《梁祝》写爱（学院创作，小提琴）。","mix":"二胡名家还有刘天华，他是近代二胡专业化的开创者，作品有《病中吟》《光明行》；阿炳是民间艺人，二者常被对举。《二泉映月》是创作曲，不是民歌。","mcq":[{"q":"二胡曲《二泉映月》的作者是","o":["刘天华","聂耳","华彦钧（阿炳）","冼星海"],"a":2,"w":"《二泉映月》为无锡民间艺人华彦钧（阿炳）所作；刘天华是近代二胡艺术的开创者。"}],"rel":[{"t":"刘天华","n":"近代二胡专业化的开创者"},{"t":"《梁祝》","n":"近现代器乐名曲对举"},{"t":"民族乐器分类","n":"二胡属拉弦乐器"}],"more":"阿炳（1893–1950），原名华彦钧，双目失明，无锡道士与街头艺人。\n作品：二胡曲《二泉映月》《听松》《寒春风曲》；琵琶曲《大浪淘沙》《龙船》《昭君出塞》。","exam":[]},{"id":"b05-021","t":"《梁祝》","cid":"05f","p":2,"kind":"作品","alias":["梁祝","梁祝小提琴协奏曲","梁山伯与祝英台协奏曲"],"one":"1959年何占豪、陈钢作曲的小提琴协奏曲，取材越剧音调。","ans":"《梁祝》全名《梁山伯与祝英台》，是**小提琴协奏曲**，由上海音乐学院学生**何占豪、陈钢**在1959年创作，同年在上海首演，独奏者为俞丽拿。乐曲取材于**越剧**唱腔与民间传说，按草桥结拜、抗婚、楼台会、化蝶等情节展开。它让西洋乐器奏出中国韵味，是**中国民族化交响音乐的代表作**，国内外演出长盛不衰。","pts":["1959年何占豪、陈钢作曲","小提琴协奏曲，取材越剧音调与梁祝传说","西洋形式与民族风格结合的代表作"],"mem":"逻辑线：小提琴（西洋）加越剧旋律（中国），再加梁祝传说，所以叫“洋乐中魂”。作曲者两个姓“何陈”，年份1959，是建国十周年的献礼之作。","mix":"越剧《梁山伯与祝英台》是戏曲，小提琴协奏曲《梁祝》是器乐曲，二者同题不同体裁；《梁祝》是协奏曲，不是交响曲。","mcq":[{"q":"小提琴协奏曲《梁祝》的作曲者是","o":["何占豪、陈钢","聂耳、冼星海","刘天华、华彦钧","马可、瞿维"],"a":0,"w":"《梁祝》为何占豪、陈钢1959年创作；马可等人作曲的是歌剧《白毛女》。"}],"rel":[{"t":"越剧与黄梅戏","n":"越剧《梁祝》是其音调来源"},{"t":"《二泉映月》","n":"近现代器乐名曲对举"},{"t":"歌剧《白毛女》","n":"同为民族化音乐创作"}],"more":"1959年5月在上海首演，小提琴独奏俞丽拿。","exam":[]},{"id":"b05-022","t":"古琴","cid":"05f","p":2,"kind":"常识","alias":["七弦琴","瑶琴","古琴艺术"],"one":"中国最古老的弹拨乐器之一，2003年入选人类非遗代表作。","ans":"古琴又称**七弦琴、瑶琴**，是**中国最古老的弹拨乐器之一**，在八音中属“丝”，居琴棋书画之首，被视为文人修身养性的雅器。琴有七弦十三徽，用减字谱记谱，名曲有**《高山流水》《广陵散》**《平沙落雁》等。2003年古琴艺术入选联合国教科文组织**人类口头和非物质遗产代表作**，是中国文人音乐传统的核心。","pts":["最古老的弹拨乐器之一，七弦十三徽","琴棋书画之首，文人雅器","2003年入选人类非遗代表作"],"mem":"年份串联：昆曲2001、古琴2003、粤剧2009、花儿2009，按这个顺序记中国入选的几项音乐戏曲类非遗。琴是“君子之器”，所以排在琴棋书画第一位。","mix":"古琴是弹拨乐器（拨弦），不是拉弦；古筝十几根弦以上，古琴只有七根弦；2001年首批入选的是昆曲，古琴是2003年。","mcq":[{"q":"2003年入选联合国教科文组织人类口头和非物质遗产代表作的中国乐器艺术是","o":["粤剧","昆曲","花儿","古琴"],"a":3,"w":"古琴艺术2003年入选；昆曲是2001年，粤剧、花儿是2009年。"}],"rel":[{"t":"《广陵散》","n":"古琴名曲"},{"t":"伯牙子期与《高山流水》","n":"古琴名曲与知音典故"},{"t":"中国十大古曲","n":"多数为古琴曲"},{"t":"八音","n":"古琴属丝"}],"more":"传统七弦十三徽，用减字谱记谱。\n古琴曲：《高山流水》《广陵散》《平沙落雁》《梅花三弄》《渔樵问答》《胡笳十八拍》。","exam":[]},{"id":"b05-023","t":"中国十大古曲","cid":"05f","p":2,"kind":"合称","alias":["十大古曲","中国古代十大名曲"],"one":"十首古琴、琵琶名曲，含《高山流水》《广陵散》《十面埋伏》等。","ans":"中国十大古曲是**流传至今的十首古代名曲**，通行名单为**《高山流水》《广陵散》《平沙落雁》《梅花三弄》《十面埋伏》《夕阳箫鼓》《渔樵问答》《胡笳十八拍》《汉宫秋月》《阳春白雪》**。其中古琴曲占多数，《十面埋伏》是琵琶曲，《夕阳箫鼓》后来改编为《春江花月夜》。这一名单集中体现了古琴与琵琶两大乐器的传统曲目。","pts":["十首古琴、琵琶传统名曲","高山流水、广陵散、平沙落雁、梅花三弄、十面埋伏等","《夕阳箫鼓》即《春江花月夜》前身"],"members":[["《高山流水》","古琴曲，伯牙与钟子期的知音故事"],["《广陵散》","古琴曲，聂政刺韩王传说，嵇康临刑弹奏"],["《平沙落雁》","古琴曲，又名《雁落平沙》，写秋江雁落之景"],["《梅花三弄》","古琴曲，相传原为晋代桓伊笛曲，梅花主题三次再现"],["《十面埋伏》","琵琶曲，写楚汉垓下之战"],["《夕阳箫鼓》","琵琶曲，后改编为《春江花月夜》"],["《渔樵问答》","古琴曲，渔夫与樵夫的山水问答，表现隐逸"],["《胡笳十八拍》","古琴曲（琴歌），据蔡文姬归汉故事"],["《汉宫秋月》","宫怨题材，有琵琶、二胡等版本"],["《阳春白雪》","典出宋玉《对楚王问》，与“下里巴人”相对"]],"mem":"自编首字串：“高广平梅十夕渔，胡汉阳”。十首里只记一首琵琶战争曲：《十面埋伏》，写楚汉相争；其余先默认是古琴曲，再补《夕阳箫鼓》是琵琶曲。","mix":"十大古曲的名单各家略有出入，以通行十首为准；《二泉映月》《梁祝》是近现代作品，不在其中；《夕阳箫鼓》与张若虚的诗《春江花月夜》同名而不同体裁。","mcq":[{"q":"下列乐曲中，属于“中国十大古曲”的是","o":["《二泉映月》","《十面埋伏》","《梁祝》","《茉莉花》"],"a":1,"w":"《十面埋伏》是琵琶古曲；其余三首都是近现代作品或民歌。"}],"rel":[{"t":"古琴","n":"多数古曲为古琴曲"},{"t":"《广陵散》","n":"十大古曲之一"},{"t":"伯牙子期与《高山流水》","n":"十大古曲之首"},{"t":"《十面埋伏》","n":"琵琶古曲"}],"more":"《夕阳箫鼓》又称《浔阳琵琶》，后改编为民族管弦乐《春江花月夜》。","exam":[]},{"id":"b05-024","t":"《广陵散》","cid":"05f","p":2,"kind":"作品","alias":["广陵散","广陵止息"],"one":"古琴曲，与嵇康临刑弹奏、“于今绝矣”的故事相连。","ans":"《广陵散》是**古琴曲**，又名《广陵止息》，相传取材于战国**聂政刺韩王**的故事，曲调激昂慷慨。魏晋之际**嵇康**善弹此曲，据《晋书》《世说新语》记载，他被司马氏处死前索琴弹奏，叹道“**《广陵散》于今绝矣**”，后世因此视其为绝响。今传曲谱收于明代朱权《神奇秘谱》，列入**中国十大古曲**，与嵇康的人格气节紧密相连。","pts":["古琴曲，取材聂政刺韩王","嵇康临刑弹奏，“《广陵散》于今绝矣”","曲谱存于明代《神奇秘谱》，十大古曲之一"],"mem":"画面：刑场上日影西斜，嵇康索琴弹完一曲，说“《广陵散》于今绝矣”。关键词连成线：广陵散，嵇康，临刑，绝响。","mix":"嵇康并非该曲作者，只是以善弹闻名；曲子在明代仍有谱，并未真正失传，“绝”是嵇康的感叹。","mcq":[{"q":"“《广陵散》于今绝矣”是哪位人物临刑前所说","o":["阮籍","向秀","嵇康","山涛"],"a":2,"w":"此语见于《晋书·嵇康传》，嵇康被害前弹《广陵散》后所叹。"}],"rel":[{"t":"嵇康","n":"临刑弹奏此曲"},{"t":"竹林七贤","n":"嵇康所属群体"},{"t":"《世说新语》","n":"载嵇康临刑事"},{"t":"古琴","n":"所属乐器"}],"more":"琴谱见明代朱权《神奇秘谱》（1425年）。","exam":[]},{"id":"b05-029","t":"敦煌壁画","cid":"05g","p":2,"kind":"作品","alias":["莫高窟壁画","莫高窟","飞天","反弹琵琶"],"one":"甘肃莫高窟壁画，飞天为代表形象，1987年入世界遗产。","ans":"敦煌壁画指**甘肃敦煌莫高窟的壁画**，莫高窟始建于前秦（366年），延续到元代，1987年列入**世界文化遗产**。壁画有佛像、经变、佛传故事、供养人像和丝路交通场景，其中**飞天**是最具代表性的形象，**反弹琵琶**等乐舞图成为后世舞蹈灵感。1900年莫高窟发现**藏经洞**，出土大量文书。它与云冈、龙门、麦积山并称四大石窟。","pts":["莫高窟壁画，始建于前秦366年","飞天、反弹琵琶等乐舞形象","1987年入选世界文化遗产"],"mem":"画面：衣带飘举的飞天在石窟顶上凌空飞舞，手里抱琵琶反弹。后世《丝路花雨》的“反弹琵琶”舞姿就来自这里。数字串：366年始建，1900年发现藏经洞，1987年入遗。","mix":"敦煌莫高窟是石窟艺术，兼有壁画和彩塑；云冈、龙门以石雕造像为主；藏经洞出土的是文书而不是壁画。","mcq":[{"q":"舞剧《丝路花雨》“反弹琵琶”舞姿的灵感来源于","o":["云冈石窟雕像","龙门石窟造像","麦积山塑像","敦煌莫高窟壁画"],"a":3,"w":"编导从敦煌壁画乐舞形象中创造了反弹琵琶舞姿。"}],"rel":[{"t":"舞剧《丝路花雨》","n":"据壁画创作"},{"t":"中国四大石窟","n":"莫高窟居其一"},{"t":"敦煌藏经洞","n":"1900年发现"},{"t":"中国首批世界遗产（1987年6项）","n":"莫高窟入选"}],"more":"莫高窟现有洞窟735个，壁画约4.5万平方米。","exam":[]},{"id":"b05-004","t":"京剧四大名旦","cid":"05h","p":1,"kind":"合称","exam":["2023名解"],"alias":["四大名旦","梅尚程荀","梅程尚荀"],"one":"梅兰芳、程砚秋、尚小云、荀慧生，京剧旦角四大流派。","ans":"四大名旦是**20 世纪 20 年代京剧旦角四位杰出演员的合称**，指**梅兰芳、程砚秋、尚小云、荀慧生**，1927 年北京《顺天时报》评选后得名。四人分别**创立梅派、程派、尚派、荀派**：梅兰芳端庄雍容，代表作《贵妃醉酒》《霸王别姬》；程砚秋唱腔幽咽婉转，代表作《锁麟囊》；尚小云刚健，荀慧生活泼，代表作《红娘》。四人推动京剧旦行艺术走向成熟，梅兰芳还将京剧带到日本、美国、苏联。","pts":["梅、程、尚、荀，1927 年评选","梅派、程派、尚派、荀派","旦行成熟，京剧走向世界"],"members":[["梅兰芳","梅派，《贵妃醉酒》《霸王别姬》"],["程砚秋","程派，幽咽婉转，《锁麟囊》"],["尚小云","尚派，刚健，擅武戏"],["荀慧生","荀派，活泼，《红娘》"]],"mem":"口诀“梅程尚荀”（常按“梅尚程荀”排）。性格配对：梅的气质“端”、程的唱腔“幽”、尚的风格“刚”、荀的角色“俏”。代表剧名各取一字：贵妃（梅）、麟囊（程）、红娘（荀）。","mix":"旦角演女性角色，四人都是男演员（乾旦）；与之并称的“四大须生”是老生；“前四大须生”与“后四大须生”是两组；京剧行当是生旦净丑。","mcq":[{"q":"下列不属于京剧“四大名旦”的是","o":["梅兰芳","荀慧生","程砚秋","马连良"],"a":3,"w":"马连良是须生，属四大须生。"},{"q":"京剧程派的创始人是","o":["荀慧生","梅兰芳","程砚秋","尚小云"],"a":2,"w":"程砚秋创程派，代表作《锁麟囊》。"}],"rel":[{"t":"梅兰芳","n":"四大名旦之首"},{"t":"四大须生","n":"男角对举"},{"t":"京剧行当","n":"旦行属生旦净丑"},{"t":"京剧的形成","n":"形成背景"},{"t":"梅兰芳表演体系","n":"梅派走向世界"}],"more":"1927 年《顺天时报》评选，由此“四大名旦”之名流传。"},{"id":"b05-007","t":"京剧行当","cid":"05h","p":1,"kind":"概念","alias":["生旦净丑","四大行当","行当"],"one":"京剧角色分类：生、旦、净、丑。","ans":"京剧行当是**京剧按角色性别、年龄、性格划分的类型**，分为**生、旦、净、丑**四大类。**生**是男性角色，分老生、小生、武生、娃娃生；**旦**是女性角色，分青衣、花旦、武旦、刀马旦、老旦等；**净**俗称花脸，演性格鲜明的男性角色，脸部勾画脸谱；**丑**是喜剧角色，鼻梁上抹白块，分文丑、武丑。行当化是京剧的重要特点，每种行当有固定的唱念做打程式，便于观众识别人物。","pts":["生旦净丑，四大行当","生男旦女，净为花脸，丑是喜剧角色","每行当有固定程式，下分细类"],"members":[["生","男性角色：老生、小生、武生、娃娃生"],["旦","女性角色：青衣、花旦、武旦、刀马旦、老旦"],["净","花脸：铜锤花脸、架子花脸、武净"],["丑","喜剧角色：文丑、武丑"]],"mem":"口诀“生旦净丑”，和四大名旦、四大须生挂钩：须生属“生”，名旦属“旦”。记法：生是男、旦是女、净是花脸、丑是小花脸（鼻梁白块）。元杂剧的角色以末、旦、净为主，与京剧的生旦净丑不同。","mix":"元杂剧有“末、旦、净”，京剧是“生旦净丑”；“生”是男角，包括老生、小生，不是“学生”；“净”指花脸，不是干净。","mcq":[{"q":"下列属于京剧四大行当的是","o":["生旦净末","生旦末丑","末旦净丑","生旦净丑"],"a":3,"w":"京剧行当为生旦净丑。"},{"q":"京剧中俗称“花脸”的行当是","o":["生","旦","丑","净"],"a":3,"w":"净行脸部勾画脸谱，俗称花脸。"}],"rel":[{"t":"京剧四功五法","n":"表演基本功"},{"t":"京剧脸谱","n":"净行的化妆"},{"t":"京剧四大名旦","n":"旦行代表"},{"t":"四大须生","n":"生行代表"}],"more":"丑行鼻梁上抹白块，俗称“小花脸”。","exam":[]},{"id":"b05-008","t":"京剧的形成","cid":"05h","p":1,"kind":"事件","alias":["皮黄腔","徽班进京","京剧形成"],"one":"1790 年徽班进京，融汇汉调、昆曲、秦腔，道光年间形成京剧。","ans":"京剧的形成是**清代中期戏曲演变的重要事件**。**乾隆五十五年（1790 年）**，徽班**三庆班**进京为乾隆祝寿，此后四喜、和春、春台等徽班陆续入京，史称**“四大徽班进京”**。徽班在北京吸收**汉调（湖北）、昆曲、秦腔**的长处，融合成以**西皮、二黄**为主的**皮黄腔**，到**道光年间**逐渐形成京剧。京剧被称为“国剧”，**2010 年列入人类非物质文化遗产代表作名录**。","pts":["1790 年徽班进京，三庆班为乾隆祝寿","融合汉调、昆曲、秦腔，形成皮黄腔","道光年间形成，2010 年列入非遗"],"mem":"时间线：1790 进京，几十年融合，道光年间成形，2010 申遗。融合公式：徽（二黄）＋汉（西皮）＋昆＋秦＝京。“皮黄”就是“西皮”和“二黄”的合称，徽班带来二黄，汉调带来西皮。","mix":"京剧起源于安徽的徽剧与湖北的汉调，不是北京本地剧种；昆曲在京剧形成前已是宫廷主流，京剧崛起即“花雅之争”中花部胜出；京剧形成于道光年间，不是乾隆年间。","mcq":[{"q":"1790 年为乾隆祝寿进京的徽班是","o":["四喜班","和春班","三庆班","春台班"],"a":2,"w":"三庆班首先进京，后有四喜、和春、春台。"},{"q":"京剧的主要腔调是","o":["昆山腔","梆子腔","弋阳腔","皮黄腔"],"a":3,"w":"皮黄腔由西皮与二黄合成。"}],"rel":[{"t":"四大徽班进京","n":"形成的起点"},{"t":"昆曲","n":"京剧吸收的剧种"},{"t":"秦腔与川剧","n":"京剧吸收的秦腔"},{"t":"同光十三绝与程长庚","n":"京剧早期名角"}],"more":"2010 年京剧列入人类非物质文化遗产代表作名录。","exam":[]},{"id":"b05-009","t":"昆曲","cid":"05h","p":1,"kind":"概念","alias":["昆剧","昆山腔","水磨调","百戏之祖"],"one":"起源于昆山，魏良辅改为水磨调，被称“百戏之祖”。","ans":"昆曲是**中国古老的戏曲剧种**，**元末明初起源于江苏昆山**，原称**昆山腔**。**明代嘉靖年间魏良辅**对昆山腔进行改革，创造**细腻婉转的“水磨调”**，梁辰鱼以昆腔写成《浣纱记》，使昆曲成为全国性剧种。昆曲唱腔清柔，表演细腻，代表作有汤显祖《牡丹亭》、孔尚任《桃花扇》、洪昇《长生殿》。昆曲对京剧等剧种影响很大，被称为**“百戏之祖”**，**2001 年列入首批“人类口头和非物质遗产代表作”**。","pts":["元末明初起源于昆山，魏良辅改革水磨调","《牡丹亭》《桃花扇》《长生殿》","百戏之祖，2001 年首批非遗"],"mem":"三个关键词：昆山、魏良辅、水磨。“水磨”像水磨年糕一样细腻、柔和，形容唱腔。年份记 2001：昆曲是我国首个入选联合国教科文组织人类口头和非物质遗产代表作的项目。剧目口诀“牡桃长”（牡丹亭、桃花扇、长生殿）。","mix":"昆曲是南曲，元杂剧是北曲；京剧形成于清代，昆曲更古老，被称“百戏之祖”；《西厢记》是元杂剧，不在昆曲三大名剧中。","mcq":[{"q":"明代改革昆山腔、创造“水磨调”的是","o":["汤显祖","魏良辅","梁辰鱼","沈璟"],"a":1,"w":"魏良辅，嘉靖年间；梁辰鱼以昆腔作《浣纱记》。"},{"q":"昆曲被列入联合国教科文组织“人类口头和非物质遗产代表作”的年份是","o":["1990","2010","2001","2018"],"a":2,"w":"2001 年首批；京剧是 2010 年。"}],"rel":[{"t":"南戏四大声腔","n":"昆山腔是其一"},{"t":"梁辰鱼《浣纱记》","n":"首部昆腔传奇"},{"t":"《牡丹亭》","n":"代表剧目"},{"t":"京剧的形成","n":"昆曲影响京剧"},{"t":"汤显祖与“临川四梦”","n":"昆曲重要剧作家"}],"more":"名剧：《牡丹亭》《桃花扇》《长生殿》《浣纱记》。","exam":[]},{"id":"b05-030","t":"地方戏五大剧种","cid":"05h","p":2,"kind":"合称","alias":["五大戏曲剧种","中国五大剧种"],"one":"京剧、越剧、黄梅戏、评剧、豫剧五大戏曲剧种。","ans":"地方戏五大剧种通常指**京剧、越剧、黄梅戏、评剧、豫剧**，是流布广、影响大的五个戏曲剧种。京剧形成于北京，被称为国粹；越剧起于浙江嵊州，代表剧目《梁山伯与祝英台》；黄梅戏流行于安徽，以《天仙配》闻名；评剧起于河北唐山一带，《花为媒》为名剧；豫剧是河南梆子，《花木兰》知名。五者合称**“中国五大戏曲剧种”**。","pts":["京剧、越剧、黄梅戏、评剧、豫剧","各自地域与代表剧目","合称中国五大戏曲剧种"],"members":[["京剧","北京；形成于清代，被称国粹；《贵妃醉酒》《霸王别姬》"],["越剧","浙江嵊州；《梁山伯与祝英台》《红楼梦》"],["黄梅戏","安徽安庆；《天仙配》《女驸马》；严凤英"],["评剧","河北唐山一带；《花为媒》《刘巧儿》；成兆才、新凤霞"],["豫剧","河南；梆子腔；《花木兰》《穆桂英挂帅》；常香玉"]],"mem":"首字口诀“京越黄评豫”。配地域：京浙皖冀豫（北京、浙江、安徽、河北、河南），顺序一一对应。","mix":"京剧本身并非地方戏，但五大剧种名单习惯把它列入；昆曲是“百戏之祖”，不在这五个之中。","mcq":[{"q":"下列不属于通行说法中“五大戏曲剧种”的是","o":["越剧","昆曲","豫剧","评剧"],"a":1,"w":"五大剧种是京、越、黄梅、评、豫，昆曲不在其中。"}],"rel":[{"t":"越剧与黄梅戏","n":"五大剧种中的两个"},{"t":"评剧","n":"五大剧种之一"},{"t":"豫剧与常香玉","n":"五大剧种之一"},{"t":"昆曲","n":"百戏之祖，不在其列"},{"t":"京剧的形成","n":"五大剧种之首"}],"more":"五大剧种常与国粹京剧并提。","exam":[]},{"id":"b05-031","t":"越剧与黄梅戏","cid":"05h","p":2,"kind":"概念","alias":["越剧","黄梅戏","严凤英","天仙配"],"one":"越剧源于浙江嵊州，代表《梁祝》；黄梅戏代表《天仙配》。","ans":"**越剧**起于浙江嵊州，由当地“落地唱书”发展而来，后在上海兴盛，以女子演员为主，唱腔婉转，代表剧目有**《梁山伯与祝英台》**《红楼梦》。**黄梅戏**源于湖北黄梅采茶调，成熟于安徽安庆一带，唱腔质朴明快，代表剧目有**《天仙配》**《女驸马》，严凤英是代表演员。两者都是**中国五大戏曲剧种**之一，通过戏曲电影传遍全国。","pts":["越剧：浙江嵊州，《梁山伯与祝英台》","黄梅戏：安徽，《天仙配》","同属五大戏曲剧种"],"mem":"配对记：越剧配《梁祝》（梁山伯越过山），黄梅戏配《天仙配》（黄梅配仙）。越剧演员多为女性，黄梅戏经典人物有董永、七仙女。","mix":"小提琴协奏曲《梁祝》取材于越剧音调；黄梅戏起源于湖北黄梅，繁荣于安徽，常被称为安徽的戏。","mcq":[{"q":"黄梅戏的代表剧目是","o":["《梁山伯与祝英台》","《花木兰》","《天仙配》","《花为媒》"],"a":2,"w":"《天仙配》是黄梅戏经典；《梁祝》属越剧，《花木兰》属豫剧，《花为媒》属评剧。"}],"rel":[{"t":"地方戏五大剧种","n":"同属五大剧种"},{"t":"《梁祝》","n":"取材越剧音调"},{"t":"评剧","n":"同属五大剧种"},{"t":"京剧的形成","n":"五大剧种之首"}],"more":"越剧《红楼梦》1962年拍成电影，徐玉兰、王文娟主演。","exam":[]},{"id":"b05-032","t":"梅兰芳表演体系","cid":"05h","p":1,"kind":"概念","alias":["梅兰芳体系","世界三大表演体系","三大表演体系"],"one":"与斯坦尼斯拉夫斯基体系、布莱希特体系并称世界三大表演体系。","ans":"梅兰芳表演体系是**以梅兰芳的京剧表演艺术为代表的中国戏曲表演体系**，与**斯坦尼斯拉夫斯基体系、布莱希特体系**并称**“世界三大表演体系”**（通行说法）。它的特点是**写意、虚拟、程式化**，通过唱念做打、虚拟动作和程式规范，用有限舞台表现无限时空。梅兰芳 1919 年访日、1930 年访美、1935 年访苏，把京剧介绍给世界，并与斯坦尼斯拉夫斯基、布莱希特等交流。这一体系体现了**中国戏曲美学的独特价值**。","pts":["梅兰芳代表的中国戏曲表演体系","与斯坦尼斯拉夫斯基、布莱希特并称三大","写意、虚拟、程式化，1935 年访苏交流"],"members":[["斯坦尼斯拉夫斯基体系","俄国，强调“体验”"],["布莱希特体系","德国，叙事体系，间离效果"],["梅兰芳体系","中国，写意、虚拟、程式"]],"mem":"三个国家三个关键词：俄“体验”，德“间离”，中“写意”。对应人物：斯坦尼（莫斯科艺术剧院）、布莱希特（柏林剧团）、梅兰芳（京剧）。时间线：1935 年梅兰芳访苏，见到斯坦尼和布莱希特，三人在莫斯科“交汇”。","mix":"“世界三大表演体系”是通行说法，学界也有不同提法；它与“世界三大古老戏剧”不同，后者指古希腊戏剧、梵剧、中国戏曲；梅兰芳是京剧演员，体系不等于梅派唱腔。","mcq":[{"q":"下列不属于“世界三大表演体系”的是","o":["莎士比亚体系","斯坦尼斯拉夫斯基体系","梅兰芳体系","布莱希特体系"],"a":0,"w":"三大体系为斯坦尼、布莱希特、梅兰芳。"},{"q":"梅兰芳访问苏联的年份是","o":["1919","1935","1949","1930"],"a":1,"w":"1919 访日，1930 访美，1935 访苏。"}],"rel":[{"t":"梅兰芳","n":"体系代表人物"},{"t":"斯坦尼斯拉夫斯基","n":"体验派代表"},{"t":"布莱希特","n":"间离效果"},{"t":"戏曲美学特征：综合性、虚拟性、程式性","n":"体系的美学基础"}],"more":"三体系：斯坦尼斯拉夫斯基（体验）、布莱希特（间离）、梅兰芳（写意）。","exam":[]},{"id":"b05-033","t":"关目","cid":"05h","p":3,"kind":"概念","alias":["戏曲关目","关目结构"],"one":"中国古代戏曲与小说批评术语，指剧情关键情节与结构布局安排。","ans":"关目是**中国古典戏曲与小说的核心批评术语**。它指戏曲剧作的**关键情节与结构布局安排**，即情节转折的关键节点。曲家常以“**关目好**”评赞剧本结构精巧。李渔在《闲情偶寄》中极重关目，该理论体现了**古代戏剧家对戏剧结构的自觉追求**。","pts":["中国古代戏曲情节与结构术语","指剧作关键情节布局与机纽关捩","曲论常赞“关目好”，李渔重结构"],"mem":"“戏曲关目如关节，结构布局最要紧”。关目好即情节跌宕生动、首尾连贯。","mix":"关目指戏曲小说的“情节结构与机纽”；“脚色/行当”指演员的行当类别；“曲牌”指唱腔曲调。","mcq":[{"q":"在中国古典戏曲批评理论中，用于指代剧情的关键情节节点及其整体结构布局安排的术语是","o":["行当","关目","曲牌","家门"],"a":1,"w":"“关目”指戏曲的情节关捩与结构布局，元明清评点常称“关目好”。"}],"rel":[{"t":"李渔","n":"曲论名家重关目结构"},{"t":"李渔《闲情偶寄》","n":"论述戏曲关目专著"},{"t":"梁辰鱼《浣纱记》","n":"明代传奇剧本代表"}],"exam":[]},{"id":"a05-001","t":"金文（钟鼎文）","cid":"05a","p":2,"kind":"概念","alias":["金文","钟鼎文","青铜器铭文"],"one":"铸刻在商周青铜器上的铭文，毛公鼎铭文最长。","ans":"金文又称**钟鼎文**，指**商周青铜器上的铭文**，盛行于西周。它上承甲骨文，下启大篆，字形线条圆润、笔画粗细富于变化，是汉字书体演变中的重要一环。著名铭文有**毛公鼎**（近500字，为现存青铜器铭文最长者）、大盂鼎和散氏盘等。金文多记载册命、征伐、土地契约与祭祀，是研究先秦历史的**第一手史料**。","pts":["商周青铜器上的铭文","毛公鼎近500字，铭文最长","承甲骨文、启大篆"],"mem":"书体排序线：**甲骨文（龟甲）→金文（青铜）→大篆→小篆→隶书→楷书**，按载体记：龟壳、铜器、石鼓、竹帛。“金”就是青铜，铜器上的字就是金文，钟和鼎是最典型的两种铜器。","mix":"甲骨文刻于龟甲兽骨，金文铸或刻于铜器，二者不要互换；后母戊鼎铭文只有3个字，字数最多的是毛公鼎。","mcq":[{"q":"现存青铜器铭文字数最多的是","o":["大盂鼎","后母戊鼎","散氏盘","毛公鼎"],"a":3,"w":"毛公鼎铭文近500字，居青铜器铭文之首；后母戊鼎仅3字。"}],"rel":[{"t":"毛公鼎","n":"铭文最长的铜器"},{"t":"甲骨文","n":"金文的前一书体"},{"t":"大篆、小篆与石鼓文","n":"金文的后续书体"},{"t":"汉字书体演变","n":"书体总线索"}],"more":"代表铜器：毛公鼎（西周，铭文近500字）、大盂鼎（西周康王时）、散氏盘（西周晚期，记土地契约）。","exam":[]},{"id":"a05-002","t":"大篆、小篆与石鼓文","cid":"05a","p":2,"kind":"概念","alias":["大篆","小篆","石鼓文","籀文"],"one":"大篆指秦统一前的古文字，小篆是秦统一后的标准字体。","ans":"**大篆**泛指秦统一前的古文字，包括金文、籀文和**石鼓文**。石鼓文刻在十个鼓形石上，为秦国刻石，常称**现存最早的石刻文字**。**小篆**是秦统一六国后，由**李斯**等人在秦国文字基础上整理简化的标准字体，《泰山刻石》《峄山刻石》是其代表。小篆是古文字的最后一站，此后隶变使汉字进入隶、楷阶段。","pts":["大篆含金文、籀文、石鼓文","石鼓文为秦国刻石，现存最早石刻","小篆为李斯整理的秦统一字体"],"mem":"大小以**先后**记：统一之前是“大”，统一之后是“小”，大篆繁、小篆简。小篆口诀“**李斯书同文，泰山峄山碑**”；石鼓记成“十面鼓，刻秦诗”。","mix":"石鼓文属大篆，不是小篆；小篆之后才是隶书，二者之间的变化称“隶变”。","mcq":[{"q":"关于石鼓文，下列说法正确的是","o":["汉代隶书刻石","秦国刻石，属大篆","唐代楷书刻石","李斯整理的小篆刻石"],"a":1,"w":"石鼓文为秦国刻石，属大篆，常称现存最早的石刻文字。"}],"rel":[{"t":"李斯","n":"小篆的整理推行者"},{"t":"金文（钟鼎文）","n":"大篆的前身之一"},{"t":"隶书与“隶变”","n":"小篆之后的书体"},{"t":"吴昌硕","n":"以石鼓文入书"},{"t":"汉字书体演变","n":"书体总线索"}],"more":"小篆刻石：《泰山刻石》《峄山刻石》；许慎《说文解字》以小篆为字头。","exam":[]},{"id":"a05-003","t":"隶书与“隶变”","cid":"05a","p":1,"kind":"概念","alias":["隶变","汉隶","秦隶","古隶","八分"],"one":"隶书笔画方折、蚕头燕尾，隶变是古文字转入今文字的分界。","ans":"隶书是**秦汉时通行的字体**，起于秦代的**秦隶（古隶）**，到东汉发展为成熟的**汉隶**。由篆书演变为隶书的过程称**“隶变”**，它把篆书圆转的线条改为**方折平直的笔画**，字形由长变扁，汉字从此失去象形面貌，因此隶变是**古文字与今文字的分界**。汉隶特点是**“蚕头燕尾”**，横画有波磔。汉碑名品有《曹全碑》《张迁碑》《乙瑛碑》《礼器碑》。隶书奠定了楷书的笔画基础，是汉字演变史的转折点。","pts":["秦隶到汉隶，蚕头燕尾","隶变是古今文字分界","汉碑：曹全碑、张迁碑、乙瑛碑、礼器碑"],"mem":"画面记：篆书像一根弯曲的铁丝，隶变是把铁丝剪成一段段直笔，所以汉字从“画物”变成“拼笔画”。隶书的横画像一条蚕，起笔圆如蚕头，收笔上挑如燕尾。汉碑四名品先记《曹全》（秀丽）和《张迁》（方正古朴），另两个《乙瑛》《礼器》可连成“乙礼”。","mix":"隶书与楷书都方正，区别在隶书扁平、有波磔，楷书方正、无蚕头燕尾；隶变发生在秦汉之际，不是汉末。“古隶”指秦隶，“八分”常指成熟的汉隶。","mcq":[{"q":"被视为古文字与今文字分界的汉字演变环节是","o":["隶变","小篆统一文字","楷书的成熟","甲骨文的出现"],"a":0,"w":"隶变使汉字摆脱象形线条，转入笔画化的今文字阶段。"},{"q":"下列碑刻中，属于汉代隶书名品的是","o":["《曹全碑》","《九成宫醴泉铭》","《多宝塔碑》","《玄秘塔碑》"],"a":0,"w":"《曹全碑》为汉隶；其余三碑都是唐代楷书。"}],"rel":[{"t":"汉字书体演变","n":"书体演变主线"},{"t":"大篆、小篆与石鼓文","n":"隶书的前身"},{"t":"楷书四大家","n":"隶书之后的楷书"},{"t":"碑学与帖学","n":"清代尊汉碑"}],"more":"汉碑名品：《曹全碑》（秀丽）、《张迁碑》（方古）、《乙瑛碑》《礼器碑》。\n传说秦代程邈整理隶书。","exam":[]},{"id":"a05-004","t":"草书：章草、今草、狂草","cid":"05a","p":2,"kind":"概念","alias":["章草","今草","狂草","草书"],"one":"草书三体：汉代章草、东汉张芝创今草、唐代张旭怀素狂草。","ans":"草书是书写快捷、笔画连绵的书体，历经三个阶段。**章草**出于汉代，由隶书草化而来，保留隶书的波磔。**今草**相传为东汉**张芝**所创，脱去隶书波磔，笔画连绵、上下牵连，王羲之将其推向成熟，张芝因此被称“草圣”。**狂草**盛于唐代，以**张旭、怀素**为代表，笔势奔放，世称“颠张醉素”。三体展现了草书由实用走向纯艺术的过程。","pts":["章草出于汉代，存隶书波磔","今草相传张芝所创","狂草盛于唐，张旭怀素代表"],"members":[["章草","汉代，隶书草化，保留波磔"],["今草","相传东汉张芝所创，王羲之成熟"],["狂草","唐代，张旭、怀素为代表"]],"mem":"按时间顺口溜：**汉章、晋今、唐狂**。章草像隶书“带尾巴”且字字独立，今草脱去波磔、上下牵连，狂草纵逸连绵如醉，正好对应唐人张旭“颠”、怀素“醉”。","mix":"“草圣”常指张芝，也指张旭，要看语境；章草、今草的发展早于狂草，不要把狂草当作最早的草书。","mcq":[{"q":"相传创造今草的书法家是","o":["史游","张旭","怀素","张芝"],"a":3,"w":"今草相传由东汉张芝所创；史游与章草相关，张旭、怀素属唐代狂草。"}],"rel":[{"t":"张旭、怀素","n":"狂草代表"},{"t":"王羲之","n":"今草的成熟者"},{"t":"书画称号：书圣、草圣、画圣","n":"草圣的称号"},{"t":"隶书与“隶变”","n":"章草的来源"}],"more":"代表作：张旭《古诗四帖》（传）、怀素《自叙帖》、王羲之《十七帖》（今草）。","exam":[]},{"id":"a05-005","t":"永字八法","cid":"05a","p":2,"kind":"概念","alias":["永字八法"],"one":"以“永”字八笔概括楷书基本笔法的传统方法。","ans":"永字八法是用“永”字八笔概括**楷书基本笔法**的传统方法，相传出自**王羲之**，一说为**隋代智永**所传。八笔为**侧**（点）、**勒**（横）、**努**（竖）、**趯**（钩）、**策**（提）、**掠**（长撇）、**啄**（短撇）、**磔**（捺）。因“永”字几乎包含楷书所有基本笔画，它成为历代学书者入门必练的法则。","pts":["以“永”字八笔概括楷书笔法","侧勒努趯策掠啄磔","相传出自王羲之或智永"],"members":[["侧","点"],["勒","横"],["努","竖"],["趯","钩"],["策","提"],["掠","长撇"],["啄","短撇"],["磔","捺"]],"mem":"八字口诀**“侧勒努趯，策掠啄磔”**，现代说法对应“点、横、竖、钩，提、撇、撇、捺”。画面：一个“永”字，写完八种笔画都练到了。","mix":"永字八法讲的是笔画，不是八种书体；出处有王羲之与智永两说，考题多取“相传王羲之”。","mcq":[{"q":"“永字八法”概括的是哪种书体的基本笔法","o":["篆书","隶书","楷书","草书"],"a":2,"w":"永字八法以“永”字八笔概括楷书基本笔画。"}],"rel":[{"t":"王羲之","n":"相传创始人"},{"t":"楷书四大家","n":"楷书笔法传承"},{"t":"钟繇","n":"楷书鼻祖"},{"t":"汉字书体演变","n":"楷书所处阶段"}],"more":"八法对应：侧（点）、勒（横）、努（竖）、趯（钩）、策（提）、掠（长撇）、啄（短撇）、磔（捺）。","exam":[]},{"id":"a05-006","t":"碑学与帖学","cid":"05a","p":3,"kind":"概念","alias":["碑帖","北碑南帖"],"one":"中国书法史上以北碑和南帖为宗的两大流派与学风。","ans":"碑学与帖学指**清代以来中国书法史上的两大书风流派**。帖学以魏晋**二王法帖**为正宗，重用笔风韵；碑学在清中期兴起，阮元作《南北书派论》提倡**北朝石刻碑版**，包世臣与康有为力主北碑。两派互补促成了**清代书法的碑帖融合变革**。","pts":["清代形成的书法两大书风流派","帖学宗二王法帖，尚风韵气度","阮元与康有为倡导北碑金石气"],"mem":"“南帖重韵宗二王，北碑尚力阮康倡”。帖如手札秀丽，碑如石刻沉雄。","mix":"帖学重墨迹法帖之流美韵致，碑学重摩崖碑刻之金石气；阮元《南北书派论》将两派明确分立。","mcq":[{"q":"清代中期撰写《南北书派论》《北碑南帖论》，力倡北碑的书法理论家是","o":["阮元","包世臣","康有为","刘墉"],"a":0,"w":"阮元撰《南北书派论》《北碑南帖论》，开启了清代尊碑抑帖的风气。"}],"rel":[{"t":"王羲之","n":"帖学奉二王为正宗"},{"t":"文房四宝","n":"书写工具基础"},{"t":"楷书四大家","n":"法帖名家流派"}],"exam":[]},{"id":"a05-007","t":"篆刻与西泠印社","cid":"05a","p":2,"kind":"概念","alias":["篆刻","西泠印社"],"one":"篆刻是刻印的艺术；西泠印社1904年创于杭州，吴昌硕任首任社长。","ans":"篆刻是以**篆书入印**、用刀在印材上镌刻的艺术，融书法与刻刀于一体，是书法的旁支。明清时形成徽派、浙派等流派。**西泠印社**1904年由丁仁、王禔、吴隐、叶铭创立于**杭州西湖孤山**，宗旨为保存金石、研究印学，**吴昌硕**为首任社长，被誉为“天下第一社”。“**中国篆刻艺术**”于**2009年**列入人类非遗代表作名录。","pts":["篆书入印的刻印艺术","西泠印社1904年杭州，吴昌硕首任社长","中国篆刻艺术2009年入人类非遗"],"mem":"年份串：**1904**成社（西泠印社）、**2009**入遗。画面：杭州西湖孤山上一群人刻印，社长是“诗书画印四绝”的吴昌硕。印面记忆：红字叫朱文（阳刻），白字叫白文（阴刻）。","mix":"西泠印社在杭州，不在上海；吴昌硕晚年居上海，常被误认为社址在上海。浙派“西泠八家”与西泠印社名称相近，但前者是清代流派，后者是近代社团。","mcq":[{"q":"西泠印社的首任社长是","o":["齐白石","吴昌硕","张大千","徐悲鸿"],"a":1,"w":"吴昌硕为西泠印社首任社长，社址在杭州西湖孤山。"}],"rel":[{"t":"吴昌硕","n":"首任社长"},{"t":"人类非遗代表作中国项目","n":"篆刻2009年入遗"},{"t":"海上画派","n":"吴昌硕所属画派"},{"t":"大篆、小篆与石鼓文","n":"印文所用篆体"}],"more":"创社人：丁仁、王禔、吴隐、叶铭；2009年“中国篆刻艺术”（西泠印社申报）列入人类非遗代表作名录。","exam":[]},{"id":"a05-009","t":"宣纸","cid":"05a","p":3,"kind":"常识","alias":["宣城纸","泾县宣纸"],"one":"产于安徽泾县的中国传统书画用纸，文房名品。","ans":"宣纸是**中国传统的书画名纸与文房名品**。它产于**安徽泾县**（古属宣州），以青檀树皮与沙田稻草为原料制成。宣纸质地绵韧、耐老化，有“**纸寿千年**、墨韵万变”之称。2009年“宣纸传统制作技艺”列入联合国**人类非遗**名录。","pts":["安徽泾县特产，文房名品","以青檀皮制成，纸寿千年","2009年列入人类非遗名录"],"mem":"“宣城泾县出宣纸，青檀稻草寿千年”。2009年列入联合国人类非遗名录。","mix":"宣纸产自安徽泾县（因唐宋隶属宣州府得名），而非宣城本地；文房四宝之纸以宣纸为代表。","mcq":[{"q":"被誉为“纸寿千年”，2009年传统制作技艺列入联合国人类非遗名录的传统书画用纸是","o":["澄心堂纸","宣纸","麻纸","竹纸"],"a":1,"w":"宣纸产于安徽泾县，具有韧而润、耐老化的特点，2009年列入人类非遗。"}],"rel":[{"t":"文房四宝","n":"宣纸居四宝之列"},{"t":"造纸术","n":"中国传统造纸发展"},{"t":"非物质文化遗产","n":"宣纸技艺入选人类非遗"}],"exam":[]},{"id":"a05-010","t":"钟繇","cid":"05b","p":2,"kind":"人物","alias":["钟太傅","钟元常"],"one":"三国魏书法家，被尊为楷书鼻祖，代表作《宣示表》。","ans":"钟繇（151–230）是**三国曹魏**重臣、书法家，官至太傅，世称“钟太傅”。他被尊为**楷书鼻祖**，将隶书向楷书推进，奠定了楷书的基本形态。代表作有**《宣示表》**《贺捷表》《荐季直表》。他与东晋**王羲之**并称“**钟王**”，与东汉草书家张芝并称“**钟张**”，其书风影响了王羲之等后世书家，是魏晋书法的开创者。","pts":["三国魏人，楷书鼻祖","代表作《宣示表》","与王羲之并称“钟王”，与张芝并称“钟张”"],"mem":"一句话：**钟繇开楷，王羲之成圣**。并称口诀“**钟王**（楷行）、**钟张**（楷草）”：钟繇搭王羲之是书体接力，搭张芝是书体互补。","mix":"楷书鼻祖是钟繇，不是王羲之；王羲之是“书圣”，《兰亭集序》是行书，不是楷书。","mcq":[{"q":"被尊为“楷书鼻祖”的书法家是","o":["钟繇","王羲之","颜真卿","欧阳询"],"a":0,"w":"钟繇为三国魏书法家，被尊为楷书鼻祖；王羲之为书圣。"}],"rel":[{"t":"王羲之","n":"并称“钟王”"},{"t":"楷书四大家","n":"后世楷书代表"},{"t":"永字八法","n":"楷书笔法"},{"t":"草书：章草、今草、狂草","n":"“钟张”的张芝"}],"more":"代表作：《宣示表》《贺捷表》《荐季直表》。","exam":[]},{"id":"a05-011","t":"王献之与“二王”","cid":"05b","p":2,"kind":"人物","alias":["王献之","二王","小王","王大令"],"one":"王羲之第七子，与父并称“二王”，《洛神赋十三行》。","ans":"王献之（344–386）是**东晋书法家**，**王羲之第七子**，官至中书令，世称“王大令”“小王”。他与父亲合称“**二王**”，书风比父亲更为妍丽流畅，尤擅行草，将东汉张芝所创“一笔书”推向纵逸贯通的高峰。传世作品有**《洛神赋十三行》**（楷书）、《中秋帖》（传）和《鸭头丸帖》。《中秋帖》与王羲之《快雪时晴帖》等并为乾隆“**三希**”之一。","pts":["东晋，王羲之第七子，称“小王”","与父并称“二王”","《洛神赋十三行》《中秋帖》《鸭头丸帖》"],"mem":"**父大子小**：王羲之“大王”（书圣），王献之“小王”。三件作品配三个词：**洛神**（赋十三行）、**中秋**（帖，三希之一）、**鸭头**（丸帖）。","mix":"“二王”指王羲之、王献之父子；《洛神赋图》是顾恺之的画，《洛神赋十三行》是王献之的字，同题不同人。","mcq":[{"q":"下列书法作品，属于王献之的是","o":["《快雪时晴帖》","《洛神赋十三行》","《兰亭集序》","《平复帖》"],"a":1,"w":"《洛神赋十三行》为王献之所书；《兰亭集序》《快雪时晴帖》为王羲之；《平复帖》为西晋陆机。"}],"rel":[{"t":"王羲之","n":"父亲，书圣"},{"t":"三希堂“三希”","n":"《中秋帖》为其一"},{"t":"《兰亭集序》","n":"其父名作"},{"t":"顾恺之","n":"同题《洛神赋图》作者"}],"more":"传世作品：《洛神赋十三行》《中秋帖》（传）、《鸭头丸帖》。","exam":[]},{"id":"a05-012","t":"《兰亭集序》","cid":"05b","p":1,"kind":"作品","alias":["兰亭序","兰亭帖","禊帖","临河序","兰亭修禊"],"one":"王羲之行书，东晋永和九年兰亭修禊所作，天下第一行书。","ans":"《兰亭集序》是**东晋书法家王羲之的行书作品**，作于**永和九年（353 年）三月三日**，王羲之与谢安、孙绰等名士在**会稽山阴兰亭修禊**，众人赋诗成集，王羲之为诗集作序。全文**28 行 324 字**，先写宴游之乐，后感叹生死无常，文中“之”字写法各异。它被誉为**“天下第一行书”**。真迹相传随唐太宗葬入昭陵，今传**冯承素“神龙本”**等摹本，藏北京故宫博物院。此帖集中体现了王羲之书风的自然流美，是行书的最高典范。","pts":["永和九年三月三日兰亭修禊","28 行 324 字，天下第一行书","真迹随唐太宗入昭陵，冯承素神龙本最著名"],"mem":"时间记“永和九年，三月三日，上巳节，在兰亭”。数字记“28 行 324 字”：28 行，324 字，324 恰好等于 18 的平方。真迹去向记一句话：“太宗爱帖，带进昭陵”。摹本记“神龙”：卷首有“神龙”半印，所以叫神龙本，摹者冯承素。","mix":"《兰亭集序》是书法作品，也是一篇文学名篇；它是行书，不是楷书；真迹已佚，现存的都是摹本；与《祭侄文稿》《黄州寒食诗帖》并称三大行书，但排第一。","mcq":[{"q":"《兰亭集序》作于","o":["唐贞观十年","东晋永和九年","南朝宋永初元年","西晋永嘉元年"],"a":1,"w":"永和九年即 353 年，三月三日修禊。"},{"q":"关于《兰亭集序》，下列说法正确的是","o":["真迹现藏北京故宫","书体为楷书","作者是颜真卿","被称为“天下第一行书”"],"a":3,"w":"天下第一行书；真迹已佚，传世为摹本。"}],"rel":[{"t":"王羲之","n":"作者"},{"t":"天下三大行书","n":"位居第一"},{"t":"《黄州寒食诗帖》","n":"第三行书"},{"t":"寒食节与清明节","n":"古代上巳、寒食并为春季节日"}],"more":"名句：永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。｜《兰亭集序》\n天朗气清，惠风和畅。｜《兰亭集序》\n后之视今，亦犹今之视昔。｜《兰亭集序》\n神龙本为唐代冯承素摹，卷首有“神龙”半印。","exam":[]},{"id":"a05-013","t":"《祭侄文稿》","cid":"05b","p":2,"kind":"作品","alias":["祭侄稿","祭侄季明文稿"],"one":"颜真卿悼念殉难侄子的行草文稿，“天下第二行书”。","ans":"《祭侄文稿》是**唐代颜真卿**于**758年**所书的行草文稿，为祭奠在**安史之乱**中为国殉难的侄子**颜季明**而作。全篇悲愤激荡，字迹随情绪起伏，涂改之处俯拾皆是，并非刻意求工的作品。它与王羲之《兰亭集序》、苏轼《黄州寒食诗帖》并称**“天下三大行书”**，被誉为“**天下第二行书**”，现藏**台北故宫博物院**。","pts":["颜真卿758年为侄子颜季明所作","安史之乱中殉难的悲愤","天下第二行书，藏台北故宫"],"mem":"三大行书按**排名**：王羲之《兰亭》第一（晋）、颜真卿《祭侄》第二（唐）、苏轼《寒食》第三（宋）。朝代也是晋、唐、宋，顺着排下来；《祭侄》的关键词是“安史之乱”和“悲”。","mix":"《祭侄文稿》是行草，不是楷书；颜真卿的楷书代表作是《多宝塔碑》，行书代表作才是《祭侄文稿》。","mcq":[{"q":"被誉为“天下第二行书”的作品是","o":["《兰亭集序》","《黄州寒食诗帖》","《自叙帖》","《祭侄文稿》"],"a":3,"w":"《祭侄文稿》为颜真卿所作，称天下第二行书；《兰亭集序》第一，《黄州寒食诗帖》第三。"}],"rel":[{"t":"颜真卿","n":"作者"},{"t":"天下三大行书","n":"所属合称"},{"t":"安史之乱","n":"写作背景"},{"t":"《兰亭集序》","n":"天下第一行书"}],"more":"作于唐乾元元年（758）；其堂兄颜杲卿、从侄颜季明在安史之乱中殉难。","exam":[]},{"id":"a05-014","t":"《黄州寒食诗帖》","cid":"05b","p":2,"kind":"作品","alias":["寒食帖","黄州寒食帖","苏轼寒食帖"],"one":"苏轼贬黄州所作行书，天下第三行书。","ans":"《黄州寒食诗帖》又称《寒食帖》，是**北宋苏轼**于**元丰五年（1082）**被贬**黄州**时所书的两首寒食诗，行书。诗写贬谪中的凄苦与失意，字体随情绪由小渐大，起伏奔放。后有**黄庭坚题跋**，称其笔势“兼颜鲁公、杨少师、李西台笔意”。它与《兰亭集序》《祭侄文稿》合称**“天下三大行书”**，被誉为“**天下第三行书**”，现藏**台北故宫博物院**。","pts":["苏轼1082年贬黄州所作","后有黄庭坚题跋","天下第三行书，藏台北故宫"],"mem":"**三三三**：苏轼是宋四家之首，《寒食帖》排**第三**，写在贬谪**黄州**第三个寒食节（元丰五年，诗中即有“已过三寒食”之句）。三大行书顺序为兰亭、祭侄、寒食，对应王、颜、苏。","mix":"黄庭坚是题跋者，不是作者；该帖是行书，不是楷书。三大行书藏地：《兰亭集序》真迹已佚，《祭侄文稿》与《寒食帖》同藏台北故宫。","mcq":[{"q":"《黄州寒食诗帖》的作者是","o":["黄庭坚","米芾","蔡襄","苏轼"],"a":3,"w":"《黄州寒食诗帖》为苏轼所书，黄庭坚仅题跋。"}],"rel":[{"t":"苏轼","n":"作者"},{"t":"黄庭坚","n":"题跋者"},{"t":"天下三大行书","n":"所属合称"},{"t":"《祭侄文稿》","n":"天下第二行书"}],"more":"苏轼《寒食雨》诗：自我来黄州，已过三寒食。｜《黄州寒食诗帖》","exam":[]},{"id":"a05-015","t":"欧阳询","cid":"05b","p":2,"kind":"人物","alias":["欧体","欧阳率更","大小欧"],"one":"初唐楷书家，欧体险劲严整，《九成宫醴泉铭》。","ans":"欧阳询（557–641）是**初唐书法家**，官至太子率更令，世称“欧阳率更”。他的楷书称“**欧体**”，结构**险劲严整**，法度森严，是**楷书四大家**之一，又列**初唐四家**。代表作为**《九成宫醴泉铭》**，被誉为“楷书极则”，另有《皇甫诞碑》《化度寺碑》。其子欧阳通亦善书，父子并称“**大小欧**”。","pts":["初唐，欧体，险劲严整","《九成宫醴泉铭》","楷书四大家，大小欧"],"mem":"自编对比：**欧体险硬、颜体丰厚、柳体劲瘦、赵体圆润**。代表作《九成宫醴泉铭》记成“**九成宫的泉水**”；欧在“欧虞褚薛”里排第一。","mix":"欧阳询与虞世南、褚遂良、薛稷合称初唐四家，与颜、柳、赵合称楷书四大家，两个合称里欧阳询都出现，选择题常拿这两个合称互相做干扰项。","mcq":[{"q":"《九成宫醴泉铭》的作者是","o":["颜真卿","柳公权","欧阳询","赵孟頫"],"a":2,"w":"《九成宫醴泉铭》为欧阳询楷书代表作；颜柳赵各有《多宝塔碑》《玄秘塔碑》《胆巴碑》。"}],"rel":[{"t":"楷书四大家","n":"欧颜柳赵之首"},{"t":"初唐四家（书法）","n":"欧虞褚薛之首"},{"t":"柳公权","n":"同为楷书四大家"},{"t":"颜真卿","n":"同为楷书四大家"}],"more":"代表作：《九成宫醴泉铭》《皇甫诞碑》《化度寺碑》；《行书千字文》《卜商帖》。","exam":[]},{"id":"a05-016","t":"柳公权","cid":"05b","p":2,"kind":"人物","alias":["柳体","柳少师"],"one":"晚唐楷书家，柳体，《玄秘塔碑》，与颜真卿并称“颜筋柳骨”。","ans":"柳公权（778–865）是**晚唐书法家**，官至太子少师，世称“柳少师”。他的楷书称“**柳体**”，骨力劲健，结体紧凑，是**楷书四大家**之一。代表作有**《玄秘塔碑》**和《神策军碑》。他与**颜真卿**并称“**颜筋柳骨**”。相传唐穆宗问用笔之法，他答“**用笔在心，心正则笔正**”，以笔谏君，此语成为书法与品行关系的名言。","pts":["晚唐，柳体，骨力劲健","《玄秘塔碑》《神策军碑》","颜筋柳骨；心正则笔正"],"mem":"**“颜筋柳骨”**：颜字肉丰筋强，柳字骨瘦力劲，一个“筋”一个“骨”，对应颜真卿、柳公权。“心正则笔正”可以联想为：**柳**公权劝**穆**宗，字正先正心。","mix":"“颜筋柳骨”中，颜是筋，柳是骨，不要对调；柳公权是晚唐，欧阳询是初唐，颜真卿是盛中唐。","mcq":[{"q":"以“心正则笔正”劝谏唐穆宗的书法家是","o":["颜真卿","欧阳询","虞世南","柳公权"],"a":3,"w":"柳公权答唐穆宗问笔法时说“用笔在心，心正则笔正”。"}],"rel":[{"t":"颜真卿","n":"并称“颜筋柳骨”"},{"t":"楷书四大家","n":"欧颜柳赵之一"},{"t":"欧阳询","n":"同为楷书四大家"},{"t":"赵孟頫","n":"楷书四大家之殿"}],"more":"代表作：《玄秘塔碑》《神策军碑》；“用笔在心，心正则笔正”。","exam":[]},{"id":"a05-017","t":"赵孟頫","cid":"05b","p":2,"kind":"人物","alias":["赵体","赵子昂","松雪道人","赵松雪"],"one":"宋宗室入元为官，赵体，楷书四大家中唯一的元代书家。","ans":"赵孟頫（1254–1322），字子昂，号松雪道人，**浙江吴兴人**，是**宋朝宗室**，入元后官至翰林学士承旨。他书画兼擅，楷书称“**赵体**”，圆润秀逸，为**楷书四大家**中唯一的元代书家，代表作有**《胆巴碑》**。绘画倡“书画同源”与复古，有《鹊华秋色图》。其妻**管道昇**也善书画，尤擅墨竹。他的复古主张影响了元代书画的走向。","pts":["宋宗室入元，赵体","《胆巴碑》；画《鹊华秋色图》","楷书四大家中唯一元代；妻管道昇"],"mem":"**欧颜柳赵**四位，只有赵孟頫是**元代**，其余三位都是唐代，可记成“三唐一元”。人物故事：宋朝皇族出仕元朝，所以字里带“秀媚”，“赵体”就是圆润秀美的代名词。","mix":"楷书四大家（欧颜柳赵）与初唐四家（欧虞褚薛）、宋四家（苏黄米蔡）要分清；赵孟頫既是书法家又是画家，《鹊华秋色图》是其画作。","mcq":[{"q":"楷书四大家中唯一的元代书法家是","o":["赵孟頫","柳公权","颜真卿","欧阳询"],"a":0,"w":"欧阳询、颜真卿、柳公权为唐人，赵孟頫为元人。"}],"rel":[{"t":"楷书四大家","n":"欧颜柳赵之殿"},{"t":"元四家","n":"同属元代书画潮流"},{"t":"柳公权","n":"同为楷书四大家"},{"t":"宋徽宗赵佶","n":"同为赵氏宗室书画家"}],"more":"代表作：《胆巴碑》（楷书）、《鹊华秋色图》（画）；管道昇《墨竹图》。","exam":[]},{"id":"a05-018","t":"初唐四家（书法）","cid":"05b","p":2,"kind":"合称","alias":["初唐四家","欧虞褚薛","初唐四大家"],"one":"欧阳询、虞世南、褚遂良、薛稷，初唐书法四家。","ans":"初唐四家指**唐代初年四位书法家欧阳询、虞世南、褚遂良、薛稷**，简称“**欧虞褚薛**”。欧阳询楷书险劲，有**《九成宫醴泉铭》**；虞世南书风圆润，有**《孔子庙堂碑》**；褚遂良书风清秀，有**《雁塔圣教序》**；薛稷以画鹤闻名。四家开创了唐代楷书法度，对**颜真卿、柳公权**等中晚唐书法家影响深远。","pts":["欧阳询、虞世南、褚遂良、薛稷","九成宫醴泉铭、孔子庙堂碑、雁塔圣教序","奠定唐楷法度"],"members":[["欧阳询","《九成宫醴泉铭》，险劲"],["虞世南","《孔子庙堂碑》，圆润"],["褚遂良","《雁塔圣教序》，清秀"],["薛稷","书画兼擅，善画鹤"]],"mem":"口诀**“欧虞褚薛”**。配对记忆：欧（醴泉）、虞（庙堂）、褚（雁塔）：**欧泉虞堂褚雁塔**，薛稷最后，记他“画鹤”。时间：四人都在唐初，早于颜、柳。","mix":"与“楷书四大家”（欧颜柳赵）只有欧阳询重合，选择题常用颜柳赵作干扰项；另有以陆柬之代薛稷的说法，通行为薛稷。","mcq":[{"q":"下列书法家中，不属于“初唐四家”的是","o":["欧阳询","虞世南","颜真卿","褚遂良"],"a":2,"w":"初唐四家是欧阳询、虞世南、褚遂良、薛稷；颜真卿属盛中唐。"}],"rel":[{"t":"欧阳询","n":"四家之首"},{"t":"楷书四大家","n":"欧阳询同在，易混"},{"t":"颜真卿","n":"常作干扰项"},{"t":"宋四家","n":"另一组数字合称"}],"more":"代表作：虞世南《孔子庙堂碑》，褚遂良《雁塔圣教序》《孟法师碑》。","exam":[]},{"id":"a05-019","t":"米芾","cid":"05b","p":2,"kind":"人物","alias":["米元章","米南宫","米颠","海岳外史"],"one":"北宋书画家，宋四家之一，号“米颠”，《蜀素帖》。","ans":"米芾（1051–1107），字元章，**襄阳人**，**北宋书画家**，列**宋四家**（苏黄米蔡）。他性情狂放，好石成癖，向奇石下拜，人称“**米颠**”。书法行书、草书用笔俊迈，代表作有**《蜀素帖》**《苕溪诗帖》。绘画以**横点皴**画江南烟云，称“**米氏云山**”，其子**米友仁**继承并发展，父子并称“大米、小米”。他著有《书史》《画史》。","pts":["北宋，宋四家，号米颠","《蜀素帖》《苕溪诗帖》","米氏云山，子米友仁"],"mem":"画面记忆：一个人对着一块奇石**拜**，称石头为“兄”，所以叫“米颠”。作品记两个“素”“溪”：**蜀素帖、苕溪诗帖**。绘画“米点”是横点，**云山**像雨后烟云。","mix":"宋四家的“米”指米芾，不要与其子米友仁（“小米”）混淆；宋四家另有以蔡京代蔡襄的说法，通行为苏黄米蔡。","mcq":[{"q":"北宋书画家米芾的代表书法作品是","o":["《蜀素帖》","《自叙帖》","《祭侄文稿》","《快雪时晴帖》"],"a":0,"w":"《蜀素帖》为米芾所书；《自叙帖》为怀素，《祭侄文稿》为颜真卿。"}],"rel":[{"t":"宋四家","n":"苏黄米蔡之一"},{"t":"苏轼","n":"同属宋四家"},{"t":"黄庭坚","n":"同属宋四家"},{"t":"文人画","n":"米氏云山属文人画"}],"more":"著作：《书史》《画史》《宝章待访录》；作品：《蜀素帖》《苕溪诗帖》。","exam":[]},{"id":"a05-020","t":"《平复帖》","cid":"05b","p":3,"kind":"作品","alias":["陆机平复帖"],"one":"西晋陆机书写的章草法帖，现存最早的名人书法真迹。","ans":"《平复帖》是**西晋文学家、书法家陆机**创作的章草墨迹。全帖共9行84字，写在麻纸上，内容为问候友人体疾。它是**中国现存最早的名人书法真迹**，被后世尊为“**法帖之祖**”与“墨皇”。近代由张伯驹捐献国家，现藏于**北京故宫博物院**。","pts":["西晋陆机所书章草法帖","现存最早的名人书法真迹，法帖之祖","近代张伯驹捐献，藏故宫博物院"],"mem":"“西晋陆机平复帖，现存最早第一真”。章草写在麻纸上，张伯驹捐故宫。","mix":"《平复帖》是现存最早的名人“墨迹真迹”；王羲之《兰亭集序》传世均为唐代摹本，非原始墨迹真迹。","mcq":[{"q":"被誉为“法帖之祖”，中国现存最早的名人书法真迹是","o":["王羲之《兰亭集序》","钟繇《宣示表》","陆机《平复帖》","王献之《中秋帖》"],"a":2,"w":"西晋陆机《平复帖》是中国现存年代最早的名人书法真迹，现藏北京故宫博物院。"}],"rel":[{"t":"陆机","n":"法帖作者西晋陆机"},{"t":"陆机《文赋》","n":"陆机文论代表作"},{"t":"《兰亭集序》","n":"东晋著名行书法帖"}],"exam":[]},{"id":"a05-021","t":"三希堂“三希”","cid":"05b","p":3,"kind":"合称","alias":["三希","三希堂法帖"],"one":"清乾隆帝养心殿三希堂所藏三件东晋著名法帖。","ans":"三希堂“三希”指**清乾隆帝养心殿三希堂珍藏的三件东晋法帖**。包括**王羲之《快雪时晴帖》**、**王献之《中秋帖》**与**王珣《伯远帖》**。堂名兼含稀世法帖与“**士希贤**”之意。现《快雪时晴帖》藏台北故宫博物院，后两件藏北京故宫。","pts":["乾隆养心殿三希堂藏东晋三帖","王羲之快雪、王献之中秋、王珣伯远","快雪帖在台北，中秋伯远在北京"],"mem":"“快雪时晴王羲之，中秋献之伯远珣”。一帖在台北故宫，两帖在北京故宫。","mix":"三希中王珣《伯远帖》是东晋墨迹真迹；王羲之《快雪时晴帖》为唐摹本；王献之《中秋帖》传为宋代米芾临本。","mcq":[{"q":"乾隆帝三希堂珍藏的三件东晋法帖中，现藏于台北故宫博物院的是","o":["王珣《伯远帖》","王献之《中秋帖》","陆机《平复帖》","王羲之《快雪时晴帖》"],"a":3,"w":"《快雪时晴帖》藏于台北故宫博物院，《中秋帖》《伯远帖》均藏于北京故宫博物院。"}],"rel":[{"t":"王羲之","n":"快雪时晴帖作者"},{"t":"《平复帖》","n":"同为晋代法帖名迹"},{"t":"《兰亭集序》","n":"天下第一行书"}],"members":[["《快雪时晴帖》","东晋王羲之行书，现藏台北故宫博物院"],["《中秋帖》","东晋王献之草书（传宋米芾临），现藏故宫博物院"],["《伯远帖》","东晋王珣行书东晋真迹，现藏故宫博物院"]],"exam":[]},{"id":"a05-022","t":"书画称号：书圣、草圣、画圣","cid":"05b","p":1,"kind":"合称","alias":["书圣草圣画圣","三绝"],"one":"书圣王羲之，草圣张旭，画圣吴道子；顾恺之称三绝。","ans":"书画称号是**后世对书画大家的尊称**：**书圣指东晋王羲之，草圣指唐代张旭，画圣指唐代吴道子**。王羲之以《兰亭集序》为代表，对行书的成熟贡献最大；张旭擅**狂草**，嗜酒挥毫；吴道子擅**佛道人物和山水**，人物衣纹有**“吴带当风”**之誉。此外，**顾恺之**被称“**才绝、画绝、痴绝**”三绝，唐文宗曾诏以**李白诗歌、裴旻剑舞、张旭草书**为“三绝”。这些称号集中体现了书画史上的最高地位。","pts":["书圣王羲之，草圣张旭，画圣吴道子","顾恺之才绝画绝痴绝","唐文宗三绝：李白诗、裴旻剑、张旭草书"],"members":[["书圣","王羲之，东晋"],["草圣","张旭，唐（东汉张芝亦称草圣）"],["画圣","吴道子，唐"],["顾恺之三绝","才绝、画绝、痴绝"]],"mem":"三个称号按书、草、画对三个人：王、张、吴，顺口记“王书张草吴画”。朝代线：晋（王）、唐（张）、唐（吴）。“三绝”分两套：顾恺之的才画痴，唐文宗的诗剑草（李白、裴旻、张旭）。","mix":"“诗仙李白、诗圣杜甫、诗佛王维”是诗人称号，不要和“书圣、草圣、画圣”混；草圣有东汉张芝与唐代张旭两说，唐代题目指张旭；吴道子称画圣，顾恺之不称画圣。","mcq":[{"q":"下列称号与人物对应，正确的是","o":["画圣：阎立本","书圣：王羲之","画圣：顾恺之","草圣：怀素"],"a":1,"w":"画圣为吴道子，草圣为张旭。"},{"q":"“才绝、画绝、痴绝”称誉的是","o":["顾恺之","王羲之","吴道子","张旭"],"a":0,"w":"《晋书》载顾恺之有三绝。"}],"rel":[{"t":"王羲之","n":"书圣"},{"t":"张旭、怀素","n":"草圣所在"},{"t":"吴道子","n":"画圣"},{"t":"顾恺之","n":"三绝"},{"t":"唐代诗人称号：诗仙、诗圣、诗佛、诗鬼、诗豪、诗魔","n":"同类称号题，常对举"}],"more":"杜甫《饮中八仙歌》称张旭为“草圣”。\n唐文宗诏以李白歌诗、裴旻剑舞、张旭草书为“三绝”（传）。","exam":[]},{"id":"a05-023","t":"谢赫“六法”","cid":"05c","p":1,"kind":"概念","alias":["六法","绘画六法","古画品录","谢赫"],"one":"南齐谢赫《古画品录》提出的绘画品评标准，首条“气韵生动”。","ans":"谢赫“六法”是**南齐画家谢赫在《古画品录》中提出的绘画品评标准**，是中国古代最重要的绘画理论之一。六法依次为：**气韵生动、骨法用笔、应物象形、随类赋彩、经营位置、传移模写**。其中**“气韵生动”**居首，要求画面传达人物神采与生命力；“骨法用笔”讲笔力，“应物象形”讲造型，“随类赋彩”讲设色，“经营位置”讲构图，“传移模写”讲临摹。六法为后世画论确立了基本框架，**气韵**成为评价中国画的最高标准。","pts":["南齐谢赫《古画品录》提出","气韵生动居首","六法：气骨应随经传"],"mem":"自编首字口诀：气、骨、应、随、经、传，连成“气骨应随经传”。逻辑线也能记：先问有没有“神”（气韵），再看笔（骨法），再看形（应物）、色（随类）、构图（经营），最后是学习方法（传移模写）。一个“从精神到技法”的由内到外顺序。","mix":"顾恺之提出“以形写神”，谢赫提出“六法”，同属六朝画论，注意不要互换；六法中“随类赋彩”讲的是设色，“传移模写”讲的是临摹，不是印刷或移动。","mcq":[{"q":"“六法”中位居第一的是","o":["经营位置","骨法用笔","应物象形","气韵生动"],"a":3,"w":"六法以气韵生动为首。"},{"q":"提出“六法”的画论著作是","o":["《论画》","《古画品录》","《画语录》","《历代名画记》"],"a":1,"w":"南齐谢赫《古画品录》。《画语录》是石涛的。"}],"rel":[{"t":"顾恺之","n":"同期画论“传神”"},{"t":"石涛与《画语录》","n":"清代画论对举"},{"t":"文人画","n":"重气韵的传统延续"},{"t":"《洛神赋图》","n":"六法可评的早期画作"}],"more":"六法：气韵生动、骨法用笔、应物象形、随类赋彩、经营位置、传移模写。","exam":[]},{"id":"a05-024","t":"《洛神赋图》","cid":"05c","p":1,"kind":"作品","alias":["洛神赋图","洛神图"],"one":"顾恺之据曹植《洛神赋》所绘的连环长卷，今存宋摹本。","ans":"《洛神赋图》是**东晋画家顾恺之根据曹植《洛神赋》绘制的人物画长卷**。画面以**连环画形式**展开，同一人物在不同场景中重复出现，依次描绘曹植与洛神相遇、倾慕、离别的情节，山水树石作衬景。作品体现顾恺之**“以形写神”**的主张，线条如春蚕吐丝，细劲连绵。原作已佚，现存**宋代摹本**，北京故宫博物院等处有藏本。它是现存早期人物画与叙事画的重要代表，对后世人物画和山水画影响很大。","pts":["顾恺之据曹植《洛神赋》绘","连环长卷，同一人物重复出现","原作已佚，现存宋摹本"],"mem":"两个“洛”记两个作者：洛神出自曹植的赋，图出自顾恺之的画，一文一画。画面像一部“连环画”：曹植站在岸边，洛神在水上，几次出场。别和《女史箴图》混：箴图写宫廷女史箴言（劝诫），洛神写爱情梦幻。","mix":"《洛神赋图》和《女史箴图》都是顾恺之名下的作品，都只有摹本；赋的作者是曹植，不是曹丕；现存《洛神赋图》为宋代摹本，不是东晋原作。","mcq":[{"q":"《洛神赋图》所依据的文学作品作者是","o":["曹操","曹丕","陶渊明","曹植"],"a":3,"w":"曹植《洛神赋》。"},{"q":"关于《洛神赋图》，下列说法正确的是","o":["描绘唐太宗接见使者","作者是阎立本","现存为宋代摹本","属于山水画"],"a":2,"w":"作者是顾恺之，原作已佚，现存宋代摹本。"}],"rel":[{"t":"顾恺之","n":"作者"},{"t":"曹植《洛神赋》","n":"画作依据"},{"t":"谢赫“六法”","n":"同期画论"},{"t":"《步辇图》","n":"早期人物画对举"}],"more":"顾恺之另有《女史箴图》（唐摹本，藏大英博物馆）。","exam":[]},{"id":"a05-025","t":"《女史箴图》","cid":"05c","p":2,"kind":"作品","alias":["女史箴图"],"one":"顾恺之据张华《女史箴》所绘，现存唐摹本藏大英博物馆。","ans":"《女史箴图》是**东晋顾恺之**依据西晋**张华**的《女史箴》所绘的人物画卷，内容是以故事规劝宫廷妇女遵守妇德，如“冯婕妤当熊”一段。画中线条如春蚕吐丝，体现“**以形写神**”。现存为**唐代摹本**，原作已佚。该摹本1900年**八国联军侵华**时被英国人掠走，现藏**大英博物馆**，是流失海外的中国名画之一。","pts":["顾恺之据张华《女史箴》所绘","唐摹本，规劝宫廷妇女","1900年流失，藏大英博物馆"],"mem":"一问一答：这幅画在哪儿？**大英博物馆**。怎么去的？1900年**八国联军**侵华流失。作者的另一幅名作《洛神赋图》现存摹本藏在**故宫**，二者**一在海外一在国内**。","mix":"《女史箴图》与《洛神赋图》同为顾恺之作品，现存均为摹本；《洛神赋图》取材曹植赋，《女史箴图》取材张华《女史箴》，题材不同。","mcq":[{"q":"《女史箴图》现存的唐摹本收藏于","o":["大英博物馆","北京故宫","台北故宫","波士顿美术馆"],"a":0,"w":"《女史箴图》唐摹本藏大英博物馆；《历代帝王图》藏波士顿美术馆。"}],"rel":[{"t":"顾恺之","n":"作者"},{"t":"《洛神赋图》","n":"顾恺之另一名作"},{"t":"谢赫“六法”","n":"同属早期画论线"},{"t":"阎立本与《历代帝王图》","n":"同为流失海外名画"}],"more":"“冯婕妤当熊”“班婕妤辞辇”等为画中著名段落；顾恺之称“才绝、画绝、痴绝”。","exam":[]},{"id":"a05-026","t":"阎立本与《历代帝王图》","cid":"05c","p":2,"kind":"人物","alias":["阎立本","历代帝王图","阎右相"],"one":"唐初人物画家，官至右相，作《步辇图》《历代帝王图》。","ans":"阎立本（约601–673）是**唐初画家**，官至**右相**，擅画人物与历史题材。他受命绘制**凌烟阁二十四功臣像**，另有**《步辇图》**，描绘唐太宗接见吐蕃使者禄东赞。**《历代帝王图》**绘汉昭帝至隋炀帝**十三位帝王**，现藏**美国波士顿美术馆**，人物神态各异。他的画使唐初人物画臻于成熟，对后世宫廷画影响很大。","pts":["唐初，官至右相","《步辇图》；凌烟阁功臣像","《历代帝王图》十三帝，藏波士顿"],"mem":"一句话：**阎立本，右相，画帝王**。数字锚点：十三位帝王，二十四位功臣。《步辇图》接见禄东赞（吐蕃），《历代帝王图》藏美国，两幅都是“帝”的主题。","mix":"阎立本与吴道子都是唐代人物画家，前者擅历史人物与帝王，后者擅佛道壁画；《步辇图》取材唐蕃关系，不是文成公主的画像。","mcq":[{"q":"绘有《历代帝王图》，官至右相的唐代画家是","o":["吴道子","张萱","阎立本","周昉"],"a":2,"w":"《历代帝王图》《步辇图》均为阎立本所作，他官至右相。"}],"rel":[{"t":"《步辇图》","n":"同作者名作"},{"t":"吴道子","n":"唐代人物画并举"},{"t":"唐太宗“天可汗”","n":"《步辇图》背景"},{"t":"《女史箴图》","n":"同为流失海外名画"}],"more":"作品：《步辇图》《历代帝王图》（波士顿美术馆）；绘凌烟阁二十四功臣像（643年）。","exam":[]},{"id":"a05-027","t":"吴带当风与曹衣出水","cid":"05c","p":2,"kind":"概念","alias":["吴带当风","曹衣出水","吴家样","曹家样"],"one":"吴道子衣带飘举，曹仲达衣纹紧贴，两种人物衣褶画法。","ans":"“吴带当风”与“曹衣出水”是对**两种人物衣纹画法**的概括，出自宋代郭若虚《图画见闻志》。**吴带当风**指唐代**吴道子**所画衣带飘举、如迎风飞动，线条圆转流畅，称“吴家样”。**曹衣出水**指**北齐曹仲达**画衣纹稠叠、紧贴身体，如刚从水中出来，称“曹家样”。二者代表了**中国佛道人物画**的两种衣褶风格。","pts":["吴道子：衣带飘举如迎风","曹仲达：衣纹紧贴如出水","两种佛道人物衣褶风格"],"members":[["吴带当风","唐吴道子，衣带飘举，称吴家样"],["曹衣出水","北齐曹仲达，衣纹紧贴，称曹家样"]],"mem":"**吴飘曹贴**：吴道子的衣带像风吹着飘，曹仲达的衣服像刚出水，紧紧贴着身子。时间：曹在北齐，吴在唐，先曹后吴。","mix":"吴是唐代吴道子，不是三国的吴国；曹仲达是北齐画家，与曹操、曹植无关。","mcq":[{"q":"“曹衣出水”的创始人曹仲达是哪个朝代的画家","o":["东晋","南朝梁","唐","北齐"],"a":3,"w":"曹仲达为北齐画家，擅佛像，衣纹紧贴；吴道子为唐代。"}],"rel":[{"t":"吴道子","n":"吴带当风的创始人"},{"t":"阎立本与《历代帝王图》","n":"同为唐代人物画家"},{"t":"敦煌壁画","n":"佛道人物画的实物"},{"t":"书画称号：书圣、草圣、画圣","n":"吴道子称画圣"}],"more":"出自宋代郭若虚《图画见闻志》：吴带当风，曹衣出水。","exam":[]},{"id":"a05-028","t":"顾陆张吴","cid":"05c","p":3,"kind":"合称","alias":["人物画四祖","六朝及唐四大家"],"one":"顾恺之、陆探微、张僧繇、吴道子，中国古代四位画家合称。","ans":"顾陆张吴指**魏晋南北朝至唐代的四位人物画大师**。即东晋**顾恺之**、南朝宋**陆探微**、南朝梁**张僧繇**与盛唐**吴道子**。顾恺之倡“以形写神”，张僧繇传“画龙点睛”，吴道子被尊为“画圣”。四人代表了**中国古代人物画的最高成就**。","pts":["顾恺之、陆探微、张僧繇、吴道子","魏晋六朝至盛唐的人物画代表名家","倡以形写神与疏体，吴道子尊画圣"],"mem":"“顾陆张吴四画家，晋宋梁唐一路夸”。前三位是六朝三家，加上盛唐画圣吴道子。","mix":"前三家顾恺之（东晋）、陆探微（刘宋）、张僧繇（南梁）合称“六朝三大家”，加上盛唐吴道子合称“四祖”或“顾陆张吴”。","mcq":[{"q":"下列中国古代著名画家中，不属于“顾陆张吴”四大家的是","o":["阎立本","顾恺之","陆探微","张僧繇"],"a":0,"w":"四大家为顾恺之、陆探微、张僧繇、吴道子；阎立本不在其列。"}],"rel":[{"t":"顾恺之","n":"四大家之首"},{"t":"吴道子","n":"四大家之一画圣"},{"t":"《洛神赋图》","n":"顾恺之传世代表作"},{"t":"阎立本与《历代帝王图》","n":"唐代人物画名家"}],"members":[["顾恺之","东晋“画绝、才绝、痴绝”，倡“以形写神”，作《洛神赋图》"],["陆探微","南朝宋画家，创“一笔画”连绵草法，风格“秀骨清像”"],["张僧繇","南朝梁画家，有“画龙点睛”典故，创“没骨法”与疏体"],["吴道子","盛唐画家，尊为“画圣”，风格“吴带当风”，作《送子天王图》"]],"exam":[]},{"id":"a05-029","t":"《韩熙载夜宴图》","cid":"05c","p":1,"kind":"作品","alias":["韩熙载夜宴图","夜宴图"],"one":"五代南唐顾闳中奉命所绘，分听乐、观舞、歇息、清吹、散宴五段。","ans":"《韩熙载夜宴图》是**五代南唐画家顾闳中所作的人物长卷**，绢本设色。南唐后主李煜怀疑大臣韩熙载，派顾闳中潜入韩府，**暗中观察夜宴，回来后凭记忆画成**。全卷分**听乐、观舞、歇息、清吹、散宴**五段，用屏风、床榻等将场景隔开又连成一体，人物神态各异，韩熙载神情忧郁，透露其纵情声色的避祸心理。现存**宋代摹本**，藏北京故宫博物院。它是五代人物画的杰作，也是研究南唐生活与服饰的形象史料。","pts":["五代南唐顾闳中，奉李煜命所绘","听乐、观舞、歇息、清吹、散宴五段","现存宋摹本，藏北京故宫"],"mem":"五段口诀：听、观、歇、吹、散，顺序就是一场宴会的一晚：先听乐，再看舞，歇一歇，听吹箫，散场。故事记成一句话：李煜派人“偷看”，顾闳中“偷记”，回来“默画”。","mix":"作者是顾闳中，不是顾恺之；韩熙载是画中被描绘的大臣，不是画家；下令作画的是南唐后主李煜。","mcq":[{"q":"《韩熙载夜宴图》的作者是","o":["阎立本","顾恺之","顾闳中","张择端"],"a":2,"w":"五代南唐顾闳中，易与顾恺之混。"},{"q":"下列不属于《韩熙载夜宴图》五段内容的是","o":["观舞","清吹","听乐","出游"],"a":3,"w":"五段为听乐、观舞、歇息、清吹、散宴。"}],"rel":[{"t":"李煜","n":"命顾闳中作画的南唐后主"},{"t":"《清明上河图》","n":"同为故宫藏长卷名作"},{"t":"唐代仕女画：张萱与周昉","n":"唐五代人物画"},{"t":"南唐二主","n":"南唐君主"}],"more":"韩熙载为南唐大臣，北方士人南渡。","exam":[]},{"id":"a05-030","t":"《五牛图》","cid":"05c","p":2,"kind":"作品","alias":["五牛图","韩滉五牛图"],"one":"唐韩滉所作，现存最早的纸本中国画之一，藏北京故宫。","ans":"《五牛图》是**唐代韩滉**所作的**纸本设色**画卷，绘五头姿态各异的牛，用笔粗劲，神态憨厚而富生气。韩滉（723–787）官至宰相，兼擅书画，以画田家风俗与牛羊著称。该图是**现存最早的纸本中国画之一**，历经元代赵孟頫题跋、清代乾隆收藏，现藏**北京故宫博物院**，是唐代绘画的稀世珍品，也是中国十大传世名画之一。","pts":["唐韩滉所作，五牛各异","现存最早的纸本中国画之一","藏北京故宫，十大传世名画之一"],"mem":"数字：**五头牛、一张纸**。最早的**纸本**画，记为“五牛纸本最早”。一句话区分：《五牛图》是唐代、纸本、动物画；《韩熙载夜宴图》是五代、人物画。","mix":"《五牛图》是动物画，不是仕女画；唐代仕女画家是张萱、周昉，韩滉与之不同。该图不是“现存最早的绘画”，战国《人物龙凤帛画》等更早。","mcq":[{"q":"《五牛图》的作者是","o":["韩滉","张萱","顾闳中","吴道子"],"a":0,"w":"《五牛图》为唐代韩滉作，是现存最早的纸本中国画之一。"}],"rel":[{"t":"中国十大传世名画","n":"所属合称"},{"t":"《韩熙载夜宴图》","n":"并列的唐五代名画"},{"t":"唐代仕女画：张萱与周昉","n":"同期画家对照"},{"t":"赵孟頫","n":"元代题跋者"}],"more":"韩滉（723–787），唐代官员、画家；《五牛图》藏北京故宫博物院。","exam":[]},{"id":"a05-031","t":"唐代仕女画：张萱与周昉","cid":"05c","p":3,"kind":"人物","alias":["张萱与周昉","唐代仕女画"],"one":"盛唐张萱与中晚唐周昉，唐代贵族仕女画代表画家。","ans":"张萱与周昉是**唐代仕女人物画的代表画家**。张萱为盛唐宫廷画家，代表作有**《虢国夫人游春图》**与《捣练图》；周昉活跃于中晚唐，代表作有**《簪花仕女图》**。二人画风丰腴华贵，生动表现贵族女性生活，确立了**唐代仕女画的经典审美风范**。","pts":["唐代仕女画两大代表名家","张萱画虢国夫人游春图、捣练图","周昉作簪花仕女图，人物体态丰腴"],"mem":"“盛唐张萱游春捣练，中唐周昉簪花仕女”。画中贵族女性体态丰腴。","mix":"张萱《虢国夫人游春图》《捣练图》传世均为宋摹本；周昉传世代表作为辽宁省博物馆藏《簪花仕女图》。","mcq":[{"q":"描绘盛唐杨贵妃三姐虢国夫人盛装骑马出游场景的名画《虢国夫人游春图》作者是","o":["周昉","张萱","阎立本","韩滉"],"a":1,"w":"《虢国夫人游春图》作者为盛唐宫廷画家张萱，传世为宋代摹本。"}],"rel":[{"t":"《步辇图》","n":"唐代人物画名作"},{"t":"《韩熙载夜宴图》","n":"五代人物画长卷"},{"t":"阎立本与《历代帝王图》","n":"同属唐代人物画家"}],"exam":[]},{"id":"a05-032","t":"大小李将军与青绿山水","cid":"05c","p":3,"kind":"合称","alias":["大小李将军","李思训李昭道","金碧山水"],"one":"唐代宗室画家李思训与李昭道父子，青绿山水开创者。","ans":"大小李将军指**唐代李思训与李昭道父子**。二人官居武职，开创了富丽堂皇的**金碧青绿山水**画派。李思训作《江帆楼阁图》，李昭道作《明皇幸蜀图》，以石青石绿勾金描绘山川。明代董其昌提出南北宗论，推李思训为**山水画“北宗之祖”**。","pts":["唐代李思训、李昭道父子合称","开创金碧青绿山水画派，勾金填彩","董其昌推李思训为北宗之祖"],"mem":"“大李思训小李昭道，青绿山水北宗祖”。石青石绿加泥金，金碧辉煌。","mix":"李思训是大李将军，李昭道是小李将军；董其昌南北宗论中，北宗之祖是李思训，南宗之祖是王维。","mcq":[{"q":"在明代董其昌提出的画论“南北宗论”中，被推尊为山水画“北宗之祖”的唐代画家是","o":["王维","吴道子","李思训","荆浩"],"a":2,"w":"董其昌推唐代宗室李思训为北宗之祖，推王维为南宗之祖。"}],"rel":[{"t":"董其昌与南北宗论","n":"推李思训为北宗之祖"},{"t":"王维","n":"董其昌推为南宗之祖"},{"t":"《千里江山图》","n":"宋代青绿山水巅峰"}],"members":[["李思训","大李将军，唐宗室，开创金碧青绿山水，董其昌推为北宗之祖，代表作《江帆楼阁图》"],["李昭道","小李将军，李思训之子，变父法更工细，代表作《明皇幸蜀图》"]],"exam":[]},{"id":"a05-033","t":"荆关董巨","cid":"05c","p":2,"kind":"合称","alias":["荆浩关仝董源巨然"],"one":"荆浩、关仝、董源、巨然，五代至宋初的山水画四家。","ans":"荆关董巨指**五代至宋初四位山水画家荆浩、关仝、董源、巨然**。荆浩著《笔法记》，有《匡庐图》，关仝有《关山行旅图》，二人代表**北方山水**，气势雄浑峻拔。董源有《潇湘图》，其弟子僧人巨然有《秋山问道图》，二人代表**江南山水**，风格平淡秀润。四人奠定了中国山水画**南北两派**的格局，为宋代山水画高峰开路。","pts":["荆浩、关仝、董源、巨然","荆关为北方，董巨为江南","奠定山水画南北两派"],"members":[["荆浩","北方山水，《匡庐图》，著《笔法记》"],["关仝","北方山水，《关山行旅图》"],["董源","江南山水，《潇湘图》"],["巨然","江南山水，董源弟子，《秋山问道图》"]],"mem":"口诀**“荆关董巨”**，两两成对：**荆关**居北、**董巨**在南。南派的“董源”后来被董其昌尊为南宗（文人画）的代表。","mix":"北宋山水三大家（李成、关仝、范宽）里也有关仝，注意与荆关董巨区分；董源、巨然是师徒，不是同辈。","mcq":[{"q":"“荆关董巨”中，代表江南山水的画家是","o":["荆浩与关仝","关仝与董源","荆浩与巨然","董源与巨然"],"a":3,"w":"董源、巨然（南唐）代表江南山水，荆浩、关仝代表北方山水。"}],"rel":[{"t":"北宋山水三大家","n":"承接并发展山水"},{"t":"文人画","n":"董巨对后世影响"},{"t":"董其昌与南北宗论","n":"董源被尊南宗"},{"t":"南唐二主","n":"董巨活动于南唐"}],"more":"荆浩《笔法记》提出气、韵、思、景、笔、墨“六要”。","exam":[]},{"id":"a05-034","t":"黄家富贵，徐熙野逸","cid":"05c","p":3,"kind":"概念","alias":["徐黄异体","黄家富贵徐熙野逸"],"one":"五代西蜀黄筌与南唐徐熙形成的花鸟画两大流派与美学风格。","ans":"该概念指**五代时期中国花鸟画的两大代表流派**。西蜀**黄筌**绘宫廷珍禽，工整浓丽，称“黄家富贵”；南唐**徐熙**写汀花水鸟，水墨淡彩，称“徐熙野逸”。徐熙之孙徐崇嗣开创“没骨”花鸟法。二者共同奠定了**中国古代花鸟画的两大美学传统**。","pts":["五代花鸟画两大风格流派","西蜀黄筌工丽富贵，南唐徐熙水墨野逸","徐崇嗣创没骨法，奠定花鸟传统"],"mem":"“西蜀黄筌画宫廷富贵，南唐徐熙写江湖野逸”。黄筌工笔，徐熙落墨。","mix":"黄筌是西蜀宫廷画家（工细富丽），徐熙是南唐布衣画家（野逸水墨）；徐熙之孙徐崇嗣创“没骨法”，不用墨线勾勒。","mcq":[{"q":"五代时期代表花鸟画“野逸”一派、多写江湖汀花水鸟的南唐画家是","o":["黄筌","黄居寀","赵昌","徐熙"],"a":3,"w":"五代花鸟画有“黄家富贵，徐熙野逸”之说，徐熙为南唐画家，风格清淡野逸。"}],"rel":[{"t":"《韩熙载夜宴图》","n":"五代南唐绘画名作"},{"t":"徐渭","n":"明代写意花鸟名家"},{"t":"齐白石","n":"近现代花鸟画大师"}],"exam":[]},{"id":"a05-035","t":"《千里江山图》","cid":"05d","p":1,"kind":"作品","alias":["千里江山图","王希孟"],"one":"北宋王希孟十八岁所作青绿山水长卷，藏北京故宫。","ans":"《千里江山图》是**北宋画家王希孟所作的青绿山水长卷**，绢本设色，现藏**北京故宫博物院**。王希孟在**政和三年（1113 年）十八岁时完成**此画，曾受**宋徽宗指点**。画卷用**石青、石绿**等矿物颜料，描绘连绵山峦、江河、村舍、舟桥，气势开阔，色彩明丽。它继承唐代青绿山水传统，是**青绿山水的代表作**，也是宋徽宗画院成就的体现。王希孟传世仅此一画。","pts":["北宋王希孟，青绿山水长卷","1113 年十八岁完成，受宋徽宗指点","石青石绿，北京故宫藏"],"mem":"数字记：1113 年，18 岁，一人一画。颜色记“青绿”两个字：石青、石绿。故事记：徽宗看了他的草稿，亲自指点，他画了半年完成，后来人们一提青绿山水就想到这幅。","mix":"《千里江山图》与《清明上河图》同为北宋名画，一画山水，一画市井；作者王希孟只留此一画，不要与“千里”相关的其他作品混淆；青绿山水并非王希孟首创，唐代李思训父子已有。","mcq":[{"q":"《千里江山图》的作者是","o":["张择端","董源","王希孟","黄公望"],"a":2,"w":"北宋王希孟，十八岁完成。"},{"q":"《千里江山图》属于","o":["文人山水","工笔花鸟","水墨写意","青绿山水"],"a":3,"w":"用石青石绿，是青绿山水代表作。"}],"rel":[{"t":"宋徽宗赵佶","n":"曾指点作者"},{"t":"大小李将军与青绿山水","n":"青绿山水传统"},{"t":"《清明上河图》","n":"北宋另一名作"},{"t":"宋代画院与院体画","n":"创作背景"}],"more":"完成于 1113 年（政和三年）。","exam":[]},{"id":"a05-036","t":"《富春山居图》","cid":"05d","p":1,"kind":"作品","alias":["富春山居图","剩山图","无用师卷"],"one":"元黄公望山水长卷，被烧分为《剩山图》与《无用师卷》。","ans":"《富春山居图》是**元代画家黄公望所绘的水墨山水长卷**，作于**1350 年**前后，为友人无用师所作，描绘富春江两岸秋景。明末收藏者**吴洪裕**临终想以此画殉葬，将其投入火中，被亲人抢救，画卷**烧成两段**：前段短，称**《剩山图》**，藏**浙江省博物馆**；后段长，称**《无用师卷》**，藏**台北故宫博物院**。2011 年两段在台北**合璧展出**。此画是元四家文人山水的代表，被誉为“中国十大传世名画”之一。","pts":["元黄公望，1350 年为无用师作","吴洪裕欲殉葬，烧为两段","《剩山图》浙江省博，《无用师卷》台北故宫，2011 合璧"],"mem":"一句话链条：黄公望画、无用师得、吴洪裕烧、剩山与无用师卷分两处。“剩”山：前段烧剩的一小段，在浙江；“无用师”卷：长的那段，在台北。2011 年合璧展出，是两岸文化交流的代表事件。","mix":"黄公望是元四家之首；《富春山居图》是水墨山水，不是青绿山水；前段“剩山图”很短，后段“无用师卷”较长；吴洪裕是明末收藏家，不是作者。","mcq":[{"q":"《富春山居图》残卷中，现藏浙江省博物馆的是","o":["《千里江山图》","《无用师卷》","《剩山图》","《溪山行旅图》"],"a":2,"w":"《剩山图》在浙江省博，《无用师卷》在台北故宫。"},{"q":"《富春山居图》的作者是","o":["吴镇","倪瓒","王蒙","黄公望"],"a":3,"w":"黄公望，元四家之首。"}],"rel":[{"t":"元四家","n":"作者所属"},{"t":"文人画","n":"元代文人山水"},{"t":"中国十大传世名画","n":"名作合集"},{"t":"《千里江山图》","n":"山水名作对举"}],"more":"1350 年黄公望为无用师作；2011 年两段在台北合璧展出。","exam":[]},{"id":"a05-037","t":"文人画","cid":"05d","p":1,"kind":"概念","alias":["士人画","士夫画","文人山水"],"one":"文人所作、重意趣与笔墨、诗书画印结合的绘画。","ans":"文人画是**由文人、士大夫创作的绘画**，北宋**苏轼提出“士人画”**，明代**董其昌推唐代王维为文人画之祖**。它不重形似，**重意趣、气韵和笔墨**，讲究**诗、书、画、印结合**，题材多为山水、梅兰竹菊。元代**元四家**是文人画的高峰，明代吴门四家继承，清代扬州八怪等有所发展。文人画与**宋代画院体**相对，影响了中国画的审美取向。","pts":["苏轼“士人画”，董其昌推王维为祖","重意趣笔墨，诗书画印结合","元四家为高峰，与院体画对举"],"mem":"四个关键词“士、意、墨、印”：画者是“士”人，追求“意”趣，靠“墨”笔，落“印”章。苏轼名句帮助理解它的主张：“论画以形似，见与儿童邻”，意思是只讲形似是小孩子的眼光。时间线：苏轼（北宋）提出，元四家（元）高峰，董其昌（明）追认王维为祖。","mix":"文人画与院体画相对：院体画重法度形似，文人画重意趣笔墨；王维是董其昌追认的“祖”，不是文人画概念的提出者；“文人四艺”（琴棋书画）是另一条目。","mcq":[{"q":"董其昌推崇为“文人画之祖”的是","o":["吴道子","王维","顾恺之","李思训"],"a":1,"w":"董其昌南北宗论，以王维为南宗之祖。"},{"q":"元代文人画的代表是","o":["清初四僧","元四家","明四家","扬州八怪"],"a":1,"w":"元四家把文人画推向高峰。"}],"rel":[{"t":"元四家","n":"文人画高峰"},{"t":"董其昌与南北宗论","n":"理论总结"},{"t":"宋代画院与院体画","n":"对立画风"},{"t":"苏轼","n":"提出士人画"},{"t":"王维","n":"追认的祖师"}],"more":"苏轼《书鄢陵王主簿所画折枝二首》：论画以形似，见与儿童邻。","exam":[]},{"id":"a05-038","t":"董其昌与南北宗论","cid":"05d","p":2,"kind":"概念","alias":["南北宗论","董其昌","南宗北宗","画禅室随笔"],"one":"明末董其昌借禅宗比喻山水画，南宗祖王维，北宗祖李思训。","ans":"董其昌（1555–1636）是**明末书画家**，松江华亭（今上海）人，官至礼部尚书，著有《画禅室随笔》。他借**禅宗分南北二宗**比喻山水画，提出**南北宗论**：**南宗以王维为祖**，崇尚水墨、重文人意趣；**北宗以李思训为祖**，青绿重彩，为画工之画。他**崇南贬北**，影响了明清文人画的价值取向。","pts":["明末董其昌，借禅宗比喻","南宗祖王维，北宗祖李思训","崇南贬北，推崇文人画"],"members":[["南宗","以王维为祖，水墨渲淡，重文人意趣"],["北宗","以李思训为祖，青绿重彩，画工之画"]],"mem":"**南王北李**：南宗王维、北宗李思训。董其昌用禅宗的“南顿北渐”作比，看到“宗”字就想到禅。董其昌是上海松江人，与交大所在城市挂钩。","mix":"南北宗不是地理上的南北方，是以禅宗比喻的画派划分；这一理论为董其昌与莫是龙、陈继儒等人共同提出，并非史实。","mcq":[{"q":"董其昌“南北宗论”中，被尊为南宗之祖的画家是","o":["李思训","王维","吴道子","董源"],"a":1,"w":"南宗以王维为祖，北宗以李思训为祖。"}],"rel":[{"t":"文人画","n":"南宗理论的归宿"},{"t":"王维","n":"南宗之祖"},{"t":"大小李将军与青绿山水","n":"北宗李思训一线"},{"t":"禅宗","n":"比喻的来源"}],"more":"著作：《画禅室随笔》；他是松江（今上海）人，书画均为明末大家。","exam":[]},{"id":"a05-039","t":"宋代画院与院体画","cid":"05d","p":2,"kind":"制度","alias":["翰林图画院","宣和画院","院体画","院画","画学"],"one":"宋代宫廷画院，徽宗时最盛，以诗句命题取士，画风工整细丽。","ans":"宋代设**翰林图画院**，网罗画家为宫廷服务，宋徽宗时**最为兴盛**，并设**画学**，以诗句命题考试，如“竹锁桥边卖酒家”，注重意境与观察。画院画家所作称“**院体画**”，风格**工整细丽**、重写实与法度。徽宗又主持编纂《**宣和画谱**》。南宋画院复兴，出现李唐、刘松年、马远、夏圭**南宋四家**。画院制度使宋代绘画走向精致与职业化。","pts":["宋设翰林图画院，徽宗时最盛","画学以诗句命题考试","院体画工整细丽，《宣和画谱》"],"mem":"**画院出题考诗**：徽宗以诗句命题（如“竹锁桥边卖酒家”只画酒旗不画酒家），逼画家画**意境**。《宣和画谱》得名于徽宗的“宣和”年号。","mix":"院体画是宫廷画风，与民间画、文人画并列；宋徽宗既是画院的推动者又是画家，不要混淆画院制度与个人书风“瘦金体”。","mcq":[{"q":"宋徽宗时画院考试常用的命题方式是","o":["默写前代名画","现场写生人物","临摹宫廷藏品","以诗句命题作画"],"a":3,"w":"徽宗画学以古人诗句命题，考查画家对意境的理解。"}],"rel":[{"t":"宋徽宗赵佶","n":"画院最盛的推动者"},{"t":"南宋四家","n":"南宋院体代表"},{"t":"文人画","n":"与院体对立的另一路"},{"t":"《千里江山图》","n":"徽宗画院出品"}],"more":"《宣和画谱》为徽宗宣和年间官修的绘画著录。","exam":[]},{"id":"a05-040","t":"宋徽宗赵佶","cid":"05d","p":2,"kind":"人物","alias":["宋徽宗","赵佶","徽宗皇帝"],"one":"北宋第八位皇帝，书画家，创瘦金体，靖康之变被金俘虏。","ans":"宋徽宗赵佶（1082–1135）是**北宋第八位皇帝**，在位1100–1126年，书画造诣极高。书法创**瘦金体**，代表作**《秾芳诗帖》**。绘画擅花鸟，有**《瑞鹤图》《芙蓉锦鸡图》**，作品工整写实。他大力扶植**画院**，主持编纂《宣和画谱》。**靖康之变**中被金俘虏，客死五国城，世人评价其“诸事皆能，独不能为君”。","pts":["北宋皇帝，创瘦金体","《瑞鹤图》《芙蓉锦鸡图》","扶植画院；靖康之变被俘"],"mem":"**一人四事**：瘦金体（书）、瑞鹤图（画）、画院（制度）、靖康之变（国灭）。人物转折：兴盛于艺、败亡于政，“诸事皆能，独不能为君”可记为总评。","mix":"徽宗是北宋皇帝，被俘的是**靖康年间**，他与宋钦宗一起被金掠走；南宋第一位皇帝是其子高宗赵构，不要把二者混淆。","mcq":[{"q":"下列作品中，出自宋徽宗之手的是","o":["《瑞鹤图》","《清明上河图》","《千里江山图》","《韩熙载夜宴图》"],"a":0,"w":"《瑞鹤图》为宋徽宗所作；《清明上河图》为张择端，《千里江山图》为王希孟。"}],"rel":[{"t":"瘦金体","n":"其独创书体"},{"t":"宋代画院与院体画","n":"他推动的画院"},{"t":"靖康之变","n":"被金俘虏"},{"t":"《千里江山图》","n":"画院弟子王希孟所作"}],"more":"代表作：《瑞鹤图》《芙蓉锦鸡图》（画），《秾芳诗帖》（书）。","exam":[]},{"id":"a05-041","t":"北宋山水三大家","cid":"05d","p":2,"kind":"合称","alias":["李成关仝范宽","宋初三大家"],"one":"李成、关仝、范宽，北宋山水画三位代表。","ans":"北宋山水三大家，据郭若虚《图画见闻志》，指**李成、关仝、范宽**三位画家。**李成**善画寒林平远，墨色清润；**关仝**画关陕山川，笔简气壮；**范宽**画雄伟的关中山水，代表作**《溪山行旅图》**，藏台北故宫。三人把五代以来的山水画推上**高峰**，确立了**北方山水**的雄浑风格，对南宋以后的山水画影响深远。","pts":["李成、关仝、范宽","范宽《溪山行旅图》","北方山水雄浑高峰"],"members":[["李成","寒林平远，墨色清润"],["关仝","关陕山川，笔简气壮"],["范宽","雄伟山水，《溪山行旅图》"]],"mem":"口诀：**李关范**，“李”开头，“范”收尾，中间的关仝既属荆关又属三家，是**桥梁人物**。《溪山行旅图》记作“**范宽走溪山**”，画中大山占据画面，人只是点缀。","mix":"另一说以董源替代关仝，称李成、董源、范宽；注意荆关董巨、三大家、南宋四家的数字合称不要混淆。","mcq":[{"q":"《溪山行旅图》的作者是","o":["李成","关仝","董源","范宽"],"a":3,"w":"《溪山行旅图》为范宽名作，现藏台北故宫。"}],"rel":[{"t":"荆关董巨","n":"前一代山水四家"},{"t":"南宋四家","n":"后一代山水四家"},{"t":"《千里江山图》","n":"北宋青绿山水"},{"t":"元四家","n":"山水画承接"}],"more":"《溪山行旅图》藏台北故宫博物院，为范宽传世名作。","exam":[]},{"id":"a05-042","t":"郭熙《林泉高致》与“三远”","cid":"05d","p":3,"kind":"概念","alias":["林泉高致","山水三远","高远深远平远"],"one":"北宋郭熙所著山水画论及其提出的“高远、深远、平远”空间理论。","ans":"《林泉高致》是**北宋画家郭熙的山水画论专著**，由其子郭思整理成书。书中提出山水画“**三远**”空间法则：自山下仰山巅为**高远**，自山前窥山后为**深远**，自近山望远山为**平远**。郭熙代表作为《早春图》，该书确立了中国山水画的透视体系。","pts":["北宋郭熙所著山水画论专著","提出高远、深远、平远之“三远法”","郭熙代表作为早春图，确立透视体系"],"mem":"“郭熙林泉高致，仰高窥深望平”。高远仰视、深远穿透、平远俯瞰。","mix":"高远（仰视，势突兀）、深远（透视，意重叠）、平远（俯视漫望，冲融渺渺）；宋代韩拙《山水纯全集》后来又补了“阔远、迷远、幽远”，合称“六远”。","mcq":[{"q":"北宋郭熙在画论《林泉高致》中提出的山水画“三远”是指","o":["高远、深远、平远","宏远、清远、深远","高远、辽远、平远","悠远、深远、清远"],"a":0,"w":"郭熙提出山水“三远”法：高远、深远、平远。"}],"rel":[{"t":"《千里江山图》","n":"北宋青绿山水名作"},{"t":"《富春山居图》","n":"元代水墨山水名作"},{"t":"董其昌与南北宗论","n":"古代重要画论"}],"exam":[]},{"id":"a05-043","t":"南宋四家","cid":"05d","p":2,"kind":"合称","alias":["南宋四大家","李刘马夏"],"one":"李唐、刘松年、马远、夏圭，南宋院体山水四家。","ans":"南宋四家指**南宋画院的四位山水画家李唐、刘松年、马远、夏圭**，简称“**李刘马夏**”。李唐开创南宋山水新风，有《万壑松风图》；刘松年工整秀雅；**马远**构图常取一角，称“**马一角**”；**夏圭**构图偏取半边，称“**夏半边**”，二人并称“**马夏**”。四家画风简练，留白多，以**边角之景**抒情，成为南宋院体山水的代表。","pts":["李唐、刘松年、马远、夏圭","马一角、夏半边","南宋院体山水代表"],"members":[["李唐","《万壑松风图》，开南宋山水新风"],["刘松年","工整秀雅，《四景山水图》"],["马远","构图取一角，称“马一角”"],["夏圭","构图取半边，称“夏半边”"]],"mem":"口诀**“李刘马夏”**，后两位有顺口溜：**马一角，夏半边**，数字“一”和“半”。画面：南宋偏安江南，所以画只剩半壁山水、一角山水。","mix":"南宋四家（李刘马夏）与北宋山水三大家（李成、关仝、范宽）都有“李”，注意区分李成与李唐。","mcq":[{"q":"南宋四家中，以“半边之景”著称、被称作“夏半边”的是","o":["马远","李唐","夏圭","刘松年"],"a":2,"w":"夏圭构图偏取半边；马远取一角，称马一角。"}],"rel":[{"t":"宋代画院与院体画","n":"南宋院体代表"},{"t":"北宋山水三大家","n":"前代山水三家"},{"t":"元四家","n":"后继山水四家"},{"t":"靖康之变","n":"南宋偏安背景"}],"more":"代表作：李唐《万壑松风图》，马远《踏歌图》《寒江独钓图》，夏圭《溪山清远图》。","exam":[]},{"id":"a05-044","t":"吴中四才子","cid":"05d","p":2,"kind":"合称","alias":["江南四大才子","吴中四杰"],"one":"明代苏州四位文人：唐寅、祝允明、文徵明、徐祯卿。","ans":"吴中四才子指**明代中叶苏州（吴中）的四位文人唐寅、祝允明、文徵明、徐祯卿**。唐寅字伯虎，诗书画俱佳；祝允明号枝山，擅书法；**文徵明**是吴门画派领袖；徐祯卿以诗名，后入前七子。其中**唐寅、文徵明**又与沈周、仇英合称**明四家**（吴门四家）。四人活跃于苏州，代表了明代江南文人的才情与风气。","pts":["唐寅、祝允明、文徵明、徐祯卿","明代苏州文人","唐寅文徵明同属明四家"],"members":[["唐寅","字伯虎，诗书画，明四家之一"],["祝允明","号枝山，书法家"],["文徵明","吴门画派领袖，明四家之一"],["徐祯卿","诗人，后入前七子"]],"mem":"口诀**“唐祝文徐”**。与明四家（**沈文唐仇**）交叉：唐、文两人两边都有。记：才子里多的是“祝、徐”，明四家里多的是“沈、仇”。","mix":"明四家是沈周、文徵明、唐寅、仇英，只有唐寅、文徵明重合；祝允明、徐祯卿不是明四家，沈周、仇英不是才子。","mcq":[{"q":"下列人物中，不属于“吴中四才子”的是","o":["唐寅","文徵明","祝允明","仇英"],"a":3,"w":"仇英是明四家之一，不在吴中四才子之列。"}],"rel":[{"t":"明四家（吴门四家）","n":"唐寅文徵明重合"},{"t":"前七子","n":"徐祯卿后入"},{"t":"文人画","n":"吴门画派属文人画"},{"t":"南宋四家","n":"数字合称对照"}],"more":"文徵明（1470–1559）、唐寅（1470–1523）；祝允明因右手六指自号“枝指生”。","exam":[]},{"id":"a05-045","t":"徐渭","cid":"05d","p":2,"kind":"人物","alias":["徐文长","青藤","青藤道人","天池山人"],"one":"明代大写意花鸟开创者，号青藤，作《墨葡萄图》《四声猿》。","ans":"徐渭（1521–1593），字文长，号**青藤**，**浙江山阴（绍兴）人**，明代书画家、戏曲家。他开创**大写意花鸟画**，用笔狂放，水墨淋漓，与陈淳并称“**青藤白阳**”，代表作**《墨葡萄图》**。戏曲有杂剧**《四声猿》**，所著**《南词叙录》**是第一部南戏专论。其画风影响八大山人、石涛、郑板桥与齐白石等后世画家。","pts":["明代，号青藤，大写意花鸟","《墨葡萄图》；与陈淳并称青藤白阳","《四声猿》《南词叙录》"],"mem":"**青藤白阳**：徐渭号青藤，陈淳号白阳，二人合称，是大写意的开山。一画一剧一论：**墨葡萄**（画）、**四声猿**（杂剧）、**南词叙录**（戏曲论）。","mix":"徐渭是明代人，与元代的黄公望、清代的八大山人不同时代；《四声猿》是杂剧，不是传奇；《南词叙录》论南戏，不是元杂剧。","mcq":[{"q":"《南词叙录》的作者，也是“青藤白阳”之一的是","o":["陈淳","徐渭","唐寅","沈周"],"a":1,"w":"徐渭号青藤，著《南词叙录》；陈淳号白阳。"}],"rel":[{"t":"八大山人","n":"受其画风影响"},{"t":"齐白石","n":"推崇徐渭"},{"t":"南戏与《琵琶记》","n":"《南词叙录》论南戏"},{"t":"汤显祖","n":"同为明代戏曲家"}],"more":"《墨葡萄图》题诗：半生落魄已成翁，独立书斋啸晚风。笔底明珠无处卖，闲抛闲掷野藤中。","exam":[]},{"id":"a05-046","t":"清初四王","cid":"05d","p":1,"kind":"合称","alias":["四王","清初六家","四王吴恽"],"one":"清初摹古正统派四画家：王时敏、王鉴、王翚、王原祁。","ans":"清初四王指**清代初期四位山水画家王时敏、王鉴、王翚、王原祁**，是当时画坛的**“正统派”**。他们**以摹古为宗，崇尚元四家和董其昌，强调笔墨功夫**，得到清廷推重。**王时敏**号烟客，**王原祁**是其孙，号麓台，**王翚**号石谷，主持绘制过《康熙南巡图》。加上**吴历、恽寿平**，合称**“清初六家”**。四王继承传统，影响很大，但流于**因袭守旧**，与四僧的创新形成对照。","pts":["王时敏、王鉴、王翚、王原祁","摹古正统派，宗元四家与董其昌","加吴历、恽寿平为清初六家"],"members":[["王时敏","号烟客，娄东派，王原祁之祖"],["王鉴","号湘碧"],["王翚","号石谷，虞山派，主持《康熙南巡图》"],["王原祁","号麓台，王时敏之孙"]],"mem":"口诀“时鉴翚原”（王时敏、王鉴、王翚、王原祁）。对比口诀：四王摹古，四僧创新。加两人成六：吴（吴历）、恽（恽寿平），记成“四王吴恽”，是清初六家的另一个名字。","mix":"四王都姓王，不要与“王蒙”（元四家）混；清初四王摹古，清初四僧创新，两者是对举；“元四家”“明四家”是不同朝代。","mcq":[{"q":"下列画家中，属于“清初四王”的是","o":["王冕","王维","王蒙","王原祁"],"a":3,"w":"四王：王时敏、王鉴、王翚、王原祁。"},{"q":"“清初六家”是在四王基础上加上","o":["髡残、弘仁","石涛、八大山人","沈周、文徵明","吴历、恽寿平"],"a":3,"w":"四王加吴历、恽寿平。"}],"rel":[{"t":"清初四僧","n":"创新派对举"},{"t":"元四家","n":"四王所宗"},{"t":"董其昌与南北宗论","n":"四王宗法的理论"},{"t":"扬州八怪","n":"后起的个性画派"}],"more":"王翚主持绘制《康熙南巡图》。","exam":[]},{"id":"a05-047","t":"清初四僧","cid":"05d","p":1,"kind":"合称","alias":["四僧","石涛八大髡残弘仁"],"one":"清初四位遗民画僧：八大山人、石涛、髡残、弘仁，主张创新。","ans":"清初四僧指**清代初期四位出家的画家八大山人（朱耷）、石涛（原济）、髡残（石谿）、弘仁（渐江）**，他们多为明朝遗民，借山水花鸟抒发故国之思。四僧**主张师法自然、创新笔墨**，反对一味摹古。**八大山人**是明宗室，画鱼鸟，白眼向人；**石涛**著《苦瓜和尚画语录》，提出“搜尽奇峰打草稿”；**髡残**画山水苍郁；**弘仁**属新安画派。四僧的创新精神与“四王”摹古形成对比。","pts":["八大山人、石涛、髡残、弘仁","明遗民画僧，借画抒怀","主张创新，与四王摹古对立"],"members":[["八大山人","朱耷，明宗室，画鱼鸟"],["石涛","原济，《苦瓜和尚画语录》"],["髡残","石谿，山水苍郁"],["弘仁","渐江，新安画派"]],"mem":"口诀“八石髡弘”。身份记一句：“四僧是遗民”，朱耷、石涛的先辈是明朝皇室。对比口诀：四王摹古守旧，四僧创新抒怀。石涛的名言记“搜尽奇峰打草稿”，意思是看遍山水再画。","mix":"四僧是清初画僧，与“元四家”“清初四王”不同；八大山人是朱耷的号，本名朱耷；“扬州八怪”是后来的个性画派，不是四僧。","mcq":[{"q":"“清初四僧”中，著《苦瓜和尚画语录》的是","o":["八大山人","髡残","石涛","弘仁"],"a":2,"w":"石涛，又称原济、苦瓜和尚。"},{"q":"八大山人本名","o":["原济","髡残","朱耷","渐江"],"a":2,"w":"八大山人即朱耷，明宗室。"}],"rel":[{"t":"八大山人","n":"四僧之一"},{"t":"石涛与《画语录》","n":"四僧之一，画论"},{"t":"清初四王","n":"摹古对举"},{"t":"扬州八怪","n":"后继创新画派"}],"more":"石涛：搜尽奇峰打草稿。","exam":[]},{"id":"a05-048","t":"八大山人","cid":"05d","p":2,"kind":"人物","alias":["朱耷","雪个","个山"],"one":"朱耷，明宗室后裔，清初四僧之一，画鱼鸟作白眼向天。","ans":"八大山人即**朱耷**（约1626–1705），**明朝宗室后裔**，明亡后出家为僧，后改信道教，号雪个、个山。他是**清初四僧**之一，画以**花鸟鱼虫**为主，笔墨简练，鱼鸟多作**白眼向天**，抒发亡国之痛与孤愤。其署款“八大山人”四字连缀，形似“**哭之**”或“**笑之**”，寄寓悲愤。作品有《河上花图卷》《孤禽图》等，影响了后世写意花鸟画。","pts":["朱耷，明宗室，清初四僧","鱼鸟白眼向天","署款似“哭之”“笑之”"],"mem":"画面：一条鱼、一只鸟，**白眼翻向天空**。签名“八大山人”连起来像“**哭之**”又像“**笑之**”，悲喜难分，正是亡国之痛。四僧口诀见“清初四僧”：弘仁、髡残、八大、石涛。","mix":"八大山人与石涛同属四僧，都是明朝宗室后裔，常一起出现；八大偏花鸟、简淡冷逸，石涛偏山水、纵横变化。","mcq":[{"q":"画鱼鸟多作“白眼向天”、署款似“哭之”“笑之”的画家是","o":["石涛","弘仁","髡残","八大山人"],"a":3,"w":"朱耷号八大山人，署款连写似哭之、笑之，寄寓亡国之痛。"}],"rel":[{"t":"清初四僧","n":"所属合称"},{"t":"石涛与《画语录》","n":"同属四僧，常对举"},{"t":"徐渭","n":"大写意前驱"},{"t":"齐白石","n":"推崇八大山人"}],"more":"作品：《河上花图卷》《孤禽图》《鱼鸟图》。","exam":[]},{"id":"a05-049","t":"石涛与《画语录》","cid":"05d","p":2,"kind":"人物","alias":["石涛","苦瓜和尚","原济","大涤子","画语录","苦瓜和尚画语录"],"one":"清初四僧之一，提出“一画”论，“笔墨当随时代”。","ans":"石涛（约1642–1707），原名**朱若极**，**明靖江王后裔**，明亡后出家，号苦瓜和尚、大涤子，是**清初四僧**之一，擅山水，后居扬州。他著**《画语录》**（《苦瓜和尚画语录》），提出“**一画**”论，主张**师法自然**，说“搜尽奇峰打草稿”，又倡“**笔墨当随时代**”，反对泥古。这些观点对清代**扬州八怪**及近现代中国画影响很大。","pts":["明宗室后裔，清初四僧","《画语录》提出“一画”论","搜尽奇峰打草稿，笔墨当随时代"],"mem":"三句话记：**一画**（理论核心）、**搜尽奇峰打草稿**（师造化）、**笔墨当随时代**（反泥古）。作品对应“《画语录》”，与四王的**摹古**正好相反，一个创新、一个复古。","mix":"石涛与四王同在清初，但四王摹古、石涛创新；石涛与八大同属四僧，不要把“一画”论误归八大。","mcq":[{"q":"提出“一画”论、著有《画语录》的清初画家是","o":["八大山人","石涛","王翚","髡残"],"a":1,"w":"《画语录》为石涛所著，提出“一画”论。"}],"rel":[{"t":"清初四僧","n":"所属合称"},{"t":"八大山人","n":"同属四僧"},{"t":"清初四王","n":"摹古对照"},{"t":"扬州八怪","n":"受其影响"}],"more":"名句：搜尽奇峰打草稿｜石涛题画语\n笔墨当随时代｜石涛题画跋","exam":[]},{"id":"a05-050","t":"金陵八家","cid":"05d","p":3,"kind":"合称","alias":["清初金陵八家","金陵画派"],"one":"明末清初活跃于南京地区的八位画家合称，以龚贤为首。","ans":"金陵八家指**明末清初活跃于南京的八位著名文人画家**。以**龚贤**为首，包括樊圻、高岑、邹喆、吴宏、叶欣、胡慥、谢荪。他们多具明朝遗民情怀，脱离清初“四王”摹古风气，注重实地写生。**龚贤擅用“积墨法”**，开创了苍茫沉郁的**金陵地域画风**。","pts":["明末清初活跃于南京的八位画家","以龚贤为首，樊圻高岑等八人","具遗民情怀，龚贤擅用积墨法"],"mem":"“金陵八家龚贤首，樊高邹吴叶胡谢”。南京遗民重写生，龚贤半千积墨厚。","mix":"金陵八家是明末清初画派，以龚贤为首（积墨法）；不同于现代傅抱石、钱松喦等的“新金陵画派”。","mcq":[{"q":"清初“金陵八家”中成就最高、以擅长“积墨法”著称的画家是","o":["樊圻","龚贤","高岑","王时敏"],"a":1,"w":"金陵八家以龚贤为首，其山水画多用积墨，墨气深厚沉着。"}],"rel":[{"t":"八大山人","n":"清初遗民画家代表"},{"t":"扬州八怪","n":"清代地域画家群体"},{"t":"明四家（吴门四家）","n":"明代地域画家群体"}],"members":[["龚贤","八家之首，字半千，擅用“积墨法”，墨色苍润沉厚，代表作《夏山过雨图》"],["樊圻","字会公，擅山水花卉，画风清丽秀雅，工整细腻"],["高岑","字蔚生，擅画江南山水，笔墨苍润秀拔"],["邹喆","字方鲁，擅山水古朴，兼工水墨花卉"],["吴宏","字远度，江西金溪人客居金陵，笔墨纵横放逸"],["叶欣","字荣木，取法宋元，笔致幽澹闲远"],["胡慥","字石公，擅画山水花卉，尤工枯木竹石"],["谢荪","字荪友，擅画山水花卉，用笔清谨雅致"]],"exam":[]},{"id":"a05-051","t":"郎世宁","cid":"05d","p":2,"kind":"人物","alias":["朱塞佩·伽斯底里奥内","Castiglione"],"one":"意大利耶稣会士，清康雍乾三朝宫廷画家，中西合璧。","ans":"郎世宁（1688–1766）是**意大利传教士**，**耶稣会士**，康熙五十四年（1715）来华，历**康雍乾三朝**任宫廷画家。他把西洋的**透视、明暗**技法与中国工笔画结合，创**中西合璧**画风，代表作有**《百骏图》**。他还参与设计**圆明园西洋楼**，是**中西文化交流**的重要人物。其画作被称为“海西法”，影响了清代宫廷绘画。","pts":["意大利耶稣会士，康雍乾三朝宫廷画家","西洋透视明暗与中国工笔结合","《百骏图》；参与圆明园西洋楼"],"mem":"一句话：**意大利人、画中国、三朝官**。三个关键词：**百骏图**（画）、**西洋楼**（建筑）、**三朝**（康雍乾）。与利玛窦（明末）对举：前者科学，后者艺术，均为传教士。","mix":"郎世宁是清代传教士画家，利玛窦是明末传教士，不要混淆；郎世宁传世代表作多用中国绢纸设色，但也曾绘制并向宫廷画师传授西洋油画。","mcq":[{"q":"清代宫廷画家郎世宁的国籍是","o":["法国","葡萄牙","德国","意大利"],"a":3,"w":"郎世宁（Giuseppe Castiglione）为意大利人，耶稣会传教士。"}],"rel":[{"t":"利玛窦","n":"明末传教士，对举"},{"t":"中国十大传世名画","n":"《百骏图》入选"},{"t":"清初四王","n":"同期正统画派"},{"t":"扬州八怪","n":"同期民间写意"}],"more":"作品：《百骏图》；参与设计圆明园西洋楼。","exam":[]},{"id":"a05-052","t":"中国画技法与分科：工笔、写意、白描、没骨","cid":"05d","p":2,"kind":"概念","alias":["工笔","写意","白描","没骨","青绿","浅绛"],"one":"中国画按题材分人物山水花鸟，按技法分工笔与写意。","ans":"中国画**按题材**分**人物、山水、花鸟**三大科，**按技法**分**工笔**与**写意**。工笔用细笔勾勒、层层设色，写意用简练笔墨抒写神韵。**白描**只用墨线勾勒，不设色；**没骨**不勾轮廓，直接用色或墨点染成形。山水又分**青绿、水墨、浅绛**：青绿用石青石绿，浅绛以淡赭石为主，相传由元代黄公望倡用。","pts":["题材：人物、山水、花鸟","技法：工笔与写意；白描、没骨","山水：青绿、水墨、浅绛"],"members":[["白描","只用墨线，不着色"],["没骨","不勾轮廓，直接设色"],["青绿山水","石青石绿重彩，如《千里江山图》"],["浅绛山水","淡赭石为主，元代黄公望倡"]],"mem":"**三科两法**：三科（人物、山水、花鸟）、两法（工笔、写意）。再记两个特殊词：**白描有线无色，没骨有色无线**，对应“无”的东西不同。","mix":"白描不是写意，是工笔一路的线描；没骨也有写意与工笔之分。青绿山水《千里江山图》属工笔重彩，不是水墨。","mcq":[{"q":"不勾轮廓、直接用色或墨点染成形的画法称为","o":["白描","工笔","没骨","浅绛"],"a":2,"w":"没骨法不用墨线勾勒轮廓；白描只用墨线不着色。"}],"rel":[{"t":"《千里江山图》","n":"青绿山水代表"},{"t":"文人画","n":"写意的主要脉络"},{"t":"大小李将军与青绿山水","n":"青绿山水源流"},{"t":"徐渭","n":"大写意代表"}],"more":"没骨相传始于南朝张僧繇；浅绛相传元代黄公望倡用。","exam":[]},{"id":"a05-053","t":"中国十大传世名画","cid":"05d","p":2,"kind":"合称","alias":["十大传世名画","十大名画"],"one":"中国古代绘画十件名作，通行版本不一，常列《清明上河图》等。","ans":"中国十大传世名画是对**流传至今的古代绘画名作**的合称，**无官方定本**。常见一种列法是**《洛神赋图》《步辇图》《唐宫仕女图》《五牛图》《韩熙载夜宴图》《清明上河图》《千里江山图》《富春山居图》《汉宫春晓图》《百骏图》**，时间跨度从**东晋到清代**，涵盖人物、山水、动物与仕女题材，集中体现了中国绘画的历史脉络与成就。","pts":["十件传世绘画名作，版本不一","东晋到清代，跨度长","如清明上河图、千里江山图"],"members":[["《洛神赋图》","东晋顾恺之（摹本）"],["《步辇图》","唐阎立本"],["《唐宫仕女图》","唐代仕女画，作者说法不一"],["《五牛图》","唐韩滉"],["《韩熙载夜宴图》","五代南唐顾闳中"],["《清明上河图》","北宋张择端"],["《千里江山图》","北宋王希孟"],["《富春山居图》","元黄公望"],["《汉宫春晓图》","明仇英"],["《百骏图》","清郎世宁"]],"mem":"**按朝代排队**：晋（洛神赋）、唐（步辇、仕女、五牛）、五代（夜宴）、宋（清明上河、千里江山）、元（富春山居）、明（汉宫春晓）、清（百骏）。数字：唐三、宋二，其余各一。","mix":"十大传世名画没有统一官方名单，有的版本收入《虢国夫人游春图》《簪花仕女图》《溪山行旅图》等；考试以《清明上河图》《千里江山图》《韩熙载夜宴图》《富春山居图》最稳。","mcq":[{"q":"下列作品中，作者与朝代对应正确的是","o":["《千里江山图》，北宋张择端","《五牛图》，唐韩滉","《百骏图》，明郎世宁","《步辇图》，唐吴道子"],"a":1,"w":"《五牛图》为唐韩滉；《千里江山图》为王希孟，《百骏图》为清郎世宁，《步辇图》为阎立本。"}],"rel":[{"t":"《清明上河图》","n":"北宋风俗长卷"},{"t":"《千里江山图》","n":"青绿山水"},{"t":"《韩熙载夜宴图》","n":"五代人物长卷"},{"t":"《富春山居图》","n":"元代山水，分藏两岸"},{"t":"郎世宁","n":"《百骏图》作者"}],"more":"十大传世名画无官方定本，各版本入选名单略有出入。","exam":[]},{"id":"a05-054","t":"徐悲鸿","cid":"05e","p":1,"kind":"人物","alias":["悲鸿","徐悲鸿画马"],"one":"近代画家，以西法改良中国画，擅画马，央美首任院长。","ans":"徐悲鸿（1895–1953），江苏宜兴人，**近现代画家和美术教育家**。他早年留学法国，主张**以西方写实技法改良中国画**，强调造型准确。他擅画马，代表作有**《奔马》《八骏图》**，油画与国画并重，另有**《愚公移山》《田横五百士》**等大型历史题材作品。新中国成立后任**中央美术学院首任院长**。徐悲鸿推动了中国美术的现代化，其写实主义路线影响了新中国美术教育。","pts":["近代画家，西法改良中国画","擅画马，《八骏图》《奔马》","《愚公移山》《田横五百士》，央美首任院长"],"mem":"记他的两个关键词：“马”和“西”。画马记《奔马》《八骏图》，看到“马”想徐悲鸿；西法改良记“留法、写实”。大作品记两个典故：愚公移山、田横五百士，都是“精神力量”的主题。对举人物：齐白石（写意）、林风眠（融合）。","mix":"“南张北齐”指张大千与齐白石，不包括徐悲鸿；徐悲鸿是“写实改良”，齐白石是“写意传统”；他的《田横五百士》是油画，《愚公移山》是国画，两种画种都有。","mcq":[{"q":"以画马著称、主张以西法改良中国画的画家是","o":["张大千","齐白石","徐悲鸿","吴昌硕"],"a":2,"w":"徐悲鸿，代表作《奔马》《八骏图》。"},{"q":"徐悲鸿创作的大型历史题材作品是","o":["《开国大典》","《清明上河图》","《江山如此多娇》","《田横五百士》"],"a":3,"w":"《田横五百士》是徐悲鸿油画作品。"}],"rel":[{"t":"齐白石","n":"同代，写意对举"},{"t":"张大千","n":"南张北齐"},{"t":"岭南画派","n":"同期改良画派"},{"t":"《开国大典》油画","n":"新中国美术名作"}],"more":"作品：《奔马》《八骏图》《愚公移山》《田横五百士》。","exam":[]},{"id":"a05-055","t":"南张北齐","cid":"05e","p":2,"kind":"合称","alias":["南张北齐","南张北溥"],"one":"张大千与齐白石，近现代中国画两大家，一南一北。","ans":"“南张北齐”指**近现代中国画大师张大千与齐白石**，两人一南一北，并为**20世纪中国画的代表**。**张大千**擅山水，晚年创**泼墨泼彩**，曾赴敦煌临摹壁画；**齐白石**擅花鸟虫鱼，以画虾闻名，主张“**似与不似之间**”。二人画风迥异，一个气象恢宏，一个朴拙天真，共同代表了**传统中国画在近代的高峰**。","pts":["张大千与齐白石","一南一北，20世纪代表","张擅山水泼彩，齐擅花鸟画虾"],"members":[["张大千","南，擅山水，泼墨泼彩，临摹敦煌"],["齐白石","北，擅花鸟，画虾，似与不似"]],"mem":"**南张北齐**，一对一：**张在南、齐在北**，张画山水、齐画虾；记成“张大千（大山大水）对齐白石（小虾小蛙）”。","mix":"另有“南张北溥”，指张大千与溥心畬；考试以“南张北齐”为多，不要把溥心畬、徐悲鸿混入。","mcq":[{"q":"“南张北齐”指的是","o":["张大千、齐白石","张大千、徐悲鸿","吴昌硕、齐白石","张大千、溥心畬"],"a":0,"w":"“南张北齐”为张大千与齐白石；张大千与溥心畬则称“南张北溥”。"}],"rel":[{"t":"张大千","n":"南张"},{"t":"齐白石","n":"北齐"},{"t":"徐悲鸿","n":"同时代画家"},{"t":"敦煌壁画","n":"张大千曾临摹"}],"more":"“南张北溥”指张大千与溥心畬。","exam":[]},{"id":"a05-056","t":"张大千","cid":"05e","p":2,"kind":"人物","alias":["张爰","大千居士","张正权"],"one":"四川内江人，泼墨泼彩山水，1941至1943年临摹敦煌壁画。","ans":"张大千（1899–1983），**四川内江人**，名爰，号大千居士，**近现代画家**。早年学石涛、八大山人，**1941至1943年赴敦煌莫高窟临摹壁画**，开阔了人物画与设色技法。晚年创**泼墨泼彩**山水，如《庐山图》，画风恢宏。他与**齐白石**并称“**南张北齐**”，晚年旅居海外，最后定居台北，是**20世纪最具国际影响的中国画家**之一。","pts":["四川内江人，号大千居士","1941–1943年临摹敦煌壁画","晚年泼墨泼彩，南张北齐"],"mem":"年份**1941–1943**：临摹敦煌，约两年半。关键词：**敦煌**（临摹）、**泼彩**（晚年创）、**南张**（与北齐并称）。","mix":"张大千临摹敦煌，不是发现藏经洞（藏经洞1900年由王道士发现）；他与徐悲鸿同时，但徐悲鸿以西法改良中国画、擅画马。","mcq":[{"q":"1941至1943年赴敦煌莫高窟临摹壁画的画家是","o":["齐白石","徐悲鸿","吴昌硕","张大千"],"a":3,"w":"张大千1941年起在敦煌临摹壁画近两年半。"}],"rel":[{"t":"南张北齐","n":"与齐白石并称"},{"t":"敦煌壁画","n":"临摹对象"},{"t":"敦煌藏经洞","n":"同地不同事，易混"},{"t":"石涛与《画语录》","n":"早年所学"}],"more":"名作：《庐山图》《长江万里图》（晚年泼墨泼彩）。","exam":[]},{"id":"a05-057","t":"吴昌硕","cid":"05e","p":2,"kind":"人物","alias":["吴俊卿","缶庐","苦铁","缶翁"],"one":"清末民初书画篆刻家，诗书画印四绝，西泠印社首任社长。","ans":"吴昌硕（1844–1927），**浙江安吉人**，名俊卿，号缶庐，**清末民初书画篆刻大师**，**海上画派**后期代表。他**诗书画印俱精**，被誉为“**四绝**”，擅以**石鼓文入书**、以书法笔意入画，花卉用色浓烈，气势雄健。他是**西泠印社首任社长**，晚年居上海。其画风影响了**齐白石**、潘天寿等人，是承前启后的一代宗师。","pts":["清末民初，诗书画印四绝","石鼓文入书，海上画派代表","西泠印社首任社长"],"mem":"**四绝**：诗、书、画、印，连起来是“**诗书画印**”，对应吴昌硕。“一个人、一座社、一类字”：吴昌硕、西泠印社、石鼓文。","mix":"吴昌硕居上海，但籍贯浙江安吉；西泠印社在杭州，不在上海。海派前期以赵之谦、任伯年为代表，吴昌硕是后期。","mcq":[{"q":"以石鼓文入书，并任西泠印社首任社长的是","o":["任伯年","吴昌硕","赵之谦","虚谷"],"a":1,"w":"吴昌硕擅石鼓文，为西泠印社首任社长。"}],"rel":[{"t":"海上画派","n":"所属画派"},{"t":"篆刻与西泠印社","n":"首任社长"},{"t":"大篆、小篆与石鼓文","n":"其书法根基"},{"t":"齐白石","n":"受其影响"}],"more":"“诗书画印”四绝；晚年居上海，卒于上海。","exam":[]},{"id":"a05-058","t":"海上画派","cid":"05e","p":2,"kind":"流派","alias":["海派","海派绘画","海上画派"],"one":"清末民初上海画家群，赵之谦、任伯年、虚谷、吴昌硕等。","ans":"海上画派又称**海派**，指**清末民初活跃在上海的画家群**。上海开埠后商业繁荣，书画市场兴盛，画家云集。代表人物有**赵之谦、任伯年、虚谷、吴昌硕**等。海派画风**雅俗共赏**，融合金石书法与民间色彩，题材贴近市民生活。它是近代中国画向现代转型的重要环节，与同期的**岭南画派**并为近代两大地域画派。","pts":["清末民初上海画家群","赵之谦、任伯年、虚谷、吴昌硕","雅俗共赏，金石入画"],"members":[["赵之谦","金石入画，书画篆刻皆精"],["任伯年","人物花鸟，雅俗共赏"],["虚谷","僧人画家，冷逸花鸟"],["吴昌硕","诗书画印四绝，后期代表"]],"mem":"**上海开埠，商业繁荣，卖画谋生**，所以海派要“雅俗共赏”。逻辑线：开埠→市民→画风通俗。成员口诀“**赵任虚吴**”。与广东的**岭南画派**对比：一个上海，一个广东。","mix":"海派是上海地域画派，岭南画派是广东画派；“京派与海派”则是文学上的对举，不要混淆。","mcq":[{"q":"下列画家中，属于海上画派的是","o":["任伯年","石涛","高剑父","徐渭"],"a":0,"w":"任伯年为海派代表；高剑父属岭南画派，石涛、徐渭是清初、明代画家。"}],"rel":[{"t":"吴昌硕","n":"后期代表"},{"t":"岭南画派","n":"同期地域画派"},{"t":"上海开埠","n":"形成背景"},{"t":"京派与海派","n":"文学上的京海对举"}],"more":"海派画家多以卖画为生，作品面向市民市场。","exam":[]},{"id":"a05-059","t":"岭南画派","cid":"05e","p":3,"kind":"流派","alias":["岭南派","二高一陈"],"one":"清末民初发端于广东的中国画革新流派，主张“折衷中西”。","ans":"岭南画派是**清末民初发端于广东的中国画革新流派**。创始人为**高剑父、高奇峰、陈树人**（合称“二高一陈”）。画派以“**折衷中西，融会古今**”为宗旨，吸收西方写生光影与日本画法，创撞水撞粉之法。它打破旧传统，是**近代中国画革新的重要力量**。","pts":["清末民初广东创立的画派","高剑父、高奇峰、陈树人合称二高一陈","主张折衷中西融会古今，吸收写生光影"],"mem":"“二高一陈创岭南，折衷中西融古今”。高剑父、高奇峰、陈树人开创。","mix":"岭南画派创始人是“二高一陈”（高剑父、高奇峰、陈树人）；第二代传人有关山月、黎雄才、赵少昂、杨善深。","mcq":[{"q":"近代岭南画派主张“折衷中西，融会古今”，其核心创始人“二高一陈”不包括","o":["高剑父","高奇峰","陈师曾","陈树人"],"a":2,"w":"“二高一陈”指高剑父、高奇峰、陈树人；陈师曾是北京画坛著名学者型画家。"}],"rel":[{"t":"海派文化","n":"近现代地域画派对照"},{"t":"徐悲鸿","n":"倡导西法改良国画"},{"t":"齐白石","n":"近现代画坛大师"}],"exam":[]},{"id":"a05-060","t":"《江山如此多娇》","cid":"05e","p":3,"kind":"作品","alias":["江山如此多娇国画"],"one":"1959年傅抱石、关山月为人民大会堂创作的巨幅国画，毛泽东题字。","ans":"《江山如此多娇》是**1959年傅抱石与关山月为人民大会堂合作创作的巨幅山水画**。画作主题取自**毛泽东词《沁园春·雪》**，并由**毛泽东亲笔题写画名**。作品将长城、黄河、北国雪景与江南春光融汇一体，是**新中国美术史上主题创作的标志性杰作**。","pts":["1959年傅抱石与关山月合作","取材沁园春·雪，毛泽东题写画名","陈列人民大会堂，新中国经典杰作"],"mem":"“抱石山月绘江山，润之题词雪意全”。1959年国庆十周年为人民大会堂创作。","mix":"《江山如此多娇》由傅抱石（新金陵画派）与关山月（岭南画派）合作，毛泽东题字；创作于1959年新中国成立十周年之际。","mcq":[{"q":"1959年为北京人民大会堂落成创作巨幅山水画《江山如此多娇》的两位画家是","o":["齐白石、张大千","徐悲鸿、蒋兆和","潘天寿、李可染","傅抱石、关山月"],"a":3,"w":"《江山如此多娇》由傅抱石、关山月合作，毛泽东亲笔题写画名。"}],"rel":[{"t":"《开国大典》油画","n":"新中国主题美术名作"},{"t":"徐悲鸿","n":"现代中国画大家"},{"t":"齐白石","n":"现代中国画大家"}],"exam":[]},{"id":"a05-061","t":"《开国大典》油画","cid":"05e","p":3,"kind":"作品","alias":["开国大典油画","董希文开国大典"],"one":"董希文于1953年创作的著名革命历史油画，现藏中国国家博物馆。","ans":"《开国大典》是**油画家董希文于1953年创作的革命历史油画**。画作描绘了**1949年10月1日毛泽东宣告新中国成立**的庄严时刻。画面融合西方写实技法与中国年画、敦煌壁画色彩。作品是**中国油画民族化的典范**，现藏**中国国家博物馆**。","pts":["董希文1953年创作的历史油画","描绘1949年新中国开国大典盛况","融合敦煌与年画色彩，油画民族化"],"mem":"“董希文画开国典，天安门上红旗展”。1953年绘成，藏中国国家博物馆。","mix":"《开国大典》油画由董希文创作，现藏中国国家博物馆；《江山如此多娇》国画由傅抱石、关山月合作，陈列于人民大会堂。","mcq":[{"q":"生动描绘1949年新中国成立时刻、被誉为“中国油画民族化典范”的名画《开国大典》的作者是","o":["董希文","徐悲鸿","靳尚谊","罗中立"],"a":0,"w":"《开国大典》油画由著名画家董希文于1952–1953年创作完成。"}],"rel":[{"t":"敦煌壁画","n":"吸收壁画装饰色彩"},{"t":"《江山如此多娇》","n":"新中国经典主题美术"},{"t":"徐悲鸿","n":"中国油画先驱人物"}],"exam":[]},{"id":"a05-062","t":"五音：宫商角徵羽","cid":"05f","p":1,"kind":"合称","alias":["五音","五声","五声音阶","宫商角徵羽"],"one":"中国古代五声音阶：宫、商、角、徵、羽，加变宫变徵为七声。","ans":"五音是**中国古代音乐的五个基本音级，即宫、商、角、徵（读 zhǐ）、羽**，构成**五声音阶**，大致相当于简谱的 1、2、3、5、6。在五声之外加入**变宫、变徵**，即成**七声音阶**。五音与**五行**相配：宫属土、商属金、角属木、徵属火、羽属水。它是传统乐律的基础，与**十二律**配合构成中国古代音乐理论体系，古琴曲、民歌、戏曲唱腔大量采用五声调式。“五音不全”“五音六律”等成语都出自此处。","pts":["宫、商、角、徵、羽五个音级","加变宫、变徵为七声","与五行相配，五声音阶"],"members":[["宫","相当于 do（1），属土"],["商","相当于 re（2），属金"],["角","相当于 mi（3），属木"],["徵","相当于 sol（5），属火，读 zhǐ"],["羽","相当于 la（6），属水"]],"mem":"口诀就是名称本身“宫商角徵羽”，对应简谱 1 2 3 5 6，跳过了 4 和 7，这就是五声音阶的特点。五行配对口诀“宫土商金角木，徵火羽水”。“徵”字读 zhǐ，不读 zhēng，是常考点。","mix":"五音不是五行；“五音”指音阶，“八音”指八类乐器材质（金石丝竹匏土革木），两者常被混淆；“徵”读 zhǐ，“角”读 jué。","mcq":[{"q":"下列属于中国古代“五音”的是","o":["黄钟、大吕、太簇、夹钟","宫、商、角、徵、羽","金、石、丝、竹、匏","生、旦、净、末、丑"],"a":1,"w":"五音为宫商角徵羽；金石丝竹是八音的一部分；黄钟大吕是十二律。"},{"q":"五声音阶加上变宫、变徵后成为","o":["十二平均律","八声音阶","七声音阶","六声音阶"],"a":2,"w":"五声加变宫变徵成七声。"}],"rel":[{"t":"八音","n":"乐器材质分类，易混"},{"t":"十二律与朱载堉十二平均律","n":"乐律理论搭档"},{"t":"民族乐器分类","n":"乐器与音阶应用"},{"t":"古琴","n":"典型五声调式乐器"}],"more":"五音与五行：宫土、商金、角木、徵火、羽水。\n“徵”读 zhǐ。","exam":[]},{"id":"a05-063","t":"八音","cid":"05f","p":2,"kind":"合称","alias":["八音分类","金石土革丝木匏竹"],"one":"周代按材质分乐器：金、石、土、革、丝、木、匏、竹。","ans":"八音是**中国古代按制作材料对乐器的分类**，见于《周礼·春官》，依次为**金、石、土、革、丝、木、匏、竹**。金指钟、镈，石指磬，土指埙，革指鼓，丝指琴瑟，木指柷敔，匏指笙竽，竹指箫管。它是世界上较早的乐器分类法，“八音”后来也泛指音乐。曾侯乙编钟属于金，古琴属于丝。","pts":["《周礼》按材质分类","金石土革丝木匏竹","编钟属金，古琴属丝，笙属匏"],"members":[["金","钟、镈等金属乐器"],["石","磬"],["土","埙"],["革","鼓"],["丝","琴、瑟"],["木","柷、敔"],["匏","笙、竽"],["竹","箫、管"]],"mem":"通行口诀“金石土革，丝木匏竹”，四字一断。每类取一件代表器：钟、磬、埙、鼓，琴、柷、笙、箫，连起来读“钟磬埙鼓琴柷笙箫”。","mix":"八音按乐器材质分，五音（宫商角徵羽）按音高分，别混；匏是葫芦，不是竹。","mcq":[{"q":"下列哪一项不属于“八音”的材质类别","o":["玉","竹","木","石"],"a":0,"w":"八音是金、石、土、革、丝、木、匏、竹，没有“玉”。"}],"rel":[{"t":"五音：宫商角徵羽","n":"按音高分，与八音常并提"},{"t":"曾侯乙编钟","n":"金类乐器的实物"},{"t":"古琴","n":"属丝"},{"t":"民族乐器分类","n":"后世按演奏方式分类"}],"more":"《周礼·春官·大师》：播之以八音，金、石、土、革、丝、木、匏、竹。","exam":[]},{"id":"a05-064","t":"十二律与朱载堉十二平均律","cid":"05f","p":2,"kind":"概念","alias":["十二律","六律六吕","律吕","十二平均律","新法密率","朱载堉"],"one":"古代十二标准音高；明代朱载堉在数学上解决十二平均律。","ans":"十二律是**中国古代十二个标准音高**，用十二根长短不同的律管确定，分为**六律六吕**，合称律吕，**黄钟**居首。传统用**三分损益法**依次生律，各律间音程并不完全相等。明代宗室**朱载堉**著《律学新说》，提出“新法密率”，用公比为2的十二次方根的算法把八度均分为十二等份，在数学上解决了**十二平均律**，是世界上较早的相关理论。","pts":["十二律分六律六吕，黄钟为首","三分损益法生律","朱载堉“新法密率”解决十二平均律"],"mem":"首字串联自编：“黄大太夹姑仲，蕤林夷南无应”（黄钟大吕太簇夹钟姑洗仲吕，蕤宾林钟夷则南吕无射应钟）。奇数位是律（黄钟、太簇、姑洗、蕤宾、夷则、无射），偶数位是吕。","mix":"十二律不等于十二平均律：前者各律音程不均，后者把八度均分；朱载堉是明代人，不是清代；巴赫《平均律钢琴曲集》是十二平均律的西方应用。","mcq":[{"q":"明代提出“新法密率”、在数学上解决十二平均律的学者是","o":["祖冲之","沈括","宋应星","朱载堉"],"a":3,"w":"朱载堉（明）著《律学新说》等，提出新法密率。"}],"rel":[{"t":"五音：宫商角徵羽","n":"音阶与律制相配"},{"t":"曾侯乙编钟","n":"先秦律制的实物证据"},{"t":"《吕氏春秋》","n":"载三分损益法"},{"t":"八音","n":"乐理基础并提"}],"more":"十二律：黄钟、大吕、太簇、夹钟、姑洗、仲吕、蕤宾、林钟、夷则、南吕、无射、应钟。\n阳律六（律）：黄钟、太簇、姑洗、蕤宾、夷则、无射；阴律六（吕）：大吕、夹钟、仲吕、林钟、南吕、应钟。","exam":[]},{"id":"a05-065","t":"曾侯乙编钟","cid":"05f","p":1,"kind":"作品","alias":["曾侯乙墓编钟","随州编钟","战国编钟"],"one":"1978 年湖北随州出土，战国早期，65 件，一钟双音。","ans":"曾侯乙编钟是**1978 年在湖北随州擂鼓墩曾侯乙墓出土的战国早期大型青铜编钟**，全套**65 件**，分三层悬挂，音域跨五个八度，可演奏完整的音阶。每件钟能发出**两个音（一钟双音）**，即正鼓音与侧鼓音。钟上有大量**乐律铭文**，记录了各国律名对应关系。它是**中国先秦礼乐文明的实物证据**，反映了战国早期高超的青铜铸造和音乐水平，现藏**湖北省博物馆**，是国家一级文物。","pts":["1978 年湖北随州曾侯乙墓出土","战国早期，全套 65 件，一钟双音","先秦礼乐实物，藏湖北省博物馆"],"mem":"数字三件套：1978，随州，65。再加一句“一钟双音”。画面记：三层悬挂的大编钟，像一座青铜“乐器架”，敲中间敲边缘发出不同的音。别忘了“战国早期”，不是春秋，也不是汉代。","mix":"编钟与“编磬”都是礼乐重器，编钟属“金”，编磬属“石”；曾侯乙是诸侯，不是楚王；与“八音”“十二律”一起考时，编钟是“金”类。","mcq":[{"q":"曾侯乙编钟出土于","o":["四川广汉","陕西西安","河南安阳","湖北随州"],"a":3,"w":"1978 年湖北随州擂鼓墩曾侯乙墓。"},{"q":"关于曾侯乙编钟，下列说法正确的是","o":["共 100 件","现藏故宫博物院","全套 65 件，一钟双音","春秋晚期墓葬出土"],"a":2,"w":"战国早期，65 件，一钟双音，藏湖北省博物馆。"}],"rel":[{"t":"八音","n":"编钟属金类乐器"},{"t":"十二律与朱载堉十二平均律","n":"铭文记乐律"},{"t":"周代六代乐舞","n":"礼乐制度背景"},{"t":"五音：宫商角徵羽","n":"编钟演奏的音阶"}],"more":"1978 年发现；战国早期，约公元前 433 年前后。","exam":[]},{"id":"a05-066","t":"伯牙子期与《高山流水》","cid":"05f","p":2,"kind":"作品","alias":["高山流水","伯牙","钟子期","知音","伯牙绝弦","伯牙摔琴"],"one":"伯牙与钟子期的知音典故，也是十大古曲之一的古琴曲。","ans":"“高山流水”是**知音典故**，也是**古琴名曲**。春秋时伯牙善鼓琴，**钟子期**能听出他的琴声志在登高山或流水，故事见于《列子·汤问》和《吕氏春秋·本味》。钟子期死后，伯牙认为世上再无知音，**破琴绝弦**，终身不复鼓琴。后世据此成《高山》《流水》二曲，列入**中国十大古曲**，“高山流水”也成为形容知己难遇的成语。","pts":["伯牙鼓琴，钟子期听出高山流水","子期死，伯牙破琴绝弦","古琴曲，十大古曲之一，喻知音"],"mem":"画面：伯牙弹到“志在高山”，子期说“巍巍乎若泰山”；弹到“志在流水”，说“洋洋乎若江河”；子期死后，伯牙把琴摔了。记两个人：弹的是伯牙，听的是子期。","mix":"冯梦龙“三言”中《警世通言》的《俞伯牙摔琴谢知音》由此改写；刘勰《文心雕龙》有《知音》篇，但讲的是文学批评。","mcq":[{"q":"“伯牙破琴绝弦”是因为哪位知音去世","o":["师旷","钟子期","桓伊","聂政"],"a":1,"w":"钟子期死后，伯牙认为再无知音，摔琴断弦。"}],"rel":[{"t":"古琴","n":"所用乐器"},{"t":"中国十大古曲","n":"十大古曲之首"},{"t":"“三言”名篇","n":"《警世通言》改写此故事"},{"t":"《吕氏春秋》","n":"载此典故"}],"more":"《列子·汤问》：伯牙鼓琴，志在高山，钟子期曰：善哉，峨峨兮若泰山。","exam":[]},{"id":"a05-067","t":"《十面埋伏》","cid":"05f","p":3,"kind":"作品","alias":["十面埋伏琵琶曲","淮阴平楚"],"one":"著名中国传统琵琶大套武曲，描写楚汉相争之垓下之战。","ans":"《十面埋伏》是**中国传统琵琶大套武曲的代表作**，列古代十大名曲。乐曲以**楚汉相争之垓下之战**为题材，生动表现刘邦汉军设伏重围、项羽兵败的战况。风格雄健铿锵，**与同题材文曲《霸王卸甲》互为对照**，是中国器乐艺术的高峰。","pts":["中国传统琵琶大套武曲名作","描写楚汉垓下之战与十面伏兵","与文曲霸王卸甲为同题材姐妹篇"],"mem":"“琵琶武曲十面伏，垓下汉军围霸王”。金戈铁马大套武曲，与《霸王卸甲》对照。","mix":"《十面埋伏》是琵琶武曲（侧重汉军胜利与激烈战斗）；《霸王卸甲》是琵琶文曲（侧重项羽兵败之苍凉悲壮）。","mcq":[{"q":"以楚汉垓下之战为历史背景、生动描绘激战与刘邦汉军合围的著名传统琵琶大套武曲是","o":["《阳关三叠》","《十面埋伏》","《广陵散》","《平沙落雁》"],"a":1,"w":"《十面埋伏》是传统琵琶大套武曲，表现垓下之战汉军大胜。"}],"rel":[{"t":"《阳关三叠》","n":"同属古代器乐名曲"},{"t":"《广陵散》","n":"中国传统古琴名曲"},{"t":"古琴","n":"传统民族器乐"}],"exam":[]},{"id":"a05-068","t":"《阳关三叠》","cid":"05f","p":3,"kind":"作品","alias":["阳关曲","阳关三叠琴歌"],"one":"依据王维《送元二使安西》谱写的中国古代著名琴歌、古琴曲。","ans":"《阳关三叠》是**中国古代著名的琴歌与古琴曲**。作品根据**唐代王维著名送别诗《送元二使安西》**谱写而成。因在演唱时将原诗后两句**反复叠唱三次**，故名“三叠”。乐调深沉苍郁、哀婉缠绵，是**中国古代送别音乐的经典范本**。","pts":["中国古代著名古琴曲与琴歌","据王维《送元二使安西》谱成","反复叠唱三遍，抒发惜别之情"],"mem":"“王维送客西出关，阳关三叠唱三遍”。古琴名曲兼琴歌，离别依依。","mix":"《阳关三叠》是古琴曲（亦为琴歌），取材王维《送元二使安西》；不是琵琶曲，也非李白诗所谱。","mcq":[{"q":"中国古代著名古琴曲《阳关三叠》的歌词取材于哪位诗人的送别名篇","o":["李白","高适","王维","岑参"],"a":2,"w":"《阳关三叠》依据唐代诗人王维的《送元二使安西》（又称《渭城曲》）谱曲而成。"}],"rel":[{"t":"王维","n":"曲谱歌词作者"},{"t":"古琴","n":"乐曲所属演奏乐器"},{"t":"《广陵散》","n":"中国古代著名琴曲"}],"exam":[]},{"id":"a05-069","t":"民族乐器分类","cid":"05f","p":2,"kind":"常识","alias":["民族乐器","吹拉弹打","民乐四大类"],"one":"吹管、拉弦、弹拨、打击四大类，琵琶、二胡等由外来传入。","ans":"中国民族乐器按演奏方式分为**吹管、拉弦、弹拨、打击**四大类。吹管有笛、箫、笙、唢呐；拉弦有二胡、京胡、马头琴；弹拨有古琴、古筝、琵琶、扬琴、三弦；打击有鼓、锣、钹。其中**琵琶、二胡等由西域或北方民族传入**后经本土化而成，二胡的前身是唐宋的奚琴、嵇琴。这套分类也是**民族管弦乐队的四大声部**。","pts":["吹管、拉弦、弹拨、打击四类","各类代表乐器","琵琶、二胡源自西域或北方民族"],"mem":"口诀“吹拉弹打”：吹（笛箫笙唢呐）、拉（二胡京胡马头琴）、弹（琴筝琵琶）、打（鼓锣钹）。乐队里这四个声部缺一不可。","mix":"古琴、古筝是弹拨而不是拉弦；扬琴用琴竹击弦，教学上通常归入弹拨类；马头琴是蒙古族拉弦乐器。","mcq":[{"q":"下列乐器中，属于拉弦乐器的是","o":["古筝","琵琶","马头琴","笙"],"a":2,"w":"马头琴是蒙古族拉弦乐器；古筝、琵琶属弹拨，笙属吹管。"}],"rel":[{"t":"古琴","n":"弹拨乐器代表"},{"t":"八音","n":"古代按材质分类"},{"t":"《二泉映月》","n":"二胡名曲"},{"t":"刘天华","n":"二胡改革者"}],"more":"二胡前身：唐代奚琴，宋代嵇琴。琵琶（曲项）经西域传入。","exam":[]},{"id":"a05-070","t":"刘天华","cid":"05f","p":3,"kind":"人物","alias":["刘天华二胡","国乐大师刘天华"],"one":"近代民族音乐家、二胡演奏家，现代民族乐器改革先驱。","ans":"刘天华是**近代民族音乐家、二胡演奏家与教育家**。他力主“**改进国乐**”，将二胡由伴奏乐器提升为独奏乐器，引西润中规范把位与弓法。代表作有**《病中吟》《良宵》《空山鸟语》《光明行》**等十大名曲。他是**中国现代二胡学派的开山奠基人**。","pts":["近代民族音乐家与二胡大师","倡导改进国乐，将二胡升为独奏乐器","作病中吟、良宵、空山鸟语等名曲"],"mem":"“天华改进国乐，二胡病中良宵”。病中吟、良宵、空山鸟语、光明行。","mix":"刘天华创制专业二胡曲（《良宵》《光明行》等），是学院派先驱；民间艺人阿炳代表作是《二泉映月》；刘半农为其兄。","mcq":[{"q":"致力于“改进国乐”，创作了《病中吟》《良宵》《光明行》等二胡名曲的近代音乐家是","o":["阿炳","华彦钧","萧友梅","刘天华"],"a":3,"w":"刘天华是中国现代二胡音乐的奠基人，作有十大二胡名曲。"}],"rel":[{"t":"《二泉映月》","n":"近现代二胡名作"},{"t":"学堂乐歌与李叔同《送别》","n":"近代音乐演进历程"},{"t":"萧友梅与国立音专","n":"近代音乐教育先驱"}],"exam":[]},{"id":"a05-071","t":"学堂乐歌与李叔同《送别》","cid":"05f","p":2,"kind":"概念","alias":["学堂乐歌","学校歌曲","送别","李叔同","弘一法师","沈心工"],"one":"20世纪初新式学堂的唱歌课歌曲，沈心工、李叔同为代表。","ans":"学堂乐歌是**20世纪初新式学堂“唱歌”课所用的歌曲**，多采用外国或日本曲调配上新词，宣传爱国、尚武与新知，是**中国近代新音乐的起点**。代表人物有**沈心工、李叔同**，沈心工作《男儿第一志气高》，李叔同作《春游》《送别》。《送别》曲调源自美国奥德威的《梦见家和母亲》，经日本犬童球溪填词传入，李叔同再配上“长亭外，古道边”的歌词。","pts":["清末民初学堂唱歌课歌曲，中国近代新音乐起点","沈心工、李叔同为代表","《送别》曲源美国奥德威，经日本传入"],"mem":"因果线：废科举、办新学堂，学堂开唱歌课，所以有“学堂乐歌”。《送别》三步传入：美国曲，日本词，李叔同填中文词。","mix":"《送别》的词作者是李叔同，曲不是他所作；李叔同后来出家为弘一法师；萧友梅是留学归来的专业音乐教育家，与学堂乐歌的普及性质不同。","mcq":[{"q":"歌曲《送别》（“长亭外，古道边”）的填词者是","o":["李叔同","沈心工","萧友梅","聂耳"],"a":0,"w":"李叔同填词，曲调源自美国奥德威，经日本传入。"}],"rel":[{"t":"萧友梅与国立音专","n":"近代专业音乐教育"},{"t":"春柳社与中国话剧的开端","n":"李叔同参与创办"},{"t":"聂耳","n":"后一代新音乐作曲家"},{"t":"《义勇军进行曲》","n":"救亡歌曲的代表"}],"more":"李叔同（1880–1942），后出家为弘一法师。\n歌词：长亭外，古道边，芳草碧连天。｜《送别》","exam":[]},{"id":"a05-072","t":"聂耳","cid":"05f","p":2,"kind":"人物","alias":["聂守信","人民音乐家聂耳"],"one":"云南籍作曲家，《义勇军进行曲》曲作者，23岁溺亡日本。","ans":"聂耳（1912–1935），**云南玉溪人，中国现代作曲家**，原名聂守信，被称为“人民音乐家”。他参加左翼文艺运动，为电影《风云儿女》谱写主题曲**《义勇军进行曲》**（田汉词），另有《毕业歌》《卖报歌》《大路歌》等。1935年他赴日本，在藤泽海滨游泳时溺水去世，年仅23岁。《义勇军进行曲》**1949年定为代国歌，1982年正式定为国歌**，2004年写入宪法。","pts":["云南人，作曲家，1912–1935","《义勇军进行曲》《毕业歌》《卖报歌》","1935年日本溺亡；歌曲后成国歌"],"mem":"配对记：聂耳对《义勇军进行曲》（国歌），冼星海对《黄河大合唱》，两人合称新音乐“双星”。聂耳享年23，1912–1935。","mix":"《黄河大合唱》是冼星海作曲、光未然作词（1939年），不是聂耳所作；《义勇军进行曲》词作者是田汉。","mcq":[{"q":"《义勇军进行曲》的曲作者是","o":["冼星海","刘天华","马可","聂耳"],"a":3,"w":"田汉作词、聂耳作曲，为电影《风云儿女》主题曲。"}],"rel":[{"t":"《义勇军进行曲》","n":"代表作，后成国歌"},{"t":"冼星海与光未然","n":"同为救亡音乐代表"},{"t":"《黄河大合唱》","n":"冼星海的代表作"},{"t":"田汉","n":"《义勇军进行曲》词作者"}],"more":"作品：《义勇军进行曲》《毕业歌》《卖报歌》《大路歌》《开路先锋曲》。","exam":[]},{"id":"a05-073","t":"萧友梅与国立音专","cid":"05f","p":3,"kind":"人物","alias":["萧友梅","国立音乐专科学校","国立音专"],"one":"萧友梅，近代音乐教育家，创办国立音专（今上海音乐学院）。","ans":"萧友梅是**中国近代专业音乐教育的奠基人**。1927年他在蔡元培支持下创办**国立音乐院**（后改称**国立音专**，今上海音乐学院前身）并任校长。他建立起专业音乐教育体制，培养出贺绿汀、冼星海等大家，**开启了中国现代音乐高等教育先河**。","pts":["中国近代专业音乐教育奠基人","1927年在上海创办国立音专","培养冼星海、贺绿汀等音乐大家"],"mem":"“萧友梅创国立音专，上音前身育英才”。蔡元培支持，1927年在上海创立。","mix":"国立音专是中国第一所独立的高等专业音乐学府（上海音乐学院前身），由萧友梅创办并主持校务；中央音乐学院于1949年在天津成立（后迁北京）。","mcq":[{"q":"1927年在蔡元培支持下于上海创办中国第一所独立高等音乐学府“国立音乐院”（后称国立音专）的音乐教育家是","o":["萧友梅","贺绿汀","黄自","马思聪"],"a":0,"w":"萧友梅是中国现代专业音乐教育的开拓者，创办国立音乐院并任校长。"}],"rel":[{"t":"蔡元培","n":"支持创办国立音乐院"},{"t":"冼星海与光未然","n":"国立音专杰出学子"},{"t":"贺绿汀《牧童短笛》","n":"国立音专杰出学子"}],"exam":[]},{"id":"a05-074","t":"贺绿汀《牧童短笛》","cid":"05f","p":3,"kind":"作品","alias":["牧童短笛","贺绿汀牧童短笛"],"one":"贺绿汀创作于1934年的中国风格钢琴曲，中国钢琴音乐的里程碑。","ans":"《牧童短笛》是**作曲家贺绿汀于1934年创作的钢琴独奏名作**。该作在齐尔品举办的“**中国风格钢琴曲比赛**”中荣获**一等奖**。乐曲将西方复调技法与江南五声调式结合，充满水乡田园诗意，是**中国现代钢琴音乐民族化的奠基之作**。","pts":["贺绿汀1934年创作的钢琴名曲","获齐尔品中国风格钢琴曲比赛一等奖","复调技法结合五声调式，田园诗意"],"mem":"“贺绿汀吹牧童笛，齐尔品评一等奖”。1934年名作，中国钢琴民族化里程碑。","mix":"《牧童短笛》是钢琴独奏曲，并非竹笛或管乐曲；获齐尔品1934年中国风格钢琴曲比赛头奖。","mcq":[{"q":"1934年在俄国作曲家齐尔品举办的“中国风格钢琴曲比赛”中荣获一等奖的钢琴独奏名作是","o":["《夕阳箫鼓》","《牧童短笛》","《花鼓》","《平湖秋月》"],"a":1,"w":"贺绿汀创作的《牧童短笛》荣获该比赛一等奖，名扬中外。"}],"rel":[{"t":"萧友梅与国立音专","n":"贺绿汀母校与师承"},{"t":"冼星海与光未然","n":"同代杰出音乐家"},{"t":"《梁祝》","n":"中国器乐民族化经典"}],"exam":[]},{"id":"a05-075","t":"歌剧《白毛女》","cid":"05f","p":2,"kind":"作品","alias":["白毛女","白毛仙姑","新歌剧白毛女","《白毛女》"],"one":"1945年延安鲁艺集体创作，被视为中国第一部新歌剧。","ans":"歌剧《白毛女》是**1945年延安鲁迅艺术学院集体创作的新歌剧**，贺敬之、丁毅执笔，马可、张鲁、瞿维等作曲。故事取材于晋察冀边区流传的“白毛仙姑”传说，写佃农杨白劳之女喜儿被地主黄世仁迫害，逃入深山，头发变白，后在八路军帮助下获救。全剧吸收民歌与戏曲音调，主题是“旧社会把人变成鬼，新社会把鬼变成人”，被视为**中国新歌剧的里程碑**，后改编为电影和芭蕾舞剧。","pts":["1945年延安鲁艺集体创作，贺敬之、丁毅执笔","喜儿、杨白劳、黄世仁，白毛仙姑传说","中国新歌剧的里程碑"],"mem":"人物串成句：杨白劳欠债被逼死，喜儿逃进山变白毛，黄世仁是恶霸，大春带八路军来解放。口诀“延安1945，喜儿变白毛”。","mix":"歌剧《白毛女》（1945）与八个样板戏之一的芭蕾舞剧《白毛女》（1965年上海舞蹈学校首演）是两个作品；“新歌剧”指借鉴民间音乐的新型民族歌剧，有别于西洋歌剧。","mcq":[{"q":"歌剧《白毛女》诞生于","o":["上海","延安","重庆","西安"],"a":1,"w":"1945年由延安鲁迅艺术学院集体创作。"}],"rel":[{"t":"八个样板戏","n":"芭蕾舞剧《白毛女》入选"},{"t":"《梁祝》","n":"同为民族化音乐创作"},{"t":"《黄河大合唱》","n":"延安时期音乐名作"},{"t":"《义勇军进行曲》","n":"红色音乐并提"}],"more":"1950年改编为同名电影。","exam":[]},{"id":"a05-076","t":"《茉莉花》","cid":"05f","p":2,"kind":"作品","alias":["茉莉花","鲜花调","江苏民歌茉莉花"],"one":"江苏民歌，普契尼歌剧《图兰朵》引用其旋律。","ans":"《茉莉花》是**江苏民歌**，流行于南京、扬州、六合一带，源自明清时期的小调《鲜花调》，旋律婉转柔美，属**小调**类民歌。它是**较早传到海外的中国民歌之一**，意大利作曲家**普契尼**在歌剧**《图兰朵》**（1926年首演）中引用了它的旋律，使这首民歌在西方广为人知，成为**中国民歌外传的典型**。","pts":["江苏民歌，源于《鲜花调》，小调","较早传到海外的中国民歌","普契尼《图兰朵》引用其旋律"],"mem":"画面：《图兰朵》的公主出场，背景响起《茉莉花》。小调=城镇曲调，《茉莉花》是小调代表，江南的“花”。","mix":"《茉莉花》是江苏民歌，《康定情歌》是四川民歌，《在那遥远的地方》是青海民歌，别混；《图兰朵》是意大利歌剧，不是中国戏曲。","mcq":[{"q":"意大利歌剧《图兰朵》引用了下列哪首中国民歌的旋律","o":["《康定情歌》","《在那遥远的地方》","《茉莉花》","《东方红》"],"a":2,"w":"普契尼在《图兰朵》中引用了江苏民歌《茉莉花》。"}],"rel":[{"t":"普契尼《图兰朵》","n":"引用其旋律"},{"t":"民歌体裁：号子、山歌、小调；信天游与花儿","n":"属小调类"},{"t":"《二泉映月》","n":"同属民间音乐"}],"more":"《图兰朵》为普契尼遗作，1926年在米兰斯卡拉歌剧院首演。","exam":[]},{"id":"a05-077","t":"民歌体裁：号子、山歌、小调；信天游与花儿","cid":"05f","p":2,"kind":"概念","alias":["号子","山歌","小调","信天游","花儿","民歌三大类"],"one":"民歌分号子、山歌、小调三类；信天游在陕北，花儿在西北。","ans":"中国民歌按风格和用途主要分为**号子、山歌、小调**三大类。号子是劳动时配合动作的歌，如川江号子；山歌产生在田野山林，高亢自由，其中**信天游**流行于陕北，**花儿**流行于甘肃、青海、宁夏，2009年列入**人类非物质文化遗产代表作名录**；小调多流行于城镇，曲调细腻，如《茉莉花》。陕北民歌《骑白马》的曲调后被填词为《东方红》。","pts":["号子、山歌、小调三类","信天游在陕北，花儿在甘青宁","花儿2009年入选人类非遗"],"mem":"三类口诀：号子在劳动，山歌在山野，小调在城里。地域记：信天游=陕北，花儿=甘肃青海宁夏西北，《茉莉花》=江苏小调。花儿与粤剧同在2009年入选非遗。","mix":"信天游与花儿都属山歌一类，只是地域不同；内蒙古、晋北还有爬山调；信天游本身没有入选联合国非遗，入选的是花儿。","mcq":[{"q":"2009年列入人类非物质文化遗产代表作名录的西北民歌是","o":["花儿","信天游","茉莉花","川江号子"],"a":0,"w":"花儿流行于甘肃、青海、宁夏等地，2009年入选。"}],"rel":[{"t":"《茉莉花》","n":"小调代表"},{"t":"《东方红》","n":"曲调源自陕北民歌"},{"t":"少数民族音乐非遗：木卡姆、长调、呼麦、侗族大歌","n":"同属音乐类非遗"},{"t":"人类非遗代表作中国项目","n":"花儿入选"}],"more":"《东方红》歌词由陕北农民李有源据民歌《骑白马》改写。","exam":[]},{"id":"a05-078","t":"少数民族音乐非遗：木卡姆、长调、呼麦、侗族大歌","cid":"05f","p":3,"kind":"常识","alias":["少数民族音乐非遗","木卡姆与侗族大歌","长调呼麦"],"one":"列入联合国教科文组织人类非物质文化遗产的四项中国少数民族音乐瑰宝。","ans":"该常识指**入选联合国人类非遗名录的四项中国少数民族音乐**。包括2005年列入的**新疆维吾尔木卡姆**与**蒙古族长调**，2009年列入的**蒙古族呼麦**与贵州**侗族大歌**。它们风格迥异，展现了**中华民族音乐文化的多元与创造力**。","pts":["入选人类非遗的四项少数民族音乐","木卡姆与蒙古族长调2005年入选","呼麦与侗族大歌2009年入选"],"mem":"“维吾木卡姆，蒙家长调呼，侗族无伴奏，非遗四明珠”。2005与2009两批入选。","mix":"蒙古族长调是2005年中蒙联合申报；侗族大歌是无指挥、无伴奏的多声部合唱；呼麦是喉音双声艺术。","mcq":[{"q":"以“无伴奏、无指挥、多声部”为显著特征，于2009年列入联合国人类非遗名录的少数民族音乐是","o":["新疆维吾尔木卡姆","蒙古族长调民歌","侗族大歌","蒙古族呼麦"],"a":2,"w":"贵州黎平侗族大歌以无伴奏、无指挥、多声部合唱闻名，2009年列入人类非遗。"}],"rel":[{"t":"人类非遗代表作中国项目","n":"非遗大项归属"},{"t":"非物质文化遗产","n":"文化遗产核心概念"},{"t":"古琴","n":"2003年入选人类非遗"}],"exam":[]},{"id":"a05-079","t":"周代六代乐舞","cid":"05g","p":3,"kind":"合称","alias":["六代乐舞","周代六舞","六乐"],"one":"周代礼乐制度中用于国家祭祀的六部古代大型乐舞总称。","ans":"周代六代乐舞指**西周礼乐最高规格的六部古代乐舞**。包括《云门》《大咸》《大韶》《大夏》《大濩》《大武》，分属黄帝至周武王。前四部为**文舞表德**，后两部为**武舞颂功**。孔子闻《韶》称三月不知肉味，是**中国礼乐文明的核心代表**。","pts":["周代礼乐制度最高规格六部乐舞","黄帝云门尧大咸舜大韶禹大夏汤大濩周大武","前四为文舞后二为武舞，孔子叹韶乐"],"mem":"“云咸韶夏濩武，黄尧舜禹汤周”。前四文舞颂功德，后二武舞表征伐。","mix":"六代乐舞中文舞四部（云门、大咸、大韶、大夏），武舞两部（大濩、大武）；孔子称赞舜的《韶》乐“尽美矣，又尽善矣”，武王《大武》“尽美矣，未尽善也”。","mcq":[{"q":"周代“六代乐舞”中，相传代表夏禹时代功德、祭祀山川的乐舞是","o":["《大咸》","《大韶》","《大濩》","《大夏》"],"a":3,"w":"《大夏》歌颂大禹治水功绩；《大咸》归尧，《大韶》归舜，《大濩》归汤。"}],"rel":[{"t":"孔子","n":"孔子闻韶三月不知肉味"},{"t":"曾侯乙编钟","n":"周代礼乐乐器实证"},{"t":"《秦王破阵乐》","n":"后世宫廷乐舞演进"}],"members":[["《云门》","黄帝时期乐舞，又称《云门大卷》，祭祀天神，属文舞"],["《大咸》","帝尧时期乐舞，又称《大章》，祭祀地祇，属文舞"],["《大韶》","帝舜时期乐舞，又称《韶乐》，祭祀四望，孔子赞“尽美矣又尽善矣”"],["《大夏》","夏禹时期乐舞，祭祀山川，颂大禹治水功绩，属文舞"],["《大濩》","商汤时期乐舞，祭祀先妣，颂商汤伐桀功绩，属武舞"],["《大武》","周武王时期乐舞，祭祀先祖，颂武王伐纣功绩，属武舞"]],"exam":[]},{"id":"a05-080","t":"梨园","cid":"05g","p":2,"kind":"制度","alias":["梨园弟子","梨园行","梨园祖师"],"one":"唐玄宗教习乐舞之处，后世称戏曲界为梨园。","ans":"梨园原是**唐代长安禁苑中的梨树园圃**，**唐玄宗**在此挑选乐工和宫女，亲自教习法曲，称“皇帝梨园弟子”，事见《新唐书·礼乐志》。它与管理俗乐的教坊并行，是宫廷音乐舞蹈的培训机构。后世因此把**戏曲行业称为梨园，演员称梨园弟子**，戏班奉**唐玄宗为梨园祖师**。白居易《长恨歌》有“梨园弟子白发新”之句。","pts":["唐玄宗设于长安，教习法曲","“皇帝梨园弟子”","后世称戏曲界为梨园，奉玄宗为祖师"],"mem":"逻辑线：玄宗在梨园教乐舞，学生叫梨园弟子，后来戏班接过这个名号，所以戏曲界叫梨园，祖师是唐玄宗。","mix":"戏班祖师另有“老郎神”之说，常被附会为唐明皇；教坊管俗乐，梨园教法曲，二者不同。","mcq":[{"q":"戏曲界奉为“梨园祖师”的帝王是","o":["唐太宗","唐玄宗","宋徽宗","清乾隆"],"a":1,"w":"唐玄宗设梨园教习乐舞，被戏班尊为祖师。"}],"rel":[{"t":"《霓裳羽衣舞》","n":"玄宗时宫廷乐舞"},{"t":"昆曲","n":"后世梨园代表剧种"},{"t":"白居易《长恨歌》《琵琶行》","n":"“梨园弟子白发新”"},{"t":"京剧的形成","n":"梨园行的主流剧种"}],"more":"梨园弟子白发新，椒房阿监青娥老。｜白居易《长恨歌》","exam":[]},{"id":"a05-081","t":"《霓裳羽衣舞》","cid":"05g","p":2,"kind":"作品","alias":["霓裳羽衣曲","霓裳羽衣","霓裳舞"],"one":"唐玄宗时宫廷乐舞，杨贵妃善舞，唐代乐舞代表。","ans":"《霓裳羽衣舞》是**唐玄宗时期的宫廷乐舞**，属法曲歌舞，舞者身着羽衣霓裳，模仿仙女，意境飘逸。相传玄宗据西凉节度使杨敬述所献《婆罗门曲》润色而成，**杨贵妃**善跳此舞。白居易《长恨歌》有“惊破霓裳羽衣曲”，另作《霓裳羽衣歌》描写其演出。该舞后来失传，南唐**李煜与大周后**曾据残谱重订，是唐代乐舞的代表。","pts":["唐玄宗时宫廷乐舞，仙女意境","杨贵妃善舞，见《长恨歌》","南唐李煜与大周后重订残谱"],"mem":"画面：杨贵妃身披羽衣在宫中起舞，安史之乱的战鼓一响，舞曲被“惊破”。关键词线：玄宗，贵妃，长恨歌，李煜重订。","mix":"相传另有玄宗梦游月宫得曲之说；《秦王破阵乐》是唐太宗时的武舞，《霓裳羽衣舞》是玄宗时的文舞，别混。","mcq":[{"q":"“渔阳鼙鼓动地来，惊破霓裳羽衣曲”出自","o":["《琵琶行》","《秦中吟》","《长恨歌》","《卖炭翁》"],"a":2,"w":"此句出自白居易《长恨歌》。"}],"rel":[{"t":"《秦王破阵乐》","n":"唐太宗时武舞对举"},{"t":"梨园","n":"玄宗教习乐舞"},{"t":"白居易《长恨歌》《琵琶行》","n":"诗中写及此曲"},{"t":"李煜","n":"与大周后重订残谱"}],"more":"白居易另有《霓裳羽衣歌》，写此舞演出。","exam":[]},{"id":"a05-082","t":"《秦王破阵乐》","cid":"05g","p":3,"kind":"作品","alias":["秦王破阵舞","神功破阵乐"],"one":"唐太宗时期创作的唐代大型宫廷歌舞、武舞代表作。","ans":"《秦王破阵乐》是**唐代大型宫廷乐舞与健舞代表作**。原为唐将士歌颂**唐太宗李世民**战功之作，李世民即位后亲制舞图，百人披甲执戟而舞。舞姿雄健，生动展现大唐盛世军威，后传入日本。高僧玄奘在《大唐西域记》中记载**戒日王曾问及此曲**。","pts":["唐代著名宫廷武舞与健舞","唐太宗亲制舞图，展现开国军威","传入日本，戒日王曾向玄奘询问"],"mem":"“太宗破阵亲制图，戒日王问玄奘师”。大唐盛世宫廷武舞，百人披甲执戟。","mix":"《秦王破阵乐》是宫廷武舞（健舞），颂扬李世民军功；《霓裳羽衣舞》是宫廷软舞，唐玄宗创制，偏重仙境浪漫风格。","mcq":[{"q":"玄奘在《大唐西域记》中记载，印度戒日王曾向其热情询问并赞叹的唐代乐舞是","o":["《秦王破阵乐》","《霓裳羽衣舞》","《胡旋舞》","《剑器浑脱》"],"a":0,"w":"《秦王破阵乐》声威远播西域与天竺，印度戒日王曾向玄奘询问此曲。"}],"rel":[{"t":"玄奘","n":"大唐西域记记录戒日王问乐"},{"t":"《霓裳羽衣舞》","n":"唐代宫廷软舞代表"},{"t":"周代六代乐舞","n":"古代国家大型乐舞源头"}],"exam":[]},{"id":"a05-083","t":"唐代健舞与软舞：胡旋、胡腾、剑器","cid":"05g","p":3,"kind":"概念","alias":["唐代健舞与软舞","健舞与软舞","胡旋舞"],"one":"唐代乐舞的两大类别，以胡旋、胡腾、剑器为健舞代表。","ans":"健舞与软舞是**唐代乐舞的两大类别**。健舞刚劲奔放，软舞舒缓优美。健舞代表有西域康国传入的**胡旋舞**、石国**胡腾舞**及公孙大娘**剑器舞**。杜甫作诗赞剑器舞，**张旭观剑舞而草书大进**。这些舞蹈生动体现了**盛唐丝绸之路多元文化的交融盛况**。","pts":["唐代乐舞分为健舞与软舞两大类","胡旋、胡腾、剑器为健舞代表","杜甫作诗赞剑器，张旭观舞悟草书"],"mem":"“康国胡旋石国腾，公孙剑器动京城”。张旭观公孙舞剑，悟得狂草神韵。","mix":"胡旋舞来自西域康国（以旋转疾速著称，杨贵妃、安禄山善跳）；胡腾舞来自石国（男子跳跃健步）；剑器舞属于健舞而非剑术。","mcq":[{"q":"唐代书法家张旭观赏其舞剑从而“草书大进”的民间著名舞蹈艺人是","o":["谢阿蛮","公孙大娘","戚夫人","梅妃"],"a":1,"w":"杜甫《观公孙大娘弟子舞剑器行》序言记载，张旭见公孙大娘舞剑器而草书大进。"}],"rel":[{"t":"杜甫","n":"作诗赞公孙大娘剑器舞"},{"t":"张旭、怀素","n":"张旭观剑舞悟狂草"},{"t":"《霓裳羽衣舞》","n":"唐代软舞代表作"}],"exam":[]},{"id":"a05-084","t":"汉代百戏","cid":"05g","p":3,"kind":"概念","alias":["汉代散乐百戏","百戏","散乐"],"one":"汉代杂技、角抵、幻术、歌舞等民间演艺表演的总称。","ans":"汉代百戏是**汉代对杂技、角抵、魔术幻术与歌舞演艺的总称**，又称“散乐”。**汉武帝在平乐观大设“曼衍鱼龙”**接待西域使臣，推动百戏进入全盛期。节目包括顶竿、走索、吐火等杂耍绝技。它是**中国古代杂技艺术与戏曲表演的重要源头**。","pts":["汉代杂技、角抵、幻术、歌舞总称","汉武帝大设鱼龙曼衍之戏接使臣","中国古代杂技与戏曲表演的重要源头"],"mem":"“汉武平乐观百戏，鱼龙曼衍宴西蕃”。角抵杂技魔术大荟萃，戏曲杂技源头。","mix":"百戏在汉代包括角抵戏（早期带有剧情的表演形式，如《东海黄公》）；隋唐后俗称“散乐”；与周代典雅庄重的“雅乐”相对立。","mcq":[{"q":"汉武帝时期为宴请并夸示西域各国使节，在长安平乐观盛大举行的宫廷百戏表演被称为","o":["《霓裳羽衣》","《东海黄公》","《鱼龙漫衍》","《大韶之乐》"],"a":2,"w":"《汉书》记载汉武帝设“鱼龙漫衍之戏”，角抵百戏大盛以夸示西域。"}],"rel":[{"t":"周代六代乐舞","n":"雅乐与百戏散乐对照"},{"t":"皮影戏与木偶戏","n":"百戏杂耍演变戏偶"},{"t":"京剧四功五法","n":"戏曲武功身段源于百戏"}],"exam":[]},{"id":"a05-085","t":"舞剧《丝路花雨》","cid":"05g","p":2,"kind":"作品","alias":["丝路花雨","反弹琵琶舞"],"one":"1979年甘肃省歌舞团据敦煌壁画创作的民族舞剧。","ans":"《丝路花雨》是**甘肃省歌舞团1979年创作的大型民族舞剧**，以唐代丝绸之路为背景，叙述画工神笔张、女儿英娘与波斯商人伊努斯的故事。编导从**敦煌壁画**的乐舞形象中取材，创造出**“反弹琵琶”**舞姿，把壁画上的静态造型变成动作。该剧在国内外演出多年，是**敦煌舞**风格的开创之作，使敦煌艺术走向舞台。","pts":["1979年甘肃省歌舞团创作","取材敦煌壁画，反弹琵琶","神笔张、英娘、伊努斯"],"mem":"画面：英娘背着琵琶，反手弹奏，脚下旋转，背景是敦煌壁画。一句话：壁画活起来，就是《丝路花雨》。","mix":"《丝路花雨》是舞剧，不是电影或戏曲；“反弹琵琶”是舞姿，不是乐器演奏技法。","mcq":[{"q":"舞剧《丝路花雨》中著名的舞姿是","o":["反弹琵琶","胡旋","剑器","折腰"],"a":0,"w":"据敦煌壁画创造的“反弹琵琶”是该剧标志。"}],"rel":[{"t":"敦煌壁画","n":"创作来源"},{"t":"唐代健舞与软舞：胡旋、胡腾、剑器","n":"唐代乐舞背景"},{"t":"音乐舞蹈史诗《东方红》","n":"当代大型歌舞对照"},{"t":"中国四大石窟","n":"莫高窟所属"}],"more":"主要人物：画工神笔张、女儿英娘、波斯商人伊努斯。","exam":[]},{"id":"a05-086","t":"音乐舞蹈史诗《东方红》","cid":"05g","p":2,"kind":"作品","alias":["东方红史诗","大型音乐舞蹈史诗东方红","《东方红》"],"one":"1964年为国庆15周年创作演出的大型音乐舞蹈史诗。","ans":"《东方红》是**1964年为庆祝中华人民共和国成立15周年创作演出的大型音乐舞蹈史诗**，周恩来亲自领导和指导创作，同年10月在北京人民大会堂首演。全剧以歌舞、朗诵和合唱再现中国共产党领导人民革命的历程，从旧中国的苦难写到新中国成立。它是**红色文艺的代表作**，1965年拍成电影。","pts":["1964年国庆15周年首演","周恩来领导创作，北京人民大会堂","红色文艺代表，1965年拍成电影"],"mem":"年份挂钩：1964年国庆15周年，同年10月16日中国首次原子弹爆炸，同年还有《东方红》，记“1964”这个红色年份。","mix":"歌曲《东方红》曲调源自陕北民歌《骑白马》，与史诗同名；1970年东方红一号卫星上天播放的也是《东方红》乐曲。","mcq":[{"q":"音乐舞蹈史诗《东方红》首演于","o":["1949年","1959年","1969年","1964年"],"a":3,"w":"1964年为国庆15周年创作首演。"}],"rel":[{"t":"东方红一号与中国航天日","n":"同名乐曲上天"},{"t":"《黄河大合唱》","n":"红色音乐名作"},{"t":"民歌体裁：号子、山歌、小调；信天游与花儿","n":"曲调出自信天游"},{"t":"舞剧《丝路花雨》","n":"当代大型舞剧"}],"more":"1964年为国庆15周年创作演出，1965年摄制成电影。","exam":[]},{"id":"a05-087","t":"民族民间舞：秧歌、安塞腰鼓、孔雀舞、锅庄","cid":"05g","p":3,"kind":"常识","alias":["中国民族民间舞","民间舞蹈"],"one":"中国汉族及少数民族最具代表性的四大传统民间舞蹈形态。","ans":"该常识指**中华民族最具代表性的传统民间舞蹈形态**。北方汉族**秧歌**欢快热烈；陕北**安塞腰鼓**气势磅礴展现黄土高原风采；**云南傣族孔雀舞**身姿优美，杨丽萍《雀之灵》名动海内外；**藏族锅庄**圆圈起舞。它们是**国家级非物质文化遗产的璀璨明珠**。","pts":["中华民族传统民间舞蹈代表","北方秧歌欢快，陕北安塞腰鼓雄浑","傣族孔雀舞与藏族锅庄各具风采"],"mem":"“陕北腰鼓北方秧，傣家孔雀藏锅庄”。汉藏傣各显风情，民间非遗明珠。","mix":"孔雀舞属于云南傣族（杨丽萍1986年创作独舞《雀之灵》）；锅庄属于藏族圆圈舞；安塞腰鼓属陕北黄土高原民间舞。","mcq":[{"q":"1986年著名舞蹈家杨丽萍以灵动纯美的手臂动作创作并表演的经典独舞《雀之灵》，取材于哪一民族的民间舞蹈","o":["藏族","苗族","壮族","傣族"],"a":3,"w":"《雀之灵》以云南西双版纳傣族民间传统的孔雀舞为基础创作升华而成。"}],"rel":[{"t":"非物质文化遗产","n":"国家级非遗项目"},{"t":"舞蹈《千手观音》","n":"当代经典舞台舞蹈"},{"t":"唐代健舞与软舞：胡旋、胡腾、剑器","n":"古代与民间舞蹈对照"}],"exam":[]},{"id":"a05-088","t":"舞蹈《千手观音》","cid":"05g","p":3,"kind":"作品","alias":["千手观音舞蹈","邰丽华千手观音"],"one":"张继钢编导、中国残疾人艺术团演出的著名古典舞台佛教群舞。","ans":"《千手观音》是**中国残疾人艺术团表演的古典佛教题材群舞**。作品由**张继钢**编导，听障舞蹈家**邰丽华担任领舞**，21位聋哑演员在手语指引下起舞。舞姿取材自**敦煌千手观音壁画**，在2005年春晚引发轰动，展现了慈悲庄严的人性大美。","pts":["中国残疾人艺术团古典佛教群舞","张继钢编导，聋哑艺术家邰丽华领舞","取材敦煌壁画，2005年春晚轰动全国"],"mem":"“继钢编导丽华领，春晚千手敦煌影”。2005年央视春晚一举成名。","mix":"《千手观音》由张继钢编导、邰丽华领舞（中国残疾人艺术团）；舞剧《丝路花雨》是甘肃省歌舞剧院1979年创作，两部作品均汲取敦煌壁画灵感。","mcq":[{"q":"在2005年央视春晚上震撼全国、由中国残疾人艺术团演出的经典舞蹈《千手观音》的领舞者是","o":["邰丽华","杨丽萍","黄豆豆","刘岩"],"a":0,"w":"著名听障舞蹈家邰丽华担任舞蹈《千手观音》的领舞。"}],"rel":[{"t":"敦煌壁画","n":"舞蹈造型灵感来源"},{"t":"民族民间舞：秧歌、安塞腰鼓、孔雀舞、锅庄","n":"当代舞台舞蹈名作"},{"t":"唐代健舞与软舞：胡旋、胡腾、剑器","n":"古代乐舞艺术源流"}],"exam":[]},{"id":"a05-089","t":"世界三大古老戏剧","cid":"05h","p":1,"kind":"合称","alias":["三大古老戏剧","世界三大古老戏剧"],"one":"古希腊悲喜剧、印度梵剧、中国戏曲。","ans":"世界三大古老戏剧是**对世界上三种最古老戏剧形态的合称**，指**古希腊悲剧和喜剧、古印度梵剧和中国戏曲**。**古希腊戏剧**起源于祭祀酒神狄奥尼索斯的活动，有三大悲剧家；**印度梵剧**用梵语演出，代表作家迦梨陀娑，代表作《沙恭达罗》；**中国戏曲**在宋元时期成熟，综合唱念做打，是三者中**唯一延续至今、仍活跃在舞台上**的。三者共同构成人类戏剧文明的源头。","pts":["古希腊戏剧、梵剧、中国戏曲","希腊起源于酒神祭祀，梵剧用梵语","中国戏曲延续至今"],"members":[["古希腊戏剧","悲剧、喜剧，酒神祭祀，三大悲剧家"],["印度梵剧","梵语，迦梨陀娑《沙恭达罗》"],["中国戏曲","宋元成熟，综合性、虚拟性、程式性"]],"mem":"三个国家按时间：希腊（最早，约前 5 世纪）、印度（公元前后）、中国（宋元成熟）。关键词配对：希腊“悲”、印度“梵”、中国“曲”。别和“世界三大表演体系”混，后者是斯坦尼斯拉夫斯基、布莱希特、梅兰芳。","mix":"“三大古老戏剧”讲戏剧形态，“三大表演体系”讲表演理论，是两组；梵剧代表作家是迦梨陀娑，不是泰戈尔（泰戈尔是近代作家）。","mcq":[{"q":"下列不属于“世界三大古老戏剧”的是","o":["印度梵剧","古希腊悲喜剧","日本能乐","中国戏曲"],"a":2,"w":"三大古老戏剧为希腊、梵剧、中国戏曲。"},{"q":"印度梵剧的代表作是","o":["《牡丹亭》","《沙恭达罗》","《俄狄浦斯王》","《罗摩衍那》"],"a":1,"w":"迦梨陀娑《沙恭达罗》；《罗摩衍那》是史诗。"}],"rel":[{"t":"古希腊三大悲剧家","n":"希腊戏剧代表"},{"t":"《沙恭达罗》","n":"梵剧代表作"},{"t":"戏曲美学特征：综合性、虚拟性、程式性","n":"中国戏曲特征"},{"t":"梅兰芳表演体系","n":"另一组三大，易混"}],"more":"中国戏曲在宋元时期成熟。","exam":[]},{"id":"a05-090","t":"南戏四大声腔","cid":"05h","p":1,"kind":"合称","alias":["四大声腔","海盐腔","余姚腔","弋阳腔","昆山腔"],"one":"明代海盐腔、余姚腔、弋阳腔、昆山腔。","ans":"南戏四大声腔是**明代南戏流传过程中形成的四种主要声腔**，即**海盐腔、余姚腔、弋阳腔、昆山腔**。**海盐腔**产于浙江海盐，**余姚腔**产于浙江余姚，**弋阳腔**产于江西弋阳，**昆山腔**产于江苏昆山。四腔各有地域特色，其中**昆山腔**经魏良辅改革成为“水磨调”，后来居上，称雄剧坛，发展为**昆曲**；弋阳腔流传广泛，对后世地方戏影响很大。四大声腔标志着南戏向传奇的发展。","pts":["海盐、余姚、弋阳、昆山四腔","昆山腔经魏良辅改革成水磨调","昆山腔发展为昆曲，弋阳腔影响地方戏"],"members":[["海盐腔","浙江海盐"],["余姚腔","浙江余姚"],["弋阳腔","江西弋阳，影响地方戏"],["昆山腔","江苏昆山，魏良辅改革，成昆曲"]],"mem":"口诀“海余弋昆”。地名线：浙江两个（海盐、余姚），江西一个（弋阳），江苏一个（昆山）。记忆点：最后胜出的是排在最后的“昆”，所以昆曲后来成为“百戏之祖”。","mix":"四大声腔是明代南戏的声腔，不是京剧的腔调（皮黄）；与“元杂剧四大家”“四大南戏”无关，四大南戏是《荆钗记》《白兔记》《拜月亭》《杀狗记》。","mcq":[{"q":"下列不属于南戏四大声腔的是","o":["海盐腔","弋阳腔","昆山腔","皮黄腔"],"a":3,"w":"皮黄腔是京剧腔调。"},{"q":"经魏良辅改革后发展成昆曲的声腔是","o":["海盐腔","余姚腔","弋阳腔","昆山腔"],"a":3,"w":"昆山腔→水磨调→昆曲。"}],"rel":[{"t":"昆曲","n":"昆山腔的发展"},{"t":"四大南戏","n":"南戏另一组并称"},{"t":"南戏与《琵琶记》","n":"南戏背景"},{"t":"梁辰鱼《浣纱记》","n":"昆腔传奇"}],"more":"四腔产地：浙江海盐、浙江余姚、江西弋阳、江苏昆山。","exam":[]},{"id":"a05-091","t":"梁辰鱼《浣纱记》","cid":"05h","p":3,"kind":"作品","alias":["浣纱记","梁辰鱼浣纱记","吴越春秋"],"one":"明代梁辰鱼所作传奇，第一部将改革后的水磨调搬上舞台的作品。","ans":"《浣纱记》是**明代戏曲家梁辰鱼创作的传奇名作**。剧本以春秋时期**吴越争霸**为背景，借范蠡与西施的爱情串联兴亡。该剧是**历史上第一部用改革后水磨调（昆山腔）谱曲演唱的传奇**，使昆山腔由清唱走上舞台演出，成为**昆曲剧种正式确立的里程碑**。","pts":["明代梁辰鱼所作历史传奇","写吴越争霸与范蠡西施故事","首部水磨调舞台传奇，昆曲确立标志"],"mem":"“梁辰鱼作浣纱记，水磨昆腔上舞台”。范蠡西施泛五湖，昆曲舞台开山之作。","mix":"魏良辅改革昆山腔为“水磨调”（唱腔革新），梁辰鱼创制《浣纱记》（舞台剧目革新）；二者相辅相成开创昆曲繁盛。","mcq":[{"q":"历史上第一部采用魏良辅改革后的“水磨调”（昆山腔）谱写并搬上戏曲舞台的传奇剧作是","o":["汤显祖《牡丹亭》","高濂《玉簪记》","梁辰鱼《浣纱记》","洪昇《长生殿》"],"a":2,"w":"梁辰鱼《浣纱记》推动昆山腔从文人室内清唱正式走向戏曲舞台表演。"}],"rel":[{"t":"昆曲","n":"第一部水磨调舞台传奇"},{"t":"南戏四大声腔","n":"昆山腔所属声腔体系"},{"t":"《牡丹亭》","n":"昆曲传奇登峰造极之作"}],"exam":[]},{"id":"a05-092","t":"花部与雅部","cid":"05h","p":2,"kind":"概念","alias":["花雅之争","花部","雅部","乱弹"],"one":"清乾隆时雅部指昆曲，花部指各地乱弹，花部最终胜出。","ans":"花部与雅部是**清乾隆年间对戏曲两大类声腔的划分**，出自李斗《扬州画舫录》。**雅部指昆山腔（昆曲）**，格调典雅；**花部**又称乱弹，包括京腔、秦腔、弋阳腔、梆子腔、罗罗腔、二黄调等地方戏，通俗热闹。两者的竞争称**“花雅之争”**，结果花部胜出，1790年徽班进京后吸收各腔，逐渐形成**京剧**。","pts":["《扬州画舫录》：雅部=昆山腔","花部=各地乱弹","花部胜出，促成京剧形成"],"mem":"逻辑线：官府文人爱雅部，百姓爱花部，观众用脚投票，花部赢，所以徽班进京后有了京剧。雅部只有一种（昆山腔），花部有六种。","mix":"花部不是花旦的行当，是地方戏的统称；“乱弹”在这里指花部诸腔，不是贬义。","mcq":[{"q":"清代“花雅之争”中，“雅部”指的是","o":["昆山腔","秦腔","弋阳腔","二黄调"],"a":0,"w":"雅部即昆山腔，其余皆属花部。"}],"rel":[{"t":"昆曲","n":"雅部"},{"t":"四大徽班进京","n":"花部胜出的标志"},{"t":"京剧的形成","n":"花雅之争的结果"},{"t":"秦腔与川剧","n":"花部地方戏"}],"more":"李斗《扬州画舫录》（1795年）：雅部即昆山腔，花部为京腔、秦腔、弋阳腔、梆子腔、罗罗腔、二黄调，统谓之乱弹。","exam":[]},{"id":"a05-093","t":"四大徽班进京","cid":"05h","p":1,"kind":"事件","alias":["四大徽班","三庆班","四喜班","和春班","春台班","徽班进京"],"one":"1790 年三庆班为乾隆祝寿进京，后有四喜、和春、春台。","ans":"四大徽班进京是**京剧形成的起点事件**。**乾隆五十五年（1790 年）**，为庆祝乾隆八十寿辰，**三庆班**从安徽进京演出，此后**四喜班、和春班、春台班**陆续入京，合称**“四大徽班”**。徽班在京城与昆曲、秦腔、汉调艺人交流，吸收各家之长，融合成**皮黄腔**，逐步形成**京剧**，史称“花雅之争”中花部取代雅部。三庆班领班人是高朗亭，后来程长庚也是三庆班的领袖。","pts":["1790 年为乾隆八十寿辰进京","三庆、四喜、和春、春台","融合汉调、昆曲、秦腔，催生京剧"],"members":[["三庆班","最先进京，1790 年，高朗亭领班"],["四喜班","随后进京"],["和春班","随后进京"],["春台班","随后进京"]],"mem":"四班名口诀“三庆四喜，和春春台”：前两个带数字，后两个带“春”。时间记 1790 年：乾隆八十寿辰（乾隆生于 1711 年）。因果线：徽班进京，融合汉、昆、秦，催生京剧。","mix":"进京的是徽班，来自安徽，不是京班；四大徽班进京不等于京剧立即形成，京剧要到道光年间才成形；“四大徽班”与“四大名旦”“四大须生”不同。","mcq":[{"q":"下列不属于“四大徽班”的是","o":["四喜班","三庆班","和春班","同春班"],"a":3,"w":"四大徽班为三庆、四喜、和春、春台。"},{"q":"首先进京为乾隆祝寿的徽班是","o":["春台班","三庆班","和春班","四喜班"],"a":1,"w":"1790 年三庆班。"}],"rel":[{"t":"京剧的形成","n":"进京催生京剧"},{"t":"同光十三绝与程长庚","n":"程长庚出自三庆班"},{"t":"昆曲","n":"被取代的雅部"},{"t":"秦腔与川剧","n":"被吸收的秦腔"}],"more":"1790 年为乾隆八十寿辰，三庆班进京。","exam":[]},{"id":"a05-094","t":"西皮二黄（皮黄腔）","cid":"05h","p":2,"kind":"概念","alias":["西皮二黄","皮黄","皮黄腔","西皮","二黄"],"one":"京剧两大主要声腔，西皮源于秦腔，二黄源于徽调。","ans":"西皮二黄是**京剧的两大主要声腔**，合称“皮黄”，京剧也因此旧称皮黄。西皮源于**秦腔**传入湖北后与当地腔调结合的变化，曲调明快、激越；二黄源于**徽调**，曲调平稳、深沉。道光年间湖北汉调艺人进京，与徽班合作，使西皮、二黄合流，是**京剧形成**的音乐基础。老生、青衣等行当均用这两种腔演唱。","pts":["京剧两大声腔，合称皮黄","西皮源秦腔，二黄源徽调","汉调与徽班合流成京剧"],"mem":"配对：西皮=西北秦腔，二黄=安徽徽调（黄山）。口诀“西秦东徽”：西皮来自西边的秦腔，二黄来自东边的徽调。性格：西皮快，二黄慢。","mix":"二黄的来源另有江西宜黄腔之说，通行说法为徽调；昆山腔不属于皮黄腔。","mcq":[{"q":"京剧的两大主要声腔是","o":["昆山腔与弋阳腔","秦腔与梆子","高腔与昆腔","西皮与二黄"],"a":3,"w":"西皮与二黄合称皮黄，是京剧的主要声腔。"}],"rel":[{"t":"京剧的形成","n":"声腔合流的结果"},{"t":"四大徽班进京","n":"带来徽调二黄"},{"t":"秦腔与川剧","n":"西皮的来源"},{"t":"花部与雅部","n":"花部诸腔融合"}],"more":"京剧旧称“皮黄”。","exam":[]},{"id":"a05-095","t":"京剧四功五法","cid":"05h","p":2,"kind":"概念","alias":["四功五法","唱念做打","手眼身法步"],"one":"四功：唱念做打；五法：手眼身法步。","ans":"四功五法是**京剧（戏曲）表演的基本功和基本技法**。**四功**指唱、念、做、打，即演唱、念白、表演和武打；**五法**指手、眼、身、法、步，即手势、眼神、身段、技法和步法。四功偏重表演的四个方面，五法落实到身体各部位的技巧。二者合称是**戏曲演员的基本训练体系**，各行当演员都要兼通。","pts":["四功：唱、念、做、打","五法：手、眼、身、法、步","戏曲演员基本功"],"mem":"口诀“唱念做打，手眼身法步”，四加五。画面：四功是“做什么”，五法是“用哪里”。","mix":"与行当“生旦净丑”区分；四功不是“唱做念舞”；“法”的具体解释各家说法不一，通常指各类程式技法。","mcq":[{"q":"京剧“四功”指的是","o":["手眼身步","唱念做打","生旦净丑","唱做念舞"],"a":1,"w":"四功是唱、念、做、打；手眼身法步是五法。"}],"rel":[{"t":"京剧行当","n":"生旦净丑"},{"t":"戏曲美学特征：综合性、虚拟性、程式性","n":"程式性的体现"},{"t":"梅兰芳","n":"京剧名家"},{"t":"曲艺：相声、评书、苏州评弹","n":"说学逗唱对举"}],"more":"四功：唱、念、做、打；五法：手、眼、身、法、步。","exam":[]},{"id":"a05-096","t":"京剧脸谱","cid":"05h","p":2,"kind":"常识","alias":["脸谱","花脸","净角脸谱"],"one":"净角勾脸：红忠勇，黑刚直，白奸诈，蓝刚强。","ans":"京剧脸谱是**净角和部分丑角面部的勾画**，用色彩和图案表现人物性格与品质。**红色表示忠勇耿直，如关羽；黑色表示刚直威猛，如包拯、张飞；白色表示奸诈多疑，如曹操；蓝色表示刚强桀骜，如窦尔敦**。脸谱主要用于**净行（花脸）**，丑角在鼻梁勾小块白粉。它是戏曲程式化与象征手法的体现。","pts":["勾画净角面部表现性格","红忠勇、黑刚直、白奸诈、蓝刚强","主要用于净行，丑角小花脸"],"mem":"四人四色：关（红）包（黑）曹（白）窦（蓝），“关包曹窦”。性格对应：红忠、黑直、白奸、蓝刚。","mix":"包拯和张飞都是黑脸；金银色多用于神佛鬼怪；生、旦行当只化妆不勾脸谱。","mcq":[{"q":"京剧脸谱中，白色多用来表现","o":["忠勇","刚直","奸诈","神怪"],"a":2,"w":"白脸多表现奸诈多疑，如曹操。"}],"rel":[{"t":"京剧行当","n":"净行"},{"t":"京剧四功五法","n":"表演基本功"},{"t":"《三国演义》人物与情节","n":"关羽、曹操等形象"},{"t":"戏曲美学特征：综合性、虚拟性、程式性","n":"程式化象征手法"}],"more":"净行又分正净（铜锤花脸）、副净（架子花脸）、武净。","exam":[]},{"id":"a05-097","t":"戏曲美学特征：综合性、虚拟性、程式性","cid":"05h","p":2,"kind":"概念","alias":["戏曲三大特征","戏曲综合性","戏曲虚拟性","戏曲程式性"],"one":"戏曲三大美学特征：综合、虚拟、程式，追求写意。","ans":"戏曲美学三大特征是**综合性、虚拟性、程式性**。综合性指戏曲融合文学、音乐、舞蹈、美术、武术杂技，以唱念做打演故事；虚拟性指用动作和象征代替实物，如**以鞭代马、以桨代船**，一桌二椅可变多种场景；程式性指表演有固定规范，如起霸、趟马。这与西方写实的话剧形成对照，体现了**写意**的审美追求。","pts":["综合性：多种艺术融合","虚拟性：以鞭代马、以桨代船","程式性：动作唱腔有固定规范"],"mem":"口诀“综虚程”：综合=大杂烩，虚拟=空手变马，程式=照谱走。三个例子：唱念做打（综合），鞭子当马（虚拟），起霸趟马（程式）。","mix":"戏曲重写意，话剧重写实；虚拟性不等于随意，同样遵守程式。","mcq":[{"q":"“以鞭代马、以桨代船”体现了戏曲的","o":["虚拟性","综合性","程式性","写实性"],"a":0,"w":"用动作和道具象征实物，是虚拟性的典型。"}],"rel":[{"t":"京剧四功五法","n":"综合表演手段"},{"t":"梅兰芳表演体系","n":"写意体系"},{"t":"世界三大表演体系","n":"与斯坦尼、布莱希特对照"},{"t":"王国维《宋元戏曲史》","n":"“以歌舞演故事”"}],"more":"王国维《宋元戏曲史》：戏曲者，以歌舞演故事也。","exam":[]},{"id":"a05-098","t":"梅兰芳","cid":"05h","p":1,"kind":"人物","alias":["梅畹华","梅派","梅郎"],"one":"京剧表演艺术大师，梅派创始人，四大名旦之首。","ans":"梅兰芳（1894–1961），**京剧表演艺术家**，北京人，**四大名旦之首**，**梅派创始人**。他以旦角见长，融合青衣、花旦、刀马旦，发展出“花衫”表演，代表作有**《贵妃醉酒》《霸王别姬》《穆桂英挂帅》**。1919 年访日，**1930 年访美，1935 年访苏**，在苏联与斯坦尼斯拉夫斯基、布莱希特交流，使京剧走向世界，其表演体系被视为**世界三大表演体系**之一。抗战期间蓄须明志，拒绝为日伪演出，新中国成立后任中国京剧院院长。","pts":["梅派创始人，四大名旦之首","《贵妃醉酒》《霸王别姬》《穆桂英挂帅》","1919 访日、1930 访美、1935 访苏"],"mem":"作品三件套：贵、霸、穆（贵妃醉酒、霸王别姬、穆桂英挂帅）。出访三件套：19 日、30 美、35 苏，按“日、美、苏”顺序连着记。人格线：抗战蓄须明志，是“戏德”与“国格”的象征。","mix":"梅兰芳是男演员，演旦角；四大名旦还有程砚秋、尚小云、荀慧生；梅兰芳的儿子梅葆玖也是京剧演员，不要混。","mcq":[{"q":"梅兰芳的代表作是","o":["《红娘》","《失空斩》","《贵妃醉酒》","《锁麟囊》"],"a":2,"w":"《锁麟囊》程砚秋，《红娘》荀慧生，《失空斩》为老生戏。"},{"q":"梅兰芳访问美国的年份是","o":["1956","1935","1919","1930"],"a":3,"w":"1930 年访美，1935 年访苏。"}],"rel":[{"t":"京剧四大名旦","n":"四大名旦之首"},{"t":"梅兰芳表演体系","n":"三大表演体系之一"},{"t":"斯坦尼斯拉夫斯基","n":"访苏时交流"},{"t":"布莱希特","n":"访苏时受其观看"}],"more":"作品：《贵妃醉酒》《霸王别姬》《穆桂英挂帅》《天女散花》《宇宙锋》。","exam":[]},{"id":"a05-099","t":"四大须生","cid":"05h","p":2,"kind":"合称","alias":["前四大须生","后四大须生"],"one":"前：余言高马；后：马谭杨奚，京剧老生名家。","ans":"四大须生是**京剧老生行当中四位名家的合称**，常见有前后两说。**前四大须生**为**余叔岩、言菊朋、高庆奎、马连良**，活跃于20世纪二三十年代；**后四大须生**为**马连良、谭富英、杨宝森、奚啸伯**，活跃于四十年代。马连良两榜皆在，形成马派。须生即老生，与**四大名旦**同为京剧鼎盛期的标志。","pts":["前：余叔岩、言菊朋、高庆奎、马连良","后：马连良、谭富英、杨宝森、奚啸伯","须生=老生，与四大名旦对举"],"members":[["余叔岩","前四大须生；余派创始人，师谭鑫培"],["言菊朋","前四大须生；言派"],["高庆奎","前四大须生；高派"],["马连良","前后两榜皆入选；马派，《借东风》《甘露寺》"],["谭富英","后四大须生；谭鑫培之孙，《定军山》"],["杨宝森","后四大须生；杨派，唱腔低回沉郁"],["奚啸伯","后四大须生；奚派"]],"mem":"两句口诀：前“余言高马”，后“马谭杨奚”，马连良是两句之间的桥。四大名旦“梅尚程荀”是旦角，四大须生是老生，别串行。","mix":"四大名旦（梅兰芳、尚小云、程砚秋、荀慧生）是旦角；四大须生是老生，且有前后两说，选择题多考“哪位不属于”。","mcq":[{"q":"下列人物不属于“后四大须生”的是","o":["谭富英","杨宝森","奚啸伯","余叔岩"],"a":3,"w":"余叔岩属前四大须生；后四大须生是马、谭、杨、奚。"}],"rel":[{"t":"京剧四大名旦","n":"旦角对举"},{"t":"京剧行当","n":"老生行当"},{"t":"同光十三绝与程长庚","n":"老生前辈"},{"t":"京剧的形成","n":"鼎盛期的名家"}],"more":"须生即老生。","exam":[]},{"id":"a05-100","t":"四小名旦","cid":"05h","p":3,"kind":"合称","alias":["京剧四小名旦"],"one":"1940年评选出的四位京剧旦角青年名家：李世芳、张君秋、毛世来、宋德珠。","ans":"四小名旦指**1940年北京评选出的四位京剧旦角名家**。成员包括**李世芳、张君秋、毛世来、宋德珠**。李世芳学梅，张君秋创“张派”青衣，毛世来工花旦，宋德珠创宋派武旦。四人承接四大名旦辉煌，是**京剧鼎盛期的青年中坚力量**。","pts":["1940年北京评选四位京剧旦角","李世芳、张君秋、毛世来、宋德珠","张君秋创张派青衣，承接四大名旦"],"mem":"“李张毛宋四小旦，君秋张派最流传”。李世芳、张君秋、毛世来、宋德珠。","mix":"四大名旦（1927年评）：梅兰芳、尚小云、程砚秋、荀慧生；四小名旦（1940年评）：李世芳、张君秋、毛世来、宋德珠。","mcq":[{"q":"1940年评选出的京剧“四小名旦”中，后来独立开创“张派”青衣艺术大师的是","o":["李世芳","毛世来","宋德珠","张君秋"],"a":3,"w":"张君秋综合梅派、程派等所长创立“张派”青衣，传人弟子众多。"}],"rel":[{"t":"京剧四大名旦","n":"前代旦角大师合称"},{"t":"京剧行当","n":"旦角行当分类体系"},{"t":"梅兰芳","n":"李世芳宗师梅派"}],"members":[["李世芳","工青衣，宗梅派艺术，被誉为“小梅兰芳”，代表作《霸王别姬》"],["张君秋","工青衣，创立刚柔相济的京剧“张派”艺术，代表作《望江亭》《诗文会》"],["毛世来","工花旦、筱派花旦名家，表演娇俏灵动，代表作《豆汁记》"],["宋德珠","工刀马旦与武旦，创立开碑立派的“宋派”武旦艺术，代表作《杨排风》"]],"exam":[]},{"id":"a05-101","t":"同光十三绝与程长庚","cid":"05h","p":3,"kind":"合称","alias":["同光十三绝","程长庚","沈蓉圃同光十三绝"],"one":"清沈蓉圃所绘同治光绪年间13位京昆名伶画卷，程长庚居首。","ans":"《同光十三绝》是**清末沈蓉圃所绘同治光绪年间13位京昆名伶画卷**，藏故宫博物院。画中涵盖生旦丑各行，徽班领袖**程长庚居首，被尊为“京剧鼻祖”**；亦有梅巧玲、谭鑫培等名角。该作生动记录了**京剧形成时期的舞台面貌与奠基人物**。","pts":["沈蓉圃绘同光年间13位京昆名伶","徽班领袖程长庚被称为京剧鼻祖","现藏故宫，记录京剧奠基期风貌"],"mem":"“同光十三沈蓉圃，长庚鼻祖老生魁”。梅巧玲谭鑫培在列，京剧奠基盛世图。","mix":"程长庚与张二奎、余三胜并称早期京剧“老生三鼎甲”，程长庚居首且被尊为“京剧鼻祖”；画师为清末沈蓉圃。","mcq":[{"q":"在清代画师沈蓉圃所绘《同光十三绝》中，位列徽班三庆班领袖、被尊为“京剧鼻祖”的著名演员是","o":["程长庚","谭鑫培","梅巧玲","余三胜"],"a":0,"w":"程长庚被公认为京剧鼻祖，在《同光十三绝》中饰演《群英会》鲁肃。"}],"rel":[{"t":"京剧的形成","n":"同光十三绝所处时期"},{"t":"四大徽班进京","n":"程长庚执掌三庆徽班"},{"t":"梅兰芳","n":"画中梅巧玲为梅兰芳祖父"}],"members":[["程长庚","老生之首，徽班三庆班班主，被誉为“京剧鼻祖”，画中饰《群英会》鲁肃"],["卢胜奎","老生名家，兼长剧作编创，画中饰《战北原》诸葛亮"],["张胜奎","老生名家，擅衰派老生，画中饰《一捧雪》莫成"],["杨月楼","武生名家，杨小楼之父，画中饰《四郎探母》杨延辉"],["谭鑫培","武生与老生泰斗，谭派创始人，画中饰《恶虎村》黄天霸"],["徐小香","小生泰斗，世称“活周瑜”，画中饰《群英会》周瑜"],["梅巧玲","旦角名家，梅兰芳祖父，画中饰《雁门关》萧太后"],["时小福","旦角名家，工青衣，画中饰《桑园会》罗敷"],["余紫云","旦角名家，工青衣花旦，画中饰《彩楼配》王宝钏"],["朱莲芬","旦角名家，兼善昆旦与诗画，画中饰《玉簪记》陈妙常"],["郝兰田","老旦奠基人，开创京剧老旦独立行当，画中饰《行路训子》康氏"],["刘赶三","丑角泰斗，擅白面工丑，画中饰《探亲家》乡下妈妈"],["杨鸣玉","昆丑名家，名震京朝，画中饰《思志诚》闵天亮"]],"exam":[]},{"id":"a05-103","t":"豫剧与常香玉","cid":"05h","p":3,"kind":"概念","alias":["豫剧","河南梆子","常香玉"],"one":"中国五大戏曲剧种之一豫剧，及常派创始人常香玉大师。","ans":"豫剧是**中国五大戏曲剧种之一**，旧称**河南梆子**，唱腔激昂高亢、质朴生动。**常香玉是豫剧大师、常派创始人**，代表作有《花木兰》“谁说女子不如男”与《拷红》。抗美援朝时她**义演捐献战斗机**，是人民艺术家的光辉典范，极大扩大了豫剧影响。","pts":["豫剧旧称河南梆子，五大剧种之一","常香玉创立常派，代表作花木兰","抗美援朝义演捐献香玉剧社号飞机"],"mem":"“河南梆子唱豫剧，香玉木兰捐战机”。五大剧种激昂高亢，花木兰名扬天下。","mix":"中国五大剧种为京剧、越剧、黄梅戏、评剧、豫剧；常香玉代表作《花木兰》名段是“刘大哥讲话理太偏，谁说女子不如男”。","mcq":[{"q":"以《花木兰》中“谁说女子不如男”唱段脍炙人口，并在抗美援朝期间义演捐献战斗机的豫剧大师是","o":["新凤霞","常香玉","严凤英","袁雪芬"],"a":1,"w":"常香玉是著名豫剧表演艺术家，抗美援朝时率剧社义演捐献“香玉剧社号”战斗机。"}],"rel":[{"t":"评剧","n":"同列中国五大剧种"},{"t":"越剧与黄梅戏","n":"中国五大地方戏曲剧种"},{"t":"秦腔与川剧","n":"北方梆子声腔渊源"}],"exam":[]},{"id":"a05-104","t":"评剧","cid":"05h","p":3,"kind":"概念","alias":["评戏","唐山落子","蹦蹦戏"],"one":"中国五大戏曲剧种之一，源于冀东民间说唱莲花落。","ans":"评剧是**中国五大戏曲剧种之一**，广泛流行于华北与东北。它由**冀东民间说唱“莲花落”**演变而来，成兆才为其早期奠基人。唱腔通俗平易、吐字清爽，长于反映现实生活。**著名演员新凤霞**主演的**《刘巧儿》《花为媒》**深入人心，具有广泛群众基础。","pts":["中国五大戏曲剧种之一，流行北方","起源于冀东民间说唱莲花落","新凤霞主演刘巧儿、花为媒等杰作"],"mem":"“冀东莲花落演评剧，新凤霞唱刘巧儿”。吐字清晰通俗易懂，北方五大剧种。","mix":"评剧起源于冀东莲花落（流行于华北东北），注意不要误写为“京剧”或与“评弹”（苏州说唱）混淆。","mcq":[{"q":"中国五大戏曲剧种之一的评剧，其前身源于河北冀东地区的民间说唱艺术","o":["二人转","木鱼书","莲花落","凤阳花鼓"],"a":2,"w":"评剧是由河北滦县一带的民间说唱“莲花落”（对口落子）吸收蹦蹦戏演变而成。"}],"rel":[{"t":"豫剧与常香玉","n":"同列中国五大剧种"},{"t":"越剧与黄梅戏","n":"同列中国五大剧种"},{"t":"京剧的形成","n":"中国戏曲代表剧种"}],"exam":[]},{"id":"a05-105","t":"粤剧","cid":"05h","p":2,"kind":"概念","alias":["广东大戏","红线女","帝女花"],"one":"粤语戏曲，2009年入选人类非遗代表作名录。","ans":"粤剧是**流行于广东、广西、香港、澳门及海外华人社区的地方戏曲**，以粤方言（广州话）演唱，主要唱腔为梆子和二黄（梆黄）。它形成于明清时期，近代吸收话剧、电影等元素，名家有**红线女、马师曾、任剑辉**。代表剧目有唐涤生编剧的**《帝女花》**，红线女的《关汉卿》也很知名。2009年粤剧列入**联合国教科文组织人类非物质文化遗产代表作名录**。","pts":["粤方言演唱，梆黄唱腔","红线女、马师曾，《帝女花》","2009年入选人类非遗"],"mem":"年份挂钩：2009年粤剧与花儿同年入选非遗（昆曲2001、古琴2003在前）。《帝女花》是唐涤生所作，名字里有“花”。","mix":"潮剧用潮汕话，粤剧用广州话；粤剧是地方戏，不在五大剧种之内；红线女的《关汉卿》写的是元杂剧作家关汉卿。","mcq":[{"q":"粤剧《帝女花》的编剧是","o":["田汉","欧阳予倩","唐涤生","关汉卿"],"a":2,"w":"《帝女花》为唐涤生编剧，任剑辉、白雪仙主演版本最著名。"}],"rel":[{"t":"人类非遗代表作中国项目","n":"2009年入选"},{"t":"昆曲","n":"同为非遗戏曲"},{"t":"地方戏五大剧种","n":"同属地方戏范畴"},{"t":"关汉卿","n":"红线女演《关汉卿》"}],"more":"粤剧艺术家：红线女、马师曾、任剑辉。","exam":[]},{"id":"a05-106","t":"秦腔与川剧","cid":"05h","p":3,"kind":"概念","alias":["秦腔","川剧","陕西梆子","川戏"],"one":"西北梆子腔鼻祖秦腔与西南“五腔共和”、变脸绝技川剧。","ans":"秦腔与川剧是**中国西北与西南两大代表性古老地方剧种**。**秦腔是梆子腔鼻祖**，以枣木梆子击节，唱腔慷慨激昂、苍凉高亢；川剧流行于巴蜀，融汇高腔等形成“**五腔共和**”，以**“变脸”“吐火”绝技**蜚声中外。二者是中华戏剧百花园的地域瑰宝。","pts":["秦腔为梆子腔鼻祖，高亢苍凉","川剧融合五腔，以变脸吐火闻名","西北与西南古老戏曲地域代表"],"mem":"“秦腔梆子吼西北，川剧变脸吐火神”。秦腔慷慨悲壮，川剧五腔共和。","mix":"秦腔是梆子腔鼻祖（以硬木梆子击节）；川剧以变脸、吐火及高腔帮腔为鲜明特色，属于“五腔共和”剧种。","mcq":[{"q":"被公认为中国戏曲“梆子腔”的源头鼻祖、唱腔以慷慨悲凉著称的地方戏曲剧种是","o":["川剧","豫剧","晋剧","秦腔"],"a":3,"w":"秦腔起源于古代西秦腔，是全国各种梆子腔剧种的源头鼻祖。"}],"rel":[{"t":"豫剧与常香玉","n":"同属梆子声腔体系"},{"t":"昆曲","n":"川剧五腔共和含昆腔"},{"t":"南戏四大声腔","n":"中国戏曲声腔流变"}],"exam":[]},{"id":"a05-107","t":"曲艺：相声、评书、苏州评弹","cid":"05h","p":2,"kind":"概念","alias":["曲艺","相声","评书","苏州评弹","评弹","说学逗唱"],"one":"以说唱为主的民间表演艺术；评弹是评话与弹词合称。","ans":"曲艺是**以说唱为主要手段的民间表演艺术**，相声、评书、苏州评弹是其代表。**相声**讲究**说、学、逗、唱**四门功夫，形成于北京、天津一带，以幽默讽刺见长；**评书**以说为主，一人一桌一扇一醒木；**苏州评弹**是评话与弹词的合称，用苏州话演出，评话只说，弹词以三弦、琵琶伴奏说唱。","pts":["相声：说学逗唱","评书：以说为主","评弹=评话+弹词，苏州话"],"mem":"评弹口诀：评话说“大书”（金戈铁马），弹词弹“小书”（儿女情长）。相声“说学逗唱”，对照戏曲“唱念做打”。","mix":"评书流行北方，评弹流行江浙沪；评书不用乐器，弹词用三弦、琵琶。","mcq":[{"q":"苏州评弹由哪两种曲艺组成","o":["评话与弹词","评书与相声","弹词与鼓词","评话与快板"],"a":0,"w":"评弹是评话与弹词的合称。"}],"rel":[{"t":"京剧四功五法","n":"唱念做打对说学逗唱"},{"t":"皮影戏与木偶戏","n":"同为民间表演艺术"},{"t":"地方戏五大剧种","n":"戏曲与曲艺对举"},{"t":"《三国演义》","n":"评书评话常演题材"}],"more":"弹词名篇：《珍珠塔》《玉蜻蜓》《三笑》。","exam":[]},{"id":"a05-108","t":"皮影戏与木偶戏","cid":"05h","p":3,"kind":"概念","alias":["皮影与木偶","皮影戏","木偶戏","傀儡戏"],"one":"借光透影的皮影与刻木弄影的木偶，中国古老的傀儡戏偶艺术。","ans":"该概念指**中国民间两大传统傀儡戏偶艺术**。皮影戏以兽皮雕影借灯光透幕表演，**2011年“中国皮影戏”列入人类非遗**；木偶戏古称“**傀儡戏**”，含提线、杖头、布袋等类。它们集造型与戏曲于一体，是**中国戏剧演进的古老活化石**。","pts":["中国古代民间傀儡戏偶艺术","中国皮影戏2011年列入人类非遗","木偶戏古称傀儡戏，有提线布袋等类"],"mem":"“隔帐陈百态皮影戏，提线掌乾坤木偶身”。2011年皮影戏列入非遗。","mix":"皮影戏俗称“影子戏”（2011年入选人类非遗）；木偶戏古称“傀儡戏”（分提线、杖头、布袋等）；二者属于戏偶表演艺术。","mcq":[{"q":"以兽皮雕制人物剪影、借光透幕说唱表演，于2011年列入联合国人类非遗名录的古老艺术是","o":["中国皮影戏","中国剪纸","木偶戏","皮黄戏"],"a":0,"w":"2011年“中国皮影戏”被联合国教科文组织列入人类非物质文化遗产名录。"}],"rel":[{"t":"人类非遗代表作中国项目","n":"皮影戏入选人类非遗"},{"t":"汉代百戏","n":"戏偶艺术源自百戏"},{"t":"京剧脸谱","n":"民间造型艺术相通"}],"exam":[]},{"id":"a05-110","t":"中国古建筑屋顶等级","cid":"05i","p":2,"kind":"常识","alias":["屋顶等级","庑殿顶","歇山顶","悬山顶","硬山顶","重檐"],"one":"重檐庑殿顶最高，依次重檐歇山、庑殿、歇山、悬山、硬山。","ans":"中国古建筑屋顶按等级由高到低，最高为**重檐庑殿顶**，如故宫太和殿；其次是**重檐歇山顶**，如天安门城楼，再依次为单檐庑殿顶、单檐歇山顶、**悬山顶、硬山顶**。攒尖顶、卷棚顶多用于亭榭园林。屋顶样式、间数、琉璃瓦颜色（黄色最尊）都服务于**礼制等级**。","pts":["重檐庑殿顶最高，如太和殿","重檐歇山次之，如天安门","悬山、硬山等级较低"],"mem":"口诀自编：“重庑重歇，单庑单歇，悬山硬山”，重檐在前，庑殿压歇山。画面：太和殿（重庑）在最高处，天安门（重歇）次之。","mix":"庑殿四面坡，歇山有九脊；悬山屋面悬出山墙，硬山不出；攒尖是亭子和天坛祈年殿常用，不进这条等级线。","mcq":[{"q":"下列屋顶形式中等级最高的是","o":["重檐歇山顶","重檐庑殿顶","单檐庑殿顶","硬山顶"],"a":1,"w":"重檐庑殿顶为最高等级，如太和殿。"}],"rel":[{"t":"中国古代三大殿","n":"太和殿等"},{"t":"斗拱与榫卯","n":"同为木构要素"},{"t":"《营造法式》","n":"建筑官方规范"},{"t":"天坛","n":"圆形攒尖屋顶"}],"more":"太和殿为重檐庑殿顶，天安门城楼为重檐歇山顶。","exam":[]},{"id":"a05-111","t":"斗拱与榫卯","cid":"05i","p":2,"kind":"概念","alias":["斗拱","斗栱","榫卯","榫卯结构"],"one":"斗拱承重挑檐也是等级标志；榫卯凹凸咬合不用钉。","ans":"斗拱与榫卯是**中国木构建筑的两项核心技术**。**斗拱**由斗、拱等构件层叠而成，位于柱与梁枋之间，既承重又使屋檐挑出，唐宋时尺度大，明清趋小，也是**等级标志**。**榫卯**以凸出的榫与凹进的卯咬合连接，不用钉子，节点有一定韧性，利于抗震，河姆渡遗址已见榫卯木构。两者使中国古建筑形成**以木为主的柔性结构**体系。","pts":["斗拱承重挑檐，等级标志","榫卯凹凸咬合，不用钉","木构抗震，河姆渡已见榫卯"],"mem":"画面：斗拱是层层叠起的托盘，把屋檐托出去；榫是凸头，卯是凹眼，一插就咬住。口诀“斗拱托檐，榫卯咬合”。","mix":"榫是凸出部分，卯是凹进部分；斗拱在唐宋结构作用大，明清趋于装饰化。","mcq":[{"q":"榫卯结构中，凹进的部分称为","o":["榫","拱","卯","斗"],"a":2,"w":"凸出为榫，凹进为卯。"}],"rel":[{"t":"应县木塔","n":"斗拱榫卯的实例"},{"t":"中国古建筑屋顶等级","n":"同属木构常识"},{"t":"《营造法式》","n":"称斗拱为铺作"},{"t":"唐代木构：南禅寺与佛光寺","n":"唐代斗拱雄大"}],"more":"斗拱又写作“斗栱”。","exam":[]},{"id":"a05-112","t":"《营造法式》","cid":"05i","p":1,"kind":"作品","alias":["营造法式","李诫"],"one":"北宋李诫编，1103 年刊行，中国第一部官方建筑设计施工规范。","ans":"《营造法式》是**北宋官方颁行的建筑设计与施工专书**，由**将作监李诫**奉敕编修，**1103 年刊行**，全书 34 卷。内容包括**制度、功限、料例、图样**，规定了**以“材”为模数的材份制**，把房屋构件分为八等材，是**中国古代最完整的建筑技术典籍**，也是**第一部官方建筑设计施工规范**。20 世纪**梁思成**以现代方法研究此书，著有《营造法式注释》。它是研究宋代及以前木构建筑的基本文献。","pts":["北宋李诫编，1103 年刊行","制度、功限、料例、图样，材份制","第一部官方建筑设计施工规范，梁思成研究"],"mem":"数字线：1103 年刊行，34 卷，8 等材。人物线：李诫编、梁思成注。和清代《工程做法则例》对比：宋有《营造法式》，清有《工程做法则例》，一宋一清，都是官方规范。","mix":"《营造法式》是北宋官方规范，计成《园冶》是明末造园专著，一官一私、一建一园；作者李诫不是梁思成，梁思成是研究者。","mcq":[{"q":"《营造法式》的编撰者是","o":["计成","沈括","李诫","梁思成"],"a":2,"w":"北宋将作监李诫；梁思成是现代研究者。"},{"q":"关于《营造法式》，下列说法正确的是","o":["北宋官方建筑规范","清代工程做法","明代私人造园著作","元代营建手册"],"a":0,"w":"北宋官方颁行的建筑设计施工规范。"}],"rel":[{"t":"梁思成与林徽因","n":"现代研究者"},{"t":"斗拱与榫卯","n":"木构核心技术"},{"t":"中国古建筑屋顶等级","n":"建筑等级制度"},{"t":"《园冶》","n":"造园专著对举"}],"more":"梁思成《〈营造法式〉注释》。1103 年刊行。","exam":[]},{"id":"a05-113","t":"《园冶》","cid":"05i","p":2,"kind":"作品","alias":["园冶","计成","虽由人作宛自天开"],"one":"明末计成著，中国第一部园林艺术专著。","ans":"《园冶》是**明末计成所著的造园专著**，约成书于崇祯四年（1631），共三卷，被视为**中国第一部系统的园林艺术理论著作**。计成是江苏吴江人，书中分兴造论、园说、相地、立基、掇山、借景等篇，提出**“虽由人作，宛自天开”**的造园标准和**“巧于因借，精在体宜”**的原则。该书总结江南园林经验，后传入日本，影响后世造园。","pts":["明末计成著，造园专著","“虽由人作，宛自天开”","“巧于因借，精在体宜”"],"mem":"一句话抓核心：人工造园要像天然生成。年份记崇祯四年（1631）。对比：《营造法式》（宋，李诫）讲建筑，《园冶》（明，计成）讲园林。","mix":"《营造法式》是建筑规范，《园冶》是造园专著；《园冶》在日本称《夺天工》；刊行时间一般认为是崇祯七年（1634）。","mcq":[{"q":"“虽由人作，宛自天开”出自","o":["《园冶》","《营造法式》","《长物志》","《天工开物》"],"a":0,"w":"这是计成《园冶》提出的造园标准。"}],"rel":[{"t":"苏州古典园林","n":"江南园林实例"},{"t":"造园手法：借景、框景、对景","n":"《园冶》总结的手法"},{"t":"《营造法式》","n":"建筑规范对举"},{"t":"中国四大名园","n":"园林代表"}],"more":"虽由人作，宛自天开。｜《园冶·园说》\n巧于因借，精在体宜。｜《园冶·兴造论》","exam":[]},{"id":"a05-114","t":"梁思成与林徽因","cid":"05i","p":2,"kind":"人物","alias":["梁思成","林徽因夫妇","营造学社"],"one":"中国近代建筑学奠基者夫妇，1937年发现佛光寺东大殿。","ans":"梁思成（1901–1972）与林徽因（1904–1955）是**中国近代建筑学的奠基者夫妇**，均留学美国宾夕法尼亚大学。他们在**中国营造学社**从事古建筑调查，**1937年发现五台山佛光寺东大殿**，证明中国仍存唐代木构。梁思成著《中国建筑史》，主张保护北京古城；二人参与**国徽设计**，梁思成并主持**人民英雄纪念碑**的建筑设计工作。","pts":["中国营造学社，古建筑调查","1937年发现佛光寺东大殿","参与国徽设计，梁思成主持人民英雄纪念碑设计"],"mem":"画面：1937年夫妇骑骡子上五台山，在深山里发现唐代的佛光寺。数字串：1937发现，唐大中十一年（857）所建。","mix":"南禅寺（782年）比佛光寺更早，是现存最古老木构，1953年才发现；人民英雄纪念碑的设计是集体工作，梁思成为主要负责人之一。","mcq":[{"q":"1937年梁思成、林徽因等人在五台山发现的唐代木构建筑是","o":["南禅寺","应县木塔","独乐寺","佛光寺东大殿"],"a":3,"w":"佛光寺东大殿由营造学社1937年发现；南禅寺1953年发现。"}],"rel":[{"t":"唐代木构：南禅寺与佛光寺","n":"发现的建筑"},{"t":"《营造法式》","n":"梁思成加以研究"},{"t":"林徽因","n":"建筑学家与诗人"},{"t":"国家象征","n":"参与国徽设计"}],"more":"梁思成著《中国建筑史》，祖籍广东新会，梁启超之子。","exam":[]},{"id":"a05-115","t":"唐代木构：南禅寺与佛光寺","cid":"05i","p":3,"kind":"常识","alias":["南禅寺大殿","佛光寺东大殿","唐代木结构建筑"],"one":"山西五台山保存至今的两座唐代木结构佛殿建筑名作。","ans":"该常识指**山西五台山留存的中国唐代木结构建筑瑰宝**。**南禅寺大殿**建于782年，是**中国现存年代最早的木构建筑**；**佛光寺东大殿**建于857年，1937年由**梁思成与林徽因**考察证实，集唐代建筑、雕塑、壁画、题记四绝于一身。","pts":["五台山唐代木构建筑实物瑰宝","南禅寺大殿建于782年，现存最早","梁思成林徽因发现佛光寺，四绝合一"],"mem":"“五台南禅现存早（782），思成徽因佛光宝（857）”。南禅第一早，佛光集四绝。","mix":"中国现存最早的木构建筑是五台山南禅寺大殿（782年）；佛光寺东大殿（857年）体量更大，由梁思成、林徽因夫妇于1937年发现。","mcq":[{"q":"中国现存年代最早的木结构建筑实物是位于山西五台山的","o":["佛光寺东大殿","南禅寺大殿","应县木塔","独乐寺观音阁"],"a":1,"w":"南禅寺大殿重建于唐建中三年（782年），是中国现存年代最早的木构建筑。"}],"rel":[{"t":"梁思成与林徽因","n":"考察发现佛光寺东大殿"},{"t":"中国古建筑屋顶等级","n":"唐代佛殿大木作规制"},{"t":"《营造法式》","n":"古代木构建筑经典规范"}],"exam":[]},{"id":"a05-116","t":"应县木塔","cid":"05i","p":2,"kind":"常识","alias":["释迦塔","佛宫寺释迦塔","佛宫寺木塔"],"one":"山西应县辽代木塔，世界现存最高最古老的纯木楼阁式塔。","ans":"应县木塔即**山西应县佛宫寺释迦塔**，建于**辽清宁二年（1056年）**，八角形，高约67米，外观五层，内有四个暗层。它是**世界现存最高、最古老的纯木结构楼阁式塔**，全塔以斗拱榫卯相连，历经地震战火仍立至今。1933年梁思成、莫宗江等人曾前往考察，它与意大利比萨斜塔、法国埃菲尔铁塔并称**世界三大奇塔**。","pts":["山西应县佛宫寺释迦塔，辽1056年建","世界现存最高最古老的纯木楼阁式塔","与比萨斜塔、埃菲尔铁塔并称三大奇塔"],"mem":"数字：1056（辽），高67米，外五内九（五层外观加四暗层）。朝代对照：辽应县，唐佛光、南禅，一句话“辽塔唐殿”。","mix":"常被误认为唐代或宋代；是木塔，不是砖塔；南禅寺、佛光寺是唐代殿堂，不是塔。","mcq":[{"q":"应县木塔建于","o":["唐代","辽代","宋代","明代"],"a":1,"w":"辽清宁二年（1056年）。"}],"rel":[{"t":"斗拱与榫卯","n":"木塔核心技术"},{"t":"唐代木构：南禅寺与佛光寺","n":"同为现存木构名例"},{"t":"梁思成与林徽因","n":"曾前往考察"},{"t":"金字塔","n":"世界古建筑对照"}],"more":"全称佛宫寺释迦塔，位于山西朔州应县。","exam":[]},{"id":"a05-117","t":"中国四大古桥","cid":"05i","p":2,"kind":"合称","alias":["四大古桥","赵州桥卢沟桥广济桥洛阳桥"],"one":"赵州桥、卢沟桥、广济桥、洛阳桥。","ans":"中国四大古桥通常指**赵州桥、卢沟桥、广济桥、洛阳桥**。赵州桥在河北赵县，**隋代李春**主持建造，是现存最古老的**单孔敞肩石拱桥**；卢沟桥在北京，**金代**建成，“卢沟晓月”为燕京八景之一，1937年**七七事变**在此爆发；广济桥在广东潮州，启闭式浮桥与石梁桥结合；洛阳桥在福建泉州，**北宋蔡襄**主持，是现存较早的跨海梁式石桥。","pts":["赵州桥、卢沟桥、广济桥、洛阳桥","赵州桥：隋李春，敞肩石拱","洛阳桥：北宋蔡襄"],"members":[["赵州桥","河北赵县；隋代李春；现存最古老的单孔敞肩石拱桥"],["卢沟桥","北京；金代1192年建成；七七事变发生地"],["广济桥","广东潮州，又称湘子桥；启闭式浮桥与梁桥结合"],["洛阳桥","福建泉州，又名万安桥；北宋蔡襄主持"]],"mem":"口诀“赵卢广洛”，对应朝代“隋金宋宋”，地域“河北京粤闽”。北方两座（赵、卢），南方两座（广、洛）。","mix":"洛阳桥在福建泉州，与河南洛阳无关；四大古桥另有不同版本，以通行说法为准。","mcq":[{"q":"下列桥梁中，由北宋蔡襄主持建造的是","o":["赵州桥","卢沟桥","洛阳桥","广济桥"],"a":2,"w":"洛阳桥（万安桥）在泉州，北宋蔡襄主持。"}],"rel":[{"t":"赵州桥","n":"四大古桥之首"},{"t":"应县木塔","n":"同属古建筑常识"},{"t":"《营造法式》","n":"宋代建筑规范"},{"t":"京杭大运河","n":"同为古代水陆工程"}],"more":"卢沟桥1937年七七事变发生地。","exam":[]},{"id":"a05-118","t":"苏州古典园林","cid":"05i","p":2,"kind":"地理","alias":["苏州园林","拙政园","留园","网师园","沧浪亭","狮子林"],"one":"江南私家园林代表，九处列入世界遗产；四大名园沧狮拙留。","ans":"苏州古典园林是**以私家宅园为主的江南园林代表**，有“江南园林甲天下，苏州园林甲江南”之誉。**1997年**拙政园、留园、网师园、环秀山庄列入世界遗产，**2000年**扩展沧浪亭、狮子林、艺圃、耦园、退思园，共九处。**苏州四大名园**为沧浪亭（宋）、狮子林（元）、拙政园（明）、留园（明）。园林讲究**叠石理水、借景、咫尺山林**。","pts":["私家园林，江南园林代表","1997年四处、2000年扩展五处，共九处","四大名园：沧浪亭、狮子林、拙政园、留园"],"mem":"年份：1997（4处）加2000（5处）等于9处。四大名园按朝代“宋元明明”：沧浪亭、狮子林、拙政园、留园，首字“沧狮拙留”。","mix":"“苏州四大名园”与“中国四大名园”（拙政园、留园、颐和园、避暑山庄）只有拙政园、留园重合；退思园在苏州吴江同里。","mcq":[{"q":"苏州四大名园中，始建于宋代的是","o":["沧浪亭","狮子林","拙政园","留园"],"a":0,"w":"沧浪亭宋代始建；狮子林元代，拙政园、留园明代。"}],"rel":[{"t":"中国四大名园","n":"拙政园、留园重合"},{"t":"《园冶》","n":"造园理论"},{"t":"造园手法：借景、框景、对景","n":"园林手法"},{"t":"世界遗产类型","n":"文化遗产实例"}],"more":"沧浪亭取意《楚辞·渔父》“沧浪之水清兮”。","exam":[]},{"id":"a05-119","t":"造园手法：借景、框景、对景","cid":"05i","p":3,"kind":"概念","alias":["中国古典园林理景手法","借景框景对景","造园理景手法"],"one":"中国古典园林营造中组织视线与拓展空间的核心理景手法。","ans":"该概念指**中国传统园林组织空间视觉的核心理景手法**。**借景**纳园外之景于园内，如拙政园借北寺塔，计成倡“**巧于因借**”；**框景**借门窗洞口框取景物如画；**对景**设景物互为视线端点。它们拓展了有限空间，生动达成“**虽由人作，宛自天开**”的意境。","pts":["古典园林组织视线的核心理景手法","借景如借北寺塔，计成倡巧于因借","框景如画，对景呼应，宛自天开"],"mem":"“借景纳远塔，框景如挂画，对景两相望，园冶天开巧”。苏州园林经典手法。","mix":"借景分远借、邻借、仰借、俯借等（计成《园冶》强调“巧于因借，精在体宜”）；框景利用门窗洞口如画框取景；漏景则透过窗棂若隐若现。","mcq":[{"q":"明代计成在园林专著《园冶》中提出“巧于因借，精在体宜”，其中“借景”的典型实例是","o":["网师园殿春簃看芍药","留园冠云峰对景","拙政园倚虹亭远借北寺塔","沧浪亭看水面"],"a":2,"w":"拙政园在园内借城内北寺塔（报恩寺塔）为背景，是中国古典园林“远借”的经典代表。"}],"rel":[{"t":"《园冶》","n":"论述园林借景经典专著"},{"t":"苏州古典园林","n":"理景造景手法集大成"},{"t":"中国四大名亭","n":"园林建筑节点与对景"}],"exam":[]},{"id":"a05-120","t":"天坛","cid":"05i","p":3,"kind":"地理","alias":["北京天坛","天坛公园"],"one":"始建于明永乐十八年的明清皇家祭天建筑群，世界文化遗产。","ans":"天坛是**明清两代帝王祭天祈谷的皇家建筑群**。始建于**明永乐十八年（1420年）**，位于北京。主体有祈年殿、圜丘坛，格局“**北圆南方**”象征天圆地方，具回音壁奇观。**1998年列入世界文化遗产名录**，为中国现存最大古代祭祀建筑群。","pts":["明永乐十八年始建的明清皇家祭天坛庙","祈年殿、圜丘坛，北圆南方象征天圆地方","1998年列入世界文化遗产名录"],"mem":"“永乐十八建天坛，北圆南方祈丰年”。祈年殿圜丘回音壁，1998申遗成功。","mix":"天坛是祭天、祈谷之所（蓝瓦象征天）；地坛在城北祭地；先农坛在城南祭农神；天坛1420年与紫禁城同年建成。","mcq":[{"q":"北京天坛主体建筑格局“北圆南方”，其中明清皇帝在冬至举行祭天大典的露天三层石坛是","o":["祈年殿","皇穹宇","祈谷坛","圜丘坛"],"a":3,"w":"圜丘坛是露天圆形三层汉白玉石坛，为明清两代皇帝冬至举行祭天大典之所。"}],"rel":[{"t":"世界文化遗产","n":"1998年列入世界遗产"},{"t":"中国三大古建筑群","n":"古代大型礼制建筑群"},{"t":"中国古建筑屋顶等级","n":"祈年殿攒尖顶等级"}],"exam":[]},{"id":"a05-121","t":"传统民居","cid":"05i","p":2,"kind":"常识","alias":["四合院","福建土楼","窑洞","徽派建筑","傣家竹楼","民居"],"one":"四合院、窑洞、徽派、土楼、竹楼等地域民居。","ans":"中国传统民居因气候和民族不同而风格各异。**北京四合院**是北方合院式住宅，对称封闭；**陕北窑洞**依黄土崖而建，冬暖夏凉；**徽派建筑**以白墙黛瓦马头墙为特征，西递、宏村2000年入世界遗产；**福建土楼**是客家与闽南人聚居的夯土楼，**2008年**列入世界遗产；**傣家竹楼**是云南傣族的干栏式建筑，下层架空。","pts":["四合院、窑洞、徽派、土楼、竹楼","福建土楼2008年入世界遗产","徽派：白墙黛瓦马头墙"],"mem":"配地区：北（四合院）、西北（窑洞）、皖（徽派）、闽（土楼）、滇（竹楼）。口诀“北合西窑，徽白闽圆，傣楼架空”。","mix":"福建土楼由客家人与闽南人共同建造聚居，圆形最著名；广东开平碉楼2007年入世界遗产；上海石库门是近代里弄住宅，不是传统农村民居。","mcq":[{"q":"2008年列入世界遗产名录的民居建筑是","o":["北京四合院","陕北窑洞","徽州西递宏村","福建土楼"],"a":3,"w":"福建土楼2008年入选；西递宏村2000年入选。"}],"rel":[{"t":"石库门与外滩","n":"上海近代民居"},{"t":"窑洞对与“两个答案”","n":"窑洞的历史事件"},{"t":"世界遗产类型","n":"遗产实例"},{"t":"苏州古典园林","n":"同属建筑文化"}],"more":"广东开平碉楼与村落2007年列入世界遗产；西递、宏村2000年列入。","exam":[]},{"id":"a05-122","t":"中国三大古建筑群","cid":"05i","p":3,"kind":"合称","alias":["三大古建筑群","中国古代三大建筑群"],"one":"北京故宫、曲阜三孔与承德避暑山庄，古代三大古建筑群。","ans":"该合称指**中国古代保存最完整、规模最宏大的三大古典建筑群体**。分别为**北京故宫**、**曲阜三孔**（孔庙、孔府、孔林）与**承德避暑山庄及周围寺庙**。它们分别代表了古代皇权宫殿、儒家礼制与皇家园林建筑的最高峰，**均已入选联合国世界文化遗产名录**。","pts":["中国古代三大规模最宏大建筑群","北京故宫、曲阜三孔、承德避暑山庄","集宫殿、礼制、园林之大成，均列世界遗产"],"mem":"“故宫三孔避暑庄，三大建筑世无双”。宫殿礼制与园林，均列世界文化遗产。","mix":"中国古代三大古建筑群为北京故宫、曲阜三孔、承德避暑山庄及周围寺庙；中国“三大殿”则是太和殿、大成殿、保和殿（或天贶殿）。","mcq":[{"q":"公认的“中国古代三大建筑群”包括北京故宫、曲阜三孔以及","o":["承德避暑山庄及周围寺庙","武当山古建筑群","布达拉宫","西安大雁塔与大慈恩寺"],"a":0,"w":"中国古代三大建筑群指北京故宫、山东曲阜三孔、河北承德避暑山庄及周围寺庙。"}],"rel":[{"t":"三孔（孔庙、孔府、孔林）","n":"三大建筑群成员之一"},{"t":"世界文化遗产","n":"三大建筑群均列入世界遗产"},{"t":"中国古建筑屋顶等级","n":"古建等级规制典范"}],"members":[["北京故宫","明清两代皇宫紫禁城，中国现存规模最大、保存最完整的木构宫殿建筑群"],["曲阜三孔（孔庙、孔府、孔林）","历代祭祀孔子与孔氏后裔生活墓葬的儒家礼制建筑群"],["承德避暑山庄及周围寺庙","清代皇家避暑夏宫与外八庙藏传佛教融合建筑群"]],"exam":[]},{"id":"a05-123","t":"中国四大名亭","cid":"05i","p":3,"kind":"合称","alias":["四大名亭","中国名亭"],"one":"滁州醉翁亭、北京陶然亭、长沙爱晚亭、杭州湖心亭。","ans":"中国四大名亭指**中国古代人文底蕴深厚的四座著名园林名亭**。分别为安徽滁州**醉翁亭**（欧阳修作记）、北京**陶然亭**（白居易诗意）、长沙**爱晚亭**（杜牧诗意）与杭州**湖心亭**（张岱作记）。四亭融景于文，**是中国名篇与古典园林结合的典范**。","pts":["中国古代四座著名人文景观名亭","醉翁亭、陶然亭、爱晚亭、湖心亭","连接欧阳修、白居易、杜牧、张岱名篇"],"mem":"“醉翁陶然爱晚湖，欧白杜张名篇赋”。滁州、北京、长沙、杭州四座名亭。","mix":"醉翁亭在安徽滁州（欧阳修）；陶然亭在北京（白居易诗意）；爱晚亭在湖南长沙岳麓山（杜牧诗意，毕沅改名，毛泽东题额）；湖心亭在杭州西湖（张岱）。","mcq":[{"q":"中国四大名亭中，由清代罗典始建、名字取自杜牧名句“停车坐爱枫林晚”的名亭是","o":["醉翁亭","爱晚亭","陶然亭","湖心亭"],"a":1,"w":"湖南长沙岳麓山的爱晚亭取杜牧《山行》中“停车坐爱枫林晚”之意命名。"}],"rel":[{"t":"欧阳修","n":"欧阳修作醉翁亭记"},{"t":"张岱","n":"张岱作湖心亭看雪"},{"t":"造园手法：借景、框景、对景","n":"园林名亭造景"}],"members":[["醉翁亭","安徽滁州琅琊山，北宋欧阳修作《醉翁亭记》，“醉翁之意不在酒”"],["陶然亭","北京陶然亭公园，清代江藻建，取白居易“更待菊黄家酿熟，共君一醉一陶然”"],["爱晚亭","湖南长沙岳麓山，清代罗典建，取杜牧“停车坐爱枫林晚，霜叶红于二月花”"],["湖心亭","浙江杭州西湖中，明末清初张岱作《湖心亭看雪》闻名"]],"exam":[]},{"id":"d05-001","t":"魏良辅","cid":"05h","p":2,"kind":"人物","alias":["曲圣","昆曲鼻祖","魏尚泉"],"one":"明代戏曲音乐家，革新昆山腔创立“水磨调”，被尊为“曲圣”与昆曲鼻祖。","ans":"魏良辅，号尚泉，**明代嘉靖年间戏曲音乐家**，流寓太仓，被尊为**“曲圣”**与**昆曲鼻祖**。他在明代南戏四大声腔格局下，融汇海盐、弋阳等南腔与北曲之长，历时十年革新旧昆山腔，创制细腻柔婉、讲究吐字行腔的**“水磨调”**，并配以笛、箫、笙、琵琶伴奏。其后**梁辰鱼**据新腔创作首部昆腔传奇**《浣纱记》**，将昆曲推上明清剧坛主流。","pts":["明代戏曲音乐家，尊称“曲圣”、昆曲鼻祖","融南北曲革新昆山腔，创“水磨调”","梁辰鱼据新腔作《浣纱记》使昆曲登上舞台"],"mem":"戏曲双人接力记昆曲诞生：**魏良辅**像“作曲家”磨出**水磨调**，**梁辰鱼**像“编剧”写出**《浣纱记》**，词曲合璧成就“百戏之祖”。","mix":"魏良辅只改音乐声腔不写剧本，第一部用昆腔水磨调搬演的传奇是梁辰鱼《浣纱记》，而非汤显祖《牡丹亭》；明代南戏四大声腔为海盐、余姚、弋阳、昆山腔。","mcq":[{"q":"明代据魏良辅革新后的昆山腔“水磨调”创作的第一部传奇剧本是","o":["汤显祖《牡丹亭》","高明《琵琶记》","梁辰鱼《浣纱记》","洪昇《长生殿》"],"a":2,"w":"魏良辅创昆腔“水磨调”后，梁辰鱼首以新腔创作《浣纱记》，推动昆曲盛行。"}],"rel":[{"t":"昆曲","n":"昆曲声腔革新鼻祖"},{"t":"南戏四大声腔","n":"革新四大声腔中的昆山腔"},{"t":"花雅之争","n":"清代雅部即指昆腔"},{"t":"汤显祖与莎士比亚同年逝世","n":"《牡丹亭》以昆腔传演"}],"exam":[]},{"id":"d05-002","t":"花雅之争","cid":"05h","p":3,"kind":"事件","alias":["花部与雅部之争"],"one":"清乾隆间雅部昆曲与花部地方戏的竞争，花部胜出并促成京剧诞生。","ans":"花雅之争是**清乾隆、嘉庆间“雅部”（昆腔）与“花部”（乱弹，含秦腔、徽调、汉调等地方戏）的舞台竞争**，首载于清人**李斗《扬州画舫录》**。花部凭通俗生动胜出，取代日趋案头化的昆曲，促成1790年**四大徽班进京**与**京剧**诞生。","pts":["清乾隆间雅部（昆曲）与花部（地方戏乱弹）之争","花部胜出，见载《扬州画舫录》，促成京剧形成"],"mem":"记住“雅”和“花”各指谁：**雅**=典雅文人的**昆曲**，**花**=百花齐放的**地方戏（乱弹）**；市民爱看热闹，花部胜出开出“国粹京剧”。","mix":"“花部”并非特指某一个剧种，而是昆腔以外所有地方戏声腔的统称（又称“乱弹”）；花雅之争的结果是花部胜出，而非雅部获胜。","mcq":[{"q":"清代戏曲史“花雅之争”中的“雅部”特指","o":["京剧","秦腔","徽调","昆腔"],"a":3,"w":"清人李斗《扬州画舫录》将昆腔称为“雅部”，将昆腔以外的各地方戏统称“花部”（乱弹）。"}],"rel":[{"t":"昆曲","n":"“雅部”即指昆曲"},{"t":"魏良辅","n":"昆腔水磨调开创者"},{"t":"四大徽班进京","n":"花部胜出后的关键事件"},{"t":"京剧的形成","n":"花雅之争的直接成果"}],"exam":[]},{"id":"d05-003","t":"中国营造学社","cid":"05i","p":3,"kind":"事件","alias":["营造学社"],"one":"1930年朱启钤创办的中国首个现代古建筑学术团体，梁思成、刘敦桢主持。","ans":"中国营造学社是**1930年朱启钤在北平创办的中国首个现代古建筑学术团体**，**梁思成**、**刘敦桢**分掌法式部与文献部。学社开展全国古建田野测绘，1937年发现唐代木构**五台山佛光寺东大殿**，编刊**《中国营造学社汇刊》**，奠定现代建筑史学基础。","pts":["1930年朱启钤创办，梁思成、刘敦桢分掌两部","测绘发现唐代佛光寺，出版《中国营造学社汇刊》"],"mem":"三人分工记学社：**朱启钤**牵头建社（1930），**梁思成**管法式看实物，**刘敦桢**管文献查古书，巅峰战绩是1937年找到唐代**佛光寺**。","mix":"创办人是朱启钤（非梁思成），梁思成、刘敦桢是核心学术主持；学社之名取自北宋李诫建筑典籍《营造法式》（1919年朱启钤发现该书抄本，后促成1920年石印与1925年陶本重刊，由此筹建学社）。","mcq":[{"q":"1930年在北平创办“中国营造学社”并担任社长的是","o":["朱启钤","梁思成","刘敦桢","林徽因"],"a":0,"w":"朱启钤于1930年正式创办中国营造学社并任社长，梁思成、刘敦桢分别任法式部和文献部主任。"}],"rel":[{"t":"梁思成与林徽因","n":"学社核心学术成员"},{"t":"《营造法式》","n":"学社定名与研究源头"},{"t":"唐代木构：南禅寺与佛光寺","n":"1937年测绘发现佛光寺"},{"t":"应县木塔","n":"学社重点测绘的辽代古建"}],"exam":[]},{"id":"d05-004","t":"古琴艺术","cid":"05f","p":2,"kind":"常识","alias":["古琴","七弦琴","瑶琴"],"one":"三千余年历史的七弦弹拨乐器艺术，文人四艺之首，2003年入选人类非遗。","ans":"古琴艺术是中国最古老的弹拨乐器传统，古琴又称**七弦琴**、瑶琴，有三千余年历史，居古代文人**“琴棋书画”四艺之首**。其以独特**“减字谱”**记谱，音色清微淡远，名曲有**《高山流水》《广陵散》《梅花三弄》**等。**2003年11月**，古琴艺术入选联合国教科文组织第二批**“人类口头和非物质遗产代表作”**，是继2001年昆曲后中国第二项入选的非遗。","pts":["又称七弦琴，文人“琴棋书画”四艺之首","用“减字谱”记谱，名曲《高山流水》《广陵散》","2003年入选第二批人类非遗，中国第二项"],"mem":"中国首批非遗时间锚点：**2001昆曲（第1项）→2003古琴（第2项）**，隔两年刚好“一唱一弹”；记古琴抓“七弦、减字谱、高山流水遇知音”。","mix":"莫将古琴与古筝混淆：古琴七弦无柱、用于文人清赏，古筝多弦（常见21弦）有雁柱；古琴入选人类非遗是2003年（第二批），昆曲是2001年（第一批），端午节是2009年。","mcq":[{"q":"2003年入选联合国教科文组织第二批“人类口头和非物质遗产代表作”、成为中国第二项世界级非遗的是","o":["昆曲","古琴艺术","京剧","中国篆刻"],"a":1,"w":"昆曲于2001年首批入选，古琴艺术于2003年第二批入选，为中国第二项。"}],"rel":[{"t":"古琴","n":"乐器本体与构造"},{"t":"中国十大古曲","n":"多首古曲以古琴传世"},{"t":"人类非遗代表作中国项目","n":"2003年中国第二项入选"},{"t":"昆曲","n":"2001年首项入选，合称前两项"}],"exam":[]}],"tables":[{"name":"书法名家与名作","note":"","rows":[["人物","时代","称号或书体","代表作"],["李斯","秦","小篆（秦统一文字）","《泰山刻石》"],["钟繇","三国魏","楷书鼻祖","《宣示表》"],["王羲之","东晋","书圣","《兰亭集序》（天下第一行书）"],["王献之","东晋","与其父并称“二王”","《洛神赋十三行》"],["欧阳询","唐初","欧体（楷书四大家）","《九成宫醴泉铭》"],["颜真卿","唐","颜体，“颜筋柳骨”","楷书《多宝塔碑》，行书《祭侄文稿》（天下第二行书）"],["柳公权","唐","柳体","《玄秘塔碑》"],["张旭、怀素","唐","草书，“颠张醉素”，张旭称“草圣”","怀素《自叙帖》"],["苏轼、黄庭坚、米芾、蔡襄","北宋","宋四家","苏轼《黄州寒食帖》（天下第三行书）"],["宋徽宗赵佶","北宋","瘦金体","《秾芳诗帖》"],["赵孟頫","元","赵体（楷书四大家）","《胆巴碑》"]]},{"name":"绘画名作","note":"","rows":[["作品","作者与时代","内容或要点"],["《洛神赋图》《女史箴图》","东晋顾恺之","现存为摹本；顾恺之称“才绝、画绝、痴绝”"],["《步辇图》","唐阎立本","唐太宗接见吐蕃使者禄东赞"],["《历代帝王图》","唐阎立本","十三位帝王像"],["《送子天王图》","唐吴道子（传）","吴道子被尊为“画圣”"],["《五牛图》","唐韩滉","现存最早的纸本中国画之一"],["《虢国夫人游春图》","唐张萱","宋代摹本传世"],["《韩熙载夜宴图》","五代南唐顾闳中","夜宴场景长卷"],["《清明上河图》","北宋张择端","汴京清明时节风俗长卷"],["《千里江山图》","北宋王希孟","青绿山水，作者十八岁完成"],["《富春山居图》","元黄公望","分为《剩山图》（浙江省博物馆）与《无用师卷》（台北故宫）"],["《墨葡萄图》","明徐渭","大写意花鸟"],["《八骏图》《奔马图》","徐悲鸿","近代以画马著称"]]}]});